# lru.py
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        # OrderedDict maintains insertion order, which we can utilize to track
        # usage order. Moving an item to the end makes it "most recently used".
        # The leftmost item is the "least recently used".
        self._cache: OrderedDict[str, any] = OrderedDict()
        self._capacity = capacity

    def get(self, key, default=None):
        if key in self._cache:
            # If key exists, move it to the end to mark as most recently used
            self._cache.move_to_end(key)
            return self._cache[key]
        return default

    def put(self, key, value):
        if key in self._cache:
            # If key exists, update value and move to end. No eviction needed.
            self._cache[key] = value
            self._cache.move_to_end(key)
            return None

        # If key is new, we need to evict if at capacity
        if len(self._cache) >= self._capacity:
            # Pop the first item (least recently used)
            evicted_key, _ = self._cache.popitem(last=False)
            # Insert the new key
            self._cache[key] = value
            # Note: move_to_end is not strictly necessary here as it's the only insertion,
            # but conceptually it is now the MRU.
        else:
            self._cache[key] = value

        return None

    def __len__(self):
        return len(self._cache)

    def __contains__(self, key):
        return key in self._cache

    def keys(self):
        # Returns keys from least (left) to most (right) recently used
        return list(self._cache.keys())

    def resize(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")

        new_capacity = capacity
        evicted_keys = []

        while len(self._cache) > new_capacity:
            # Pop the least recently used item
            evicted_key, _ = self._cache.popitem(last=False)
            evicted_keys.append(evicted_key)
            new_capacity += 1

        return evicted_keys
