from fractions import Fraction
from typing import List, Tuple, Optional, Iterator

class CalcError(Exception):
    def __init__(self, position: int):
        self.position = position
        super().__init__(f"CalcError at position {position}")

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.pos = 0
        self.length = len(text)
        self.tokens: List[str] = []

    def peek(self) -> Optional[str]:
        if self.pos < self.length:
            return self.text[self.pos]
        return None

    def advance(self) -> Optional[str]:
        if self.pos < self.length:
            ch = self.text[self.pos]
            self.pos += 1
            return ch
        return None

    def skip_whitespace(self):
        while self.peek() and self.peek() in ' \t':
            self.advance()

    def is_number_start(self, ch: str) -> bool:
        return ch.isdigit() or ch == '.'

    def read_number(self) -> str:
        start = self.pos
        has_dot = False

        while self.pos < self.length:
            ch = self.text[self.pos]
            if ch.isdigit():
                self.pos += 1
            elif ch == '.' and not has_dot:
                has_dot = True
                self.pos += 1
            else:
                break

        if not has_dot and self.pos == start:
            raise CalcError(start) # No digits found after start

        # Check if we ended right after a dot without digits
        if not has_dot:
            return "" # Should not happen due to loop logic, but safety check

        # Validate number format
        if has_dot and self.pos == start + 1:
            raise CalcError(start) # .5 case: dot at start
        if not has_dot and self.pos == start:
            raise CalcError(start) # No digits

        return self.text[start:self.pos]

    def tokenize(self):
        while self.pos < self.length:
            self.skip_whitespace()
            if self.pos >= self.length:
                break

            start = self.pos
            ch = self.peek()

            # Try number
            if ch.isdigit() or ch == '.':
                num_str = self.read_number()
                if not num_str:
                    raise CalcError(start)
                self.tokens.append(num_str)
                self.pos += len(num_str)
                continue

            # Try operator or parenthesis
            if ch in '+-*/()':
                self.tokens.append(ch)
                self.pos += 1
                continue

            # Invalid character
            raise CalcError(start)

        # Check for trailing garbage
        if self.pos < self.length:
            # Skip remaining whitespace if any
            while self.pos < self.length and self.text[self.pos] in ' \t':
                self.pos += 1
            if self.pos < self.length:
                raise CalcError(self.pos)

        return self.tokens

class Parser:
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def current(self) -> Optional[str]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected_type: str = None) -> str:
        if self.current() is None:
            return ""

        token = self.current()
        self.pos += 1
        return token

    def is_operator(self, tok: str) -> bool:
        return tok in '+-*/'

    def is_paren(self, tok: str) -> bool:
        return tok == '('

    def parse(self) -> Fraction:
        result = self.parse_additive()

        # Check for trailing garbage
        if self.current() is not None:
            raise CalcError(self.pos)

        return result

    def parse_additive(self) -> Fraction:
        left = self.parse_multiplicative()

        while self.current() in '+-':
            op = self.consume()
            right = self.parse_multiplicative()

            if op == '+':
                left = left + right
            else: # '-'
                left = left - right

        return left

    def parse_multiplicative(self) -> Fraction:
        left = self.parse_unary()

        while self.current() in '*/':
            op = self.consume()
            right = self.parse_unary()

            if op == '*':
                left = left * right
            else: # '/'
                if right == 0:
                    raise CalcError(self.pos - 1) # Position of the /
                left = left / right

        return left

    def parse_unary(self) -> Fraction:
        if self.current() == '-':
            self.consume()
            return -self.parse_unary()
        return self.parse_primary()

    def parse_primary(self) -> Fraction:
        tok = self.current()

        if tok is None:
            raise CalcError(self.pos)

        if tok == '(':
            self.consume() # consume '('
            val = self.parse_additive()
            if self.current() != ')':
                raise CalcError(self.pos)
            self.consume() # consume ')'
            return val

        if self.current() and self.current() == ')':
            # Extra closing paren
            raise CalcError(self.pos)

        if self.current() in '+-':
            # Unary plus is not allowed per spec, but if we see + here it's likely a syntax error
            # However, the spec says "There is no unary plus". 
            # If we have " - (1", that's fine. If we have "(1 +)", that's caught by additive loop.
            # If we have "1 +", caught by additive loop.
            # But if we are in parse_primary and see '+', it means previous op was missing or 
            # it's a trailing garbage like "(1 +".
            # Actually, "1 +" -> parsed as 1, then '+' is left. Handled in parse_additive loop.
            # What about " - + 1"? 
            # Unary '-' consumes, then parse_unary calls parse_primary.
            # parse_primary sees '+'. This is invalid unary.
            # Spec: "There is no unary plus."
            # So if we see + at start of primary, it's a syntax error for unary context.
            # But wait, could it be binary? 
            # Structure: LeftOp RightVal. If LeftOp is consumed, we expect RightVal.
            # So if we see + here, it's unexpected.
            raise CalcError(self.pos)

        # It should be a number
        if not (tok.isdigit() or tok == '.'):
            raise CalcError(self.pos)

        num = self.consume()
        # Parse string to Fraction
        # Since we are in parse_primary, we assume valid number format from lexer
        # Just in case, re-parse or use Fraction directly if safe
        # The lexer ensures valid numbers, so we can trust the string
        try:
            # Handle potential float conversion issues by using Fraction constructor
            # which does exact parsing for .25 etc
            if '.' in num:
                # Split and reconstruct to avoid float conversion
                int_part = num.split('.')[0]
                frac_part = num.split('.')[1]
                # Handle leading zeros or negative signs? Lexer strips '-' already for numbers
                # Actually lexer returns "0.25", "-0.25"? 
                # No, lexer handles '-'. The number token itself won't have '-' inside unless it's a negative number
                # But lexer separates '-' as token.
                # So num is "0.25" or "12.50"
                if not int_part:
                    raise CalcError(self.pos)

                # Fraction(num) works for strings like "0.25" in Python 3.12+?
                # Yes, fractions.Fraction accepts a string representing a float.
                # But to be strictly exact as per spec "converted exactly to a Fraction", 
                # we should avoid float intermediate if possible.
                # However, spec says: "Every number is converted exactly to a Fraction (0.1 is Fraction(1, 10))"
                # Python's Fraction("0.1") -> Fraction(1, 10). This is safe.
                # But "0.3" -> 3/10? No, 3/10. Wait. 
                # 0.1 + 0.2 = 0.3. 
                # If we use float: float("0.1") + float("0.2") = 0.3. Fraction(0.3) -> Fraction(3, 10). Correct.
                # But 0.1 + 0.2 in float is 0.30000000000000004.
                # Python Fraction("0.30000000000000004") would be messy.
                # The spec implies we parse the string representation directly without float conversion.
                # fractions.Fraction("0.1") works perfectly.
                val = Fraction(num)
            else:
                val = Fraction(int(num))

            return val

        except Exception:
            raise CalcError(self.pos)

def evaluate(expr: str) -> Fraction:
    if not expr:
        raise CalcError(0)

    try:
        lexer = Lexer(expr)
        tokens = lexer.tokenize()

        parser = Parser(tokens)
        return parser.parse()
    except CalcError:
        raise
    except Exception as e:
        raise CalcError(0) from e
