from typing import Callable

class TokenBucket:
    def __init__(self, rate: float, capacity: float, clock: Callable[[], float] = None):
        if rate <= 0:
            raise ValueError("rate must be greater than 0")
        if capacity <= 0:
            raise ValueError("capacity must be greater than 0")

        if clock is None:
            clock = time.monotonic

        self._rate = rate
        self._capacity = capacity
        self._tokens = capacity  # Starts full
        self._last_time = clock()

    def _refill(self) -> None:
        """
        Refill tokens based on elapsed time since the last refill check.
        If the clock moved backwards, this does nothing and keeps the previous time reference.
        """
        current_time = clock()

        # If current_time is earlier than or equal to last_time, no time has passed
        if current_time <= self._last_time:
            return

        elapsed = current_time - self._last_time
        tokens_to_add = elapsed * self._rate

        # Cap at capacity
        self._tokens = min(self._tokens + tokens_to_add, self._capacity)
        self._last_time = current_time

    def try_acquire(self, n: int = 1) -> bool:
        if n <= 0:
            raise ValueError("n must be greater than 0")
        if n > self._capacity:
            raise ValueError("n must be at most capacity")

        self._refill()

        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n: int = 1) -> float:
        if n <= 0:
            raise ValueError("n must be greater than 0")
        if n > self._capacity:
            raise ValueError("n must be at most capacity")

        self._refill()

        if self._tokens >= n:
            return 0.0

        tokens_needed = n - self._tokens
        # time = tokens_needed / rate
        return tokens_needed / self._rate

    def available(self) -> float:
        return self._tokens
