Segment = Union[str, int]
Container = dict | list | tuple

# Constant for the wildcard segment
WILDCARD = object()

class PathError(LookupError):
    """Exception raised when a path is invalid or an operation cannot be performed."""
    __slots__ = ('path',)

    def __init__(self, path: str):
        self.path = path
        super().__init__(f"Path '{path}' is invalid or operation failed")


