    """
    Parse a numeric string into an integer, allowing for optional leading '-'.
    """
    if not s:
        raise PathError("Empty index string")

    # Regex for optional minus followed by digits
    if re.match(r'^-?\d+$', s):
        return int(s)
    else:
        raise PathError(f"Invalid index format: {s}")


