    """
    Parse a path string into a list of segments (str, int, or WILDCARD).

    Raises PathError on syntax errors.
    """
    if not isinstance(path, str):
        raise PathError(str(path))

    if not path:
        return []

    segments: list[Union[Segment, WILDCARD]] = []
    pos = 0
    n = len(path)

    while pos < n:
        c = path[pos]

        if c == '"':
            # Parse quoted key: "..."
            pos += 1
            if path[pos] == '"':
                raise PathError(path)

            escaped_chars = []
            i = pos
            while i < n and path[i] != '"':
                if path[i] == '\\':
                    if i + 1 >= n:
                        raise PathError(path)
                    next_c = path[i + 1]
                    if next_c == '"':
                        escaped_chars.append('"')
                        i += 2
                    elif next_c == '\\':
                        escaped_chars.append('\\')
                        i += 2
                    else:
                        raise PathError(path)
                elif path[i] == '.' or path[i] == '[' or path[i] == ']':
                    raise PathError(path)
                else:
                    escaped_chars.append(path[i])
                    i += 1

            if i >= n:
                raise PathError(path)

            if path[i] != '"':
                raise PathError(path)

            key = "".join(escaped_chars)
            if not key:
                raise PathError(path)

            segments.append(key)
            pos = i + 1

        elif c == '*':
            # Check if it's a wildcard segment [*]
            if pos + 1 >= n or path[pos + 1] != '[':
                raise PathError(path)

            if pos + 2 >= n or path[pos + 2] != ']':
                raise PathError(path)

            segments.append(WILDCARD)
            pos += 3

        elif c == '.':
            # Parse name
            if pos + 1 >= n or path[pos + 1] in '.[]':
                raise PathError(path)

            name_start = pos + 1
            while pos + 1 < n and path[pos + 1] not in '.[]':
                pos += 1

            if pos == name_start:
                raise PathError(path)

            name = path[name_start:pos]
            segments.append(name)
            pos += 1

        elif c == '[':
            # Check if it's a wildcard segment [*]
            if pos + 1 >= n or path[pos + 1] != '*':
                # It's a numeric index or quoted key
                if pos + 1 >= n:
                    raise PathError(path)

                if path[pos + 1] == '"':
