"""
Sudoku module for reading, checking, solving, and analyzing puzzles.
Uses only Python 3.12 standard library.
"""

import copy
import re
from typing import Optional, List, Set, Tuple, Dict


def _validate_grid(grid: List[List[int]]) -> None:
    """
    Validates that the grid is 9x9 and contains only integers 0-9.
    Raises ValueError if invalid.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must have 9 rows.")
    for r_idx, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError(f"Row {r_idx} must have 9 cells.")
        for c_idx, cell in enumerate(row):
            if not isinstance(cell, int) or isinstance(cell, bool):
                raise ValueError(f"Cell [{r_idx}, {c_idx}] must be an integer.")
            if cell < 0 or cell > 9:
                raise ValueError(f"Cell [{r_idx}, {c_idx}] must be between 0 and 9, got {cell}.")


def parse(text: str) -> List[List[int]]:
    """
    Reads 81 cells in row-major order from the text.
    Digits 1–9 are givens; 0 and . are empty cells.
    Whitespace is ignored anywhere.
    Raises ValueError if input is invalid or cell count != 81.
    """
    # Remove all whitespace characters
    cleaned_text = re.sub(r'\s+', '', text)

    cells = []
    i = 0
    while i < len(cleaned_text):
        char = cleaned_text[i]
        if char == '.':
            cells.append(0)
        elif char.isdigit():
            d = int(char)
            if d < 1 or d > 9:
                # If '0' appears as a digit char in input, treat as empty (0)
                cells.append(0)
            else:
                cells.append(d)
        else:
            raise ValueError(f"Invalid character '{char}' found in text.")

        i += 1

    if len(cells) != 81:
        raise ValueError("Must have exactly 81 cells.")

    grid: List[List[int]] = []
    for r in range(9):
        grid.append(cells[r * 9 : (r + 1) * 9])

    _validate_grid(grid)
    return grid


def to_string(grid: List[List[int]]) -> str:
    """
    Returns the 81 cells as one line in row-major order.
    '.' for empty cells, no whitespace.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must be 9x9.")
    for row in grid:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Each row must be 9 cells.")

    result = []
    for row in grid:
        for val in row:
            if val == 0:
                result.append('.')
            else:
                result.append(str(val))
    return "".join(result)


def is_valid(grid: List[List[int]]) -> bool:
    """
    True if no digit 1–9 appears twice in any row, column or 3×3 box.
    Empty cells never conflict. Grid need not be complete.
    """
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must be 9x9.")
    for row in grid:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Each row must be 9 cells.")

    # Check rows
    for r in range(9):
        seen = set()
        for c in range(9):
            val = grid[r][c]
            if val != 0:
                if val in seen:
                    return False
                seen.add(val)

    # Check columns
    for c in range(9):
        seen = set()
        for r in range(9):
            val = grid[r][c]
            if val != 0:
                if val in seen:
                    return False
                seen.add(val)

    # Check 3x3 boxes
    for box_r in range(3):
        for box_c in range(3):
            seen = set()
            for r in range(box_r * 3, box_r * 3 + 3):
                for c in range(box_c * 3, box_c * 3 + 3):
                    val = grid[r][c]
                    if val != 0:
                        if val in seen:
                            return False
                        seen.add(val)

    return True


def solve(grid: List[List[int]]) -> Optional[List[List[int]]]:
    """
    Returns a completed, valid grid keeping every given, or None if no solution.
    If grid is invalid, returns None.
    Result is a new grid; argument is never modified.
    """
    _validate_grid(grid)

    new_grid = copy.deepcopy(grid)

    if not is_valid(new_grid):
        return None

    solution = _backtrack(new_grid)
    return solution


def _backtrack(grid: List[List[int]]) -> Optional[List[List[int]]]:
    """Backtracking solver helper."""
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                for d in range(1, 10):
                    if _is_safe(grid, r, c, d):
                        grid[r][c] = d
                        if _backtrack(grid):
                            return grid
                        grid[r][c] = 0
                return None
    return grid


def _is_safe(grid: List[List[int]], r: int, c: int, val: int) -> bool:
    """Check if placing val at (r, c) is safe."""
    for x in range(9):
        if grid[r][x] == val:
            return False
    for y in range(9):
        if grid[y][c] == val:
            return False
    box_r, box_c = (r // 3) * 3, (c // 3) * 3
    for y in range(box_r, box_r + 3):
        for x in range(box_c, box_c + 3):
            if grid[y][x] == val:
                return False
    return True


def count_solutions(grid: List[List[int]], limit: int = 2) -> int:
    """
    Counts solutions, stopping when limit is reached.
    Returns min(total solutions, limit).
    Invalid grid returns 0.
    Raises ValueError if limit < 1.
    Argument is never modified.
    """
    if limit < 1:
        raise ValueError("Limit must be at least 1.")

    _validate_grid(grid)

    if not is_valid(grid):
        return 0

    solutions_found = [0]

    def _count_recursive(g: List[List[int]]) -> None:
        if solutions_found[0] >= limit:
            return

        for r in range(9):
            for c in range(9):
                if g[r][c] == 0:
                    for d in range(1, 10):
                        if _is_safe(g, r, c, d):
                            g[r][c] = d
                            _count_recursive(g)
                            if solutions_found[0] >= limit:
                                return
                            g[r][c] = 0

        solutions_found[0] += 1
        if solutions_found[0] >= limit:
            return

    _count_recursive(copy.deepcopy(grid))
    return solutions_found[0]


def get_candidates(grid: List[List[int]], r: int, c: int) -> Set[int]:
    """
    Returns the set of valid digits (1-9) for cell (r, c) based on current grid state.
    """
    candidates = set(range(1, 10))

    # Remove digits in row
    for x in range(9):
        if grid[r][x] != 0 and grid[r][x] in candidates:
            candidates.remove(grid[r][x])

    # Remove digits in column
    for y in range(9):
        if grid[y][c] != 0 and grid[y][c] in candidates:
            candidates.remove(grid[y][c])

    # Remove digits in 3x3 box
    box_r, box_c = (r // 3) * 3, (c // 3) * 3
    for y in range(box_r, box_r + 3):
        for x in range(box_c, box_c + 3):
            if grid[y][x] != 0 and grid[y][x] in candidates:
                candidates.remove(grid[y][x])

    return candidates


def hint(grid: List[List[int]]) -> Optional[Tuple[int, int, int, str]]:
    """
    Returns the next logical step as (row, col, digit, reason).
    Scans in order:
    1. Naked single (row-major order)
    2. Hidden single (rows 0-8, then cols 0-8, then boxes 0-8, digits 1-9)
    Returns None if no step exists.
    Raises ValueError if grid shape is bad or invalid.
    Never modifies grid.
    """
    _validate_grid(grid)

    if not is_valid(grid):
        raise ValueError("Grid must be valid.")

    # 1. Naked Single
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = get_candidates(grid, r, c)
                if len(candidates) == 1:
                    return (r, c, candidates.pop(), 'naked single')

    # 2. Hidden Single
    # Order of units: Rows, Cols, Boxes
    units = []

    # Rows
    for r in range(9):
        for d in range(1, 10):
            unit_cells = []
            for c in range(9):
                if grid[r][c] == 0 and d in get_candidates(grid, r, c):
                    unit_cells.append((r, c))
            if len(unit_cells) == 1:
                return (unit_cells[0][0], unit_cells[0][1], d, 'hidden single in row')

    # Cols
    for c in range(9):
        for d in range(1, 10):
            unit_cells = []
            for r in range(9):
                if grid[r][c] == 0 and d in get_candidates(grid, r, c):
                    unit_cells.append((r, c))
            if len(unit_cells) == 1:
                return (unit_cells[0][0], unit_cells[0][1], d, 'hidden single in column')

    # Boxes
    for box_r in range(3):
        for box_c in range(3):
            box_r_start = box_r * 3
            box_c_start = box_c * 3
            for d in range(1, 10):
                unit_cells = []
                for r in range(box_r_start, box_r_start + 3):
                    for c in range(box_c_start, box_c_start + 3):
                        if grid[r][c] == 0 and d in get_candidates(grid, r, c):
                            unit_cells.append((r, c))
                if len(unit_cells) == 1:
                    return (unit_cells[0][0], unit_cells[0][1], d, 'hidden single in box')

    return None


def difficulty(grid: List[List[int]]) -> Optional[Dict[str, int]]:
    """
    Analyzes difficulty by simulating logical steps.
    Returns {'naked': N, 'hidden': H} or None if puzzle is unsolvable or requires guessing.
    Raises ValueError if grid is invalid.
    Never modifies argument.
    """
    _validate_grid(grid)

    if not is_valid(grid):
        raise ValueError("Grid must be valid.")

    work_grid = copy.deepcopy(grid)
    naked_count = 0
    hidden_count = 0

    while True:
        hint_result = hint(work_grid)

        if hint_result is None:
            # If grid is complete but no hints found, that's success (count should be 0)
            # If grid is incomplete, it's a fail
            is_complete = all(work_grid[r][c] != 0 for r in range(9) for c in range(9))
            if is_complete:
                return {'naked': naked_count, 'hidden': hidden_count}
            else:
                return None

        row, col, digit, reason = hint_result

        if reason == 'naked single':
            naked_count += 1
        else:
            hidden_count += 1

        work_grid[row][col] = digit

        # Check for error during placement (shouldn't happen if grid valid, but good to check)
        # Actually, since we check validity before calling hint and hint only picks valid moves,
        # the grid should remain valid. However, if we missed a constraint check somewhere...
        # But logically, if hint finds a move, it's safe.
        # We continue until complete or stuck.
