# todo/store.py
import json
import tempfile
import shutil
from pathlib import Path
from typing import Any

from .model import Task, normalize_title, normalize_tag, normalize_tag as normalize_tag_fn


class StoreError(Exception):
    pass


class TodoStore:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._data: dict[str, Any] | None = None
        self._load()

    def _load(self) -> None:
        """Reads the store file. Does not create it. Raises StoreError on invalid content."""
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                content = f.read()
        except FileNotFoundError:
            # Missing file is an empty store
            self._data = {"version": 1, "next_id": 0, "tasks": []}
            return

        try:
            data = json.loads(content)
        except json.JSONDecodeError:
            raise StoreError(f"Invalid JSON: {content[:50]}...")

        # Validate structure
        if not isinstance(data, dict):
            raise StoreError("Root must be a JSON object")
        if data.get("version") != 1:
            raise StoreError(f"Unsupported version: {data.get('version')}")
        if not isinstance(data.get("next_id"), int):
            raise StoreError("next_id must be an integer")
        if not isinstance(data.get("tasks"), list):
            raise StoreError("tasks must be a list")

        self._data = data

    def _save(self) -> None:
        """Writes the whole file atomically."""
        temp_fd, temp_path = tempfile.mkstemp(dir=self.path.parent, prefix=".todo_tmp_")
        try:
            with os.fdopen(temp_fd, "w", encoding="utf-8") as f:
                json.dump(self._data, f)
            shutil.move(str(temp_path), str(self.path))
        except Exception:
            # Clean up temp file on error
            try:
                os.unlink(temp_path)
            except OSError:
                pass
            raise

    def add(self, title: str, tags: tuple[str, ...] = ()) -> Task:
        self._save()
        task = Task(id=self._data["next_id"] + 1, title=title, tags=list(tags), done=False)
        self._data["next_id"] += 1
        self._data["tasks"].append(task.to_dict())
        # Ensure tasks are sorted by id (should be naturally sorted if appending sequentially, but safety check)
        # Actually, since we increment next_id and append, they are sorted.
        # However, to be safe against future modifications or logic changes, we sort by id.
        self._data["tasks"].sort(key=lambda x: x["id"])
        self._save()
        return task

    def get(self, task_id: int) -> Task:
        for task_dict in self._data["tasks"]:
            if task_dict["id"] == task_id:
                return Task.from_dict(task_dict)
        raise KeyError(task_id)

    def list(self, status: str = "open", tags: tuple[str, ...] = ()) -> list[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError(f"Invalid status: {status}")

        normalized_tags = set(normalize_tag(t) for t in tags) if tags else set()

        result = []
        for task_dict in self._data["tasks"]:
            task = Task.from_dict(task_dict)
            if status == "all":
                if normalized_tags and not all(t in task.tags for t in normalized_tags):
                    continue
            elif task.done == (status == "done"):
                if normalized_tags and not all(t in task.tags for t in normalized_tags):
                    continue
            result.append(task)
        return result

    def mark_done(self, task_id: int) -> Task:
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                self._data["tasks"][i]["done"] = True
                self._save()
                return Task.from_dict(self._data["tasks"][i])
        raise KeyError(task_id)

    def remove(self, task_id: int) -> Task:
        # Find first occurrence
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                task = Task.from_dict(task_dict)
                del self._data["tasks"][i]
                # Re-sort tasks by id to maintain order
                self._data["tasks"].sort(key=lambda x: x["id"])
                self._save()
                return task
        raise KeyError(task_id)

    def edit(self, task_id: int, title: str | None = None, add_tags: tuple[str, ...] = (), remove_tags: tuple[str, ...] = ()) -> Task:
        # First pass: validate inputs
        if title is not None:
            try:
                normalize_title(title)
            except ValueError:
                raise ValueError("Invalid title")

        for t in add_tags:
            try:
                normalize_tag(t)
            except ValueError:
                raise ValueError(f"Invalid tag: {t}")

        for t in remove_tags:
            try:
                normalize_tag(t)
            except ValueError:
                raise ValueError(f"Invalid tag: {t}")

        # Now find and modify
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                task = Task.from_dict(task_dict)

                if title is not None:
                    task.title = normalize_title(title)

                new_tags = set(task.tags)
                for t in add_tags:
                    new_tags.add(normalize_tag(t))
                for t in remove_tags:
                    new_tags.discard(normalize_tag(t))

                task.tags = sorted(new_tags)

                self._data["tasks"][i] = task.to_dict()
                self._save()
                return task

        raise KeyError(task_id)


