        # Validate required fields
        if not isinstance(d.get("id"), int):
            raise ValueError("id must be an int")
        if not isinstance(d.get("title"), str):
            raise ValueError("title must be a str")
        if not isinstance(d.get("tags"), list):
            raise ValueError("tags must be a list of str")
        if not isinstance(d.get("done"), bool):
            raise ValueError("done must be a bool")

        # Normalize title and tags
        title = normalize_title(d["title"])
        normalized_tags = set()
        for t in d["tags"]:
