            with open(self.path, "r", encoding="utf-8") as f:
                content = f.read()
        except FileNotFoundError:
            self._data = {"version": 2, "next_id": 0, "tasks": []}
            return

        try:
            data = json.loads(content)
        except json.JSONDecodeError:
            raise StoreError(f"Invalid JSON: {content[:50]}...")

        if not isinstance(data, dict):
            raise StoreError("Root must be a JSON object")
        version = data.get("version")
        if version != 1 and version != 2:
            raise StoreError(f"Unsupported version: {version}")
        if not isinstance(data.get("next_id"), int):
            raise StoreError("next_id must be an integer")
