            raise StoreError("tasks must be a list")

        # Validate tasks structure based on version
        for idx, task_dict in enumerate(data["tasks"]):
            if not isinstance(task_dict, dict):
                raise StoreError(f"Task at index {idx} is not an object")

            # Check required fields
            if "id" not in task_dict:
                raise StoreError(f"Task {idx} missing 'id'")
            if "title" not in task_dict:
                raise StoreError(f"Task {idx} missing 'title'")
            if "tags" not in task_dict:
                raise StoreError(f"Task {idx} missing 'tags'")
            if "done" not in task_dict:
                raise StoreError(f"Task {idx} missing 'done'")

            # Check ID uniqueness and order
            if idx > 0:
                if task_dict["id"] <= data["next_id"]:
                    raise StoreError(f"Task at index {idx} has invalid id")

            # Check for duplicate ids
            if task_dict["id"] in [t["id"] for t in data["tasks"][:idx]]:
                raise StoreError(f"Duplicate task id {task_dict['id']}")

        # Upgrade version 1 to 2 implicitly by loading, but we won't modify the file here
        # We just ensure the data is loaded correctly. If it's v1, tasks lack priority/due.
        # We store the raw data as is, validation happens on read.

        self._data = data

    def _save(self, version: int = 2) -> None:
        """Writes the whole file atomically. version is used for the file header."""
        temp_fd, temp_path = tempfile.mkstemp(dir=self.path.parent, prefix=".todo_tmp_")
        try:
            with os.fdopen(temp_fd, "w", encoding="utf-8") as f:
                json.dump(self._data, f)
            shutil.move(str(temp_path), str(self.path))
        except Exception:
            try:
                os.unlink(temp_path)
            except OSError:
                pass
            raise

    def add(self, title: str, tags: tuple[str, ...] = (), priority: str = "normal", due: date | None = None) -> Task:
        self._save()
        task = Task(id=self._data["next_id"] + 1, title=title, tags=list(tags), done=False, priority=priority, due=due)
        self._data["next_id"] += 1
        self._data["tasks"].append(task.to_dict())
        self._data["tasks"].sort(key=lambda x: x["id"])
        self._save()
        return task

    def get(self, task_id: int) -> Task:
        for task_dict in self._data["tasks"]:
            if task_dict["id"] == task_id:
                return Task.from_dict(task_dict)
        raise KeyError(task_id)

    def list(self, status: str = "open", tags: tuple[str, ...] = (), 
             overdue: bool = False, today: date | None = None, sort: str = "id") -> list[Task]:
        if status not in ("open", "done", "all"):
            raise ValueError(f"Invalid status: {status}")

        if overdue and today is None:
            raise ValueError("overdue requires today")

        if sort not in ("id", "priority", "due"):
            raise ValueError(f"Invalid sort: {sort}")

        normalized_tags = set(normalize_tag(t) for t in tags) if tags else set()

        result = []
        for task_dict in self._data["tasks"]:
            task = Task.from_dict(task_dict)

            # Apply status filter
            if status != "all":
                if task.done == (status == "done"):
                    pass
                elif status == "open" and task.done:
                    continue
                elif status == "done" and not task.done:
                    continue

            # Apply tag filter
            if normalized_tags and not all(t in task.tags for t in normalized_tags):
                continue

            # Apply overdue filter
            if overdue:
                if task.done:
                    continue
                if task.due is not None and task.due >= today:
                    continue

            result.append(task)

        # Sorting
        def sort_key(t: Task) -> tuple:
            # id is always first
            tid = t.id
            if sort == "priority":
                prio_order = {"high": 0, "normal": 1, "low": 2}
                return (tid, prio_order[t.priority], 0)
            elif sort == "due":
                if t.due is None:
                    return (tid, 1) # Put None dates last
                return (tid, 0, t.due)
            else: # id
                return (tid,)

        result.sort(key=sort_key)
        return result

    def mark_done(self, task_id: int) -> Task:
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                self._data["tasks"][i]["done"] = True
                self._save()
                return Task.from_dict(self._data["tasks"][i])
        raise KeyError(task_id)

    def remove(self, task_id: int) -> Task:
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                task = Task.from_dict(task_dict)
                del self._data["tasks"][i]
                self._data["tasks"].sort(key=lambda x: x["id"])
                self._save()
                return task
        raise KeyError(task_id)

    def edit(self, task_id: int, title: str | None = None, add_tags: tuple[str, ...] = (), 
             remove_tags: tuple[str, ...] = (), priority: str | None = None, 
             due: date | None = None, clear_due: bool = False) -> Task:
        # Validation before changes
        if title is not None:
            try:
                normalize_title(title)
            except ValueError:
                raise ValueError("Invalid title")

        for t in add_tags:
            try:
                normalize_tag(t)
            except ValueError:
                raise ValueError(f"Invalid tag: {t}")

        for t in remove_tags:
            try:
                normalize_tag(t)
            except ValueError:
                raise ValueError(f"Invalid tag: {t}")

        if priority is not None:
            try:
                normalize_priority(priority)
            except ValueError:
                raise ValueError("Invalid priority")

        if due is not None and clear_due:
            raise ValueError("Cannot specify due and clear_due")

        # Find and modify
        for i, task_dict in enumerate(self._data["tasks"]):
            if task_dict["id"] == task_id:
                task = Task.from_dict(task_dict)

                if title is not None:
                    task.title = normalize_title(title)

                new_tags = set(task.tags)
                for t in add_tags:
                    new_tags.add(normalize_tag(t))
                for t in remove_tags:
                    new_tags.discard(normalize_tag(t))
                task.tags = sorted(new_tags)

                if priority is not None:
                    task.priority = normalize_priority(priority)

                if due is not None:
                    task.due = due
                elif clear_due:
                    task.due = None

                self._data["tasks"][i] = task.to_dict()
                self._save()
                return task

        raise KeyError(task_id)


