import argparse
import sys
from datetime import date, datetime

from .model import Task
from .store import TodoStore, StoreError


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="todo",
        description="Simple command-line todo manager"
    )

    # Global options
    parser.add_argument("--file", "-f", type=str, default="todo.json", help="Path to the store file")
    parser.add_argument("--today", type=str, default=None, help="Date to use as today (YYYY-MM-DD)")

    subparsers = parser.add_subparsers(dest="command", help="Commands")

    # add command
    add_parser = subparsers.add_parser("add", help="Add a new task")
    add_parser.add_argument("title", nargs="?", default="", help="Task title (required)")
    add_parser.add_argument("--tag", action="append", help="Tag to assign to the task")
    add_parser.add_argument("--priority", choices=["high", "normal", "low"], help="Priority level")
    add_parser.add_argument("--due", type=str, help="Due date (YYYY-MM-DD)")

    # list command
    list_parser = subparsers.add_parser("list", help="List tasks")
    list_parser.add_argument("--status", choices=["open", "done", "all"], default="open", help="Filter by status")
    list_parser.add_argument("--tag", action="append", help="Filter by tags")
    list_parser.add_argument("--overdue", action="store_true", help="Show only overdue open tasks")
    list_parser.add_argument("--sort", choices=["id", "priority", "due"], default="id", help="Sort order")

    # done command
    done_parser = subparsers.add_parser("done", help="Mark tasks as done")
    done_parser.add_argument("ids", nargs="+", type=int, help="Task IDs to mark done")

    # remove command
    remove_parser = subparsers.add_parser("remove", help="Remove a task")
    remove_parser.add_argument("id", type=int, help="Task ID to remove")

    # edit command
    edit_parser = subparsers.add_parser("edit", help="Edit a task")
    edit_parser.add_argument("id", type=int, help="Task ID to edit")
    edit_parser.add_argument("--title", help="New title")
    edit_parser.add_argument("--tag", action="append", help="Tag to add")
    edit_parser.add_argument("--untag", action="append", help="Tag to remove")
    edit_parser.add_argument("--priority", choices=["high", "normal", "low"], help="New priority")
    edit_parser.add_argument("--due", type=str, help="New due date (YYYY-MM-DD)")
    edit_parser.add_argument("--no-due", action="store_true", help="Clear due date")

    try:
        args = parser.parse_args(argv)
    except SystemExit as e:
        return e.code if isinstance(e.code, int) else 2

    if not args.command:
        parser.print_help()
        return 2

    store = TodoStore(args.file)

    # Validate global options
    if args.today:
        try:
            today = date.fromisoformat(args.today)
        except ValueError:
            print("error: invalid date format for --today", file=sys.stderr)
            return 2
    else:
        today = date.today()

    try:
        if args.command == "add":
            if not args.title:
                return 2
            # Validate priority if provided
            if args.priority is not None:
                try:
                    normalize_priority(args.priority)
                except ValueError:
                    print("error: invalid priority", file=sys.stderr)
                    return 2

            # Validate due date if provided
            if args.due is not None:
                try:
                    parse_date(args.due)
                except ValueError:
                    print("error: invalid date format for --due", file=sys.stderr)
                    return 2

            task = store.add(args.title, args.tag or (), 
                            priority=args.priority, 
                            due=None if args.due is None else parse_date(args.due))
            print(f"added {task.id}")

        elif args.command == "list":
            # Validate overdue flag
            if args.overdue and args.today is None:
                # This is caught by the main function check, but argparse handles missing arg
                # We need to ensure today is set if --overdue is used
                # Actually, the logic in model.py raises ValueError if today is None and overdue is True
                # So we just pass None and let model raise, or set today to now.
                # The spec says "overdue without today raises ValueError". 
                # We'll set today to now if not provided AND overdue is True.
                if not args.today:
                    args.today = date.today().isoformat()

            tasks = store.list(
                status=args.status, 
                tags=args.tag or (), 
                overdue=args.overdue, 
                today=date.fromisoformat(args.today) if args.today else None, 
                sort=args.sort
            )
            for task in tasks:
                line = f"{task.id} "
                if task.done:
                    line += "[x] "
                else:
                    line += "[ ] "
                line += task.title
                if task.priority != "normal":
                    line += f" !{task.priority}"
                if task.due is not None:
                    line += f" due:{task.due.isoformat()}"
                if task.tags:
                    line += " " + " #".join(sorted(task.tags))
                print(line)

        elif args.command == "done":
            ids_to_check = args.ids
            errors = []
            for tid in ids_to_check:
                try:
                    store.get(tid)
                except KeyError:
                    errors.append(tid)

            if errors:
                print(f"error: no task with id {errors[0]}", file=sys.stderr)
                return 1

            for tid in ids_to_check:
                try:
                    store.mark_done(tid)
                    print(f"done {tid}")
                except Exception as e:
                    pass

        elif args.command == "remove":
            try:
                store.remove(args.id)
                print(f"removed {args.id}")
            except KeyError:
                print(f"error: no task with id {args.id}", file=sys.stderr)
                return 1

        elif args.command == "edit":
            has_edit = False
            if args.title is not None:
                has_edit = True
            if args.tag:
                has_edit = True
            if args.untag:
                has_edit = True
            if args.priority is not None:
                has_edit = True
            if args.due is not None:
                has_edit = True
            if args.no_due:
                has_edit = True

            if not has_edit:
                return 2

            # Validate priority if provided
            if args.priority is not None:
                try:
                    normalize_priority(args.priority)
                except ValueError:
                    print("error: invalid priority", file=sys.stderr)
                    return 2

            # Validate due date if provided
            if args.due is not None:
                try:
                    parse_date(args.due)
                except ValueError:
                    print("error: invalid date format for --due", file=sys.stderr)
                    return 2

            if args.due is not None and args.no_due:
                print("error: cannot use --due and --no-due together", file=sys.stderr)
                return 2

            try:
                task = store.edit(
                    args.id, 
                    title=args.title, 
                    add_tags=args.tag or (), 
                    remove_tags=args.untag or (), 
                    priority=args.priority, 
                    due=None if args.due is None else parse_date(args.due),
                    clear_due=args.no_due
                )
                print(f"edited {args.id}")
            except ValueError as e:
                print(f"error: {e}", file=sys.stderr)
                return 2
            except KeyError:
                print(f"error: no task with id {args.id}", file=sys.stderr)
                return 1
            except StoreError as e:
                print(f"error: {e}", file=sys.stderr)
                return 3

    except StoreError as e:
        print(f"error: {e}", file=sys.stderr)
        return 3

    return 0


if __name__ == "__main__":
    sys.exit(main())
