# minisql/tokens.py

import re
from dataclasses import dataclass

@dataclass(frozen=True)
class Token:
    kind: str
    value: str | None
    pos: int

class SQLError(Exception):
    def __init__(self, message: str, pos: int):
        self.pos = pos
        super().__init__(message)

class SQLSyntaxError(SQLError):
    pass

def _tokenize_string(s: str) -> list[Token]:
    """Tokenize a single string literal, handling escaping."""
    result = []
    i = 1  # skip opening quote
    while i < len(s):
        if s[i] == "'":
            if i + 1 < len(s) and s[i+1] == "'":
                result.append(Token('STRING', "'", i))
                i += 2
            else:
                raise SQLSyntaxError("Unterminated string", i)
        else:
            result.append(Token('STRING', s[i], i))
            i += 1
    if i < len(s) and s[i] != "'":
        raise SQLSyntaxError(f"Unexpected character '{s[i]}' at end of string", i)
    return result

def _try_parse_number(s: str, start: int) -> tuple[int | float | None, int]:
    """
    Parses a number from the string starting at 'start'.
    Returns (value, next_index).
    Raises SQLSyntaxError if format is invalid.
    """
    if not s:
        raise SQLSyntaxError("Unexpected end of input", start)

    s = s[start:]

    neg = False
    if s[0] == '-':
        neg = True
        s = s[1:]

    if not s:
        raise SQLSyntaxError(f"Number missing after minus sign", start)

    has_dot = False

    i = 0
    while i < len(s) and s[i].isdigit():
        i += 1

    if i == 0:
        raise SQLSyntaxError(f"Expected digit after minus sign", start)

    if '.' in s[i:]:
        has_dot = True
        rest = s[i:]
        if not rest[0].isdigit():
            raise SQLSyntaxError(f"Expected digit after decimal point", start)

        frac_start = i
        i += 1
        while i < len(rest) and rest[i].isdigit():
            i += 1

        if i != frac_start + 1:
            val = float(s[0:i])
            if neg:
                val = -val
            return val, start + i
        else:
            raise SQLSyntaxError(f"Expected digit after decimal point", start)

    if i < len(s):
        val = int(s[0:i])
        if neg:
            val = -val
        return val, start + i

    raise SQLSyntaxError(f"Expected digit", start)

def tokenize(sql: str) -> list[Token]:
    tokens = []
    i = 0
    keywords = {
        'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'NOT', 'ORDER', 'BY', 
        'ASC', 'DESC', 'LIMIT', 'IS', 'NULL', 'TRUE', 'FALSE',
        'JOIN', 'ON', 'GROUP', 'AS', 'COUNT', 'SUM', 'AVG', 'MIN', 'MAX'
    }

    while i < len(sql):
        c = sql[i]

        if c.isspace():
            i += 1
            continue

        j = i
        while j < len(sql) and sql[j].isalnum() or sql[j] == '_':
            j += 1

        word = sql[i:j]
        upper_word = word.upper()

        if upper_word in keywords:
            tokens.append(Token('KEYWORD', upper_word, i))
            i = j
            continue

        # Check for DOT before identifier/number logic to avoid splitting .number
        # Actually, we handle DOT as a single char token if not part of a number.
        if c == '.':
            tokens.append(Token('DOT', '.', i))
            i += 1
            continue

        if word and (word[0].isalpha() or word[0] == '_'):
            tokens.append(Token('IDENT', word, i))
            i = j
            continue

        if word.isdigit():
            val, pos = _try_parse_number(word, i)
            tokens.append(Token('NUMBER', val, i))
            i = j + pos - i
            continue

        # Single character operators/symbols
        if len(word) >= 2:
            two_char_op = sql[i:i+2]
            if two_char_op in ('!=', '<>', '<=', '>='):
                mapped_op = '!=' if two_char_op == '<>' else two_char_op
                tokens.append(Token('OP', mapped_op, i))
                i += 2
                continue

        if c == '*':
            tokens.append(Token('STAR', '*', i))
            i += 1
        elif c == ',':
            tokens.append(Token('COMMA', ',', i))
            i += 1
        elif c == '(':
            tokens.append(Token('LPAREN', '(', i))
            i += 1
        elif c == ')':
            tokens.append(Token('RPAREN', ')', i))
            i += 1
        elif c == '=':
            tokens.append(Token('OP', '=', i))
            i += 1
        elif c in ('!', '<', '>'):
            tokens.append(Token('OP', c, i))
            i += 1
        else:
            raise SQLSyntaxError(f"Unexpected character '{c}'", i)

    tokens.append(Token('EOF', None, len(sql)))
    return tokens
