# minisql/parser.py

from dataclasses import dataclass
from .tokens import Token, tokenize, SQLSyntaxError

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: int | float | str | bool | None

@dataclass(frozen=True)
class Compare:
    op: str
    left: Literal
    right: Literal

@dataclass(frozen=True)
class And:
    left: 'Condition'
    right: 'Condition'

@dataclass(frozen=True)
class Or:
    left: 'Condition'
    right: 'Condition'

@dataclass(frozen=True)
class Not:
    operand: 'Operand'

@dataclass(frozen=True)
class IsNull:
    operand: 'Operand'
    negated: bool

@dataclass(frozen=True)
class Aggregate:
    func: str
    arg: Column | None

@dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclass(frozen=True)
class Select:
    items: list[tuple[Column | Aggregate, str]] = None
    columns: list[str] | None = None
    table: str = ""
    where: 'Condition' | None = None
    join: Join | None = None
    group_by: list[str] = None
    order_by: list[tuple[str, bool]] = None
    limit: int | None = None

# Default constructor to satisfy dataclass requirements
def __new__(cls, *args, **kwargs):
    if not args:
        return object.__new__(cls, None, None, "", None, None, [], [], None, None)
    return super().__new__(cls)

Condition = And | Or | Not | IsNull
Operand = Literal # Reuse Literal for operands in this context

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    pos = 0
    len_tokens = len(tokens)

    def peek() -> Token:
        return tokens[pos]

    def advance() -> Token:
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect(kind: str, value: str | None = None) -> Token:
        if peek().kind != kind:
            raise SQLSyntaxError(f"Expected {kind} ({value})", pos)
        advance()
        return tokens[pos-1]

    def parse_identifier() -> str:
        tok = peek()
        if tok.kind != 'IDENT':
            raise SQLSyntaxError(f"Expected identifier", pos)
        advance()
        return tok.value

    def parse_number() -> Literal:
        tok = peek()
        if tok.kind != 'NUMBER':
            raise SQLSyntaxError(f"Expected number", pos)
        advance()
        return Literal(tok.value)

    def parse_string() -> Literal:
        tok = peek()
        if tok.kind != 'STRING':
            raise SQLSyntaxError(f"Expected string", pos)
        advance()
        return Literal(tok.value)

    def parse_null() -> Literal:
        return Literal(None)

    def parse_bool(val: bool) -> Literal:
        return Literal(val)

    def parse_operand() -> Literal:
        tok = peek()
        if tok.kind == 'IDENT':
            advance()
            return Literal(tok.value)
        elif tok.kind == 'NUMBER':
            advance()
            return Literal(tok.value)
        elif tok.kind == 'STRING':
            advance()
            return Literal(tok.value)
        elif tok.kind == 'KEYWORD':
            kw = tok.value
            if kw == 'NULL':
                advance()
                return parse_null()
            elif kw in ('TRUE', 'FALSE'):
                advance()
                return parse_bool(kw == 'TRUE')
            else:
                raise SQLSyntaxError(f"Unexpected keyword in operand: {kw}", pos)
        else:
            raise SQLSyntaxError(f"Unexpected token in operand", pos)

    def parse_op() -> str:
        if peek().kind == 'OP':
            advance()
            return peek().value
        return None

    def parse_primary_condition() -> 'Condition':
        if peek().kind == 'LPAREN':
            advance()
            left = parse_condition()
            if peek().kind == 'RPAREN':
                advance()
                return left
            raise SQLSyntaxError("Expected ')' after condition", pos)

        if peek().kind == 'KEYWORD' and peek().value == 'NOT':
            advance()
            operand = parse_operand()
            return Not(operand)

        operand = parse_operand()
        if peek().kind == 'OP':
            op = parse_op()
            right = parse_operand()
            return Compare(op, operand, right)

        return operand

    def parse_condition() -> 'Condition':
        left = parse_primary_condition()
        while True:
            if peek().kind == 'KEYWORD' and peek().value == 'AND':
                advance()
                right = parse_condition()
                left = And(left, right)
            elif peek().kind == 'KEYWORD' and peek().value == 'OR':
                advance()
                right = parse_condition()
                left = Or(left, right)
            else:
                break
        return left

    def parse_order_item() -> tuple[str, bool]:
        # Can be ref or aggregate
        if peek().kind == 'AGGREGATE':
            func = parse_aggregate()
            text = func.text
            if peek().kind == 'KEYWORD' and peek().value == 'ASC':
                advance()
                return (text, False)
            elif peek().kind == 'KEYWORD' and peek().value == 'DESC':
                advance()
                return (text, True)
            return (text, False)
        else:
            ref = parse_ref()
            text = ref.text
            if peek().kind == 'KEYWORD' and peek().value == 'ASC':
                advance()
                return (text, False)
            elif peek().kind == 'KEYWORD' and peek().value == 'DESC':
                advance()
                return (text, True)
            return (text, False)

    def parse_join_term() -> tuple[str, Column, Column]:
        table = parse_identifier()
        if peek().kind != 'KEYWORD' or peek().value != 'JOIN':
            raise SQLSyntaxError("Expected JOIN", pos)
        advance()

        left = parse_ref()
        if peek().kind != 'KEYWORD' or peek().value != 'ON':
            raise SQLSyntaxError("Expected ON", pos)
        advance()

        right = parse_ref()
        return (table, left, right)

    def parse_aggregate() -> Aggregate:
        if peek().kind != 'KEYWORD' or peek().value not in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            raise SQLSyntaxError("Expected aggregate function", pos)
        func = peek().value
        advance()

        if peek().kind == 'LPAREN':
            advance()
            if peek().kind == 'STAR':
                advance()
                arg = None
            else:
                arg = parse_ref()
            if peek().kind != 'RPAREN':
                raise SQLSyntaxError("Expected ')'", pos)
            advance()
            return Aggregate(func, arg)
        else:
            raise SQLSyntaxError("Expected '(' after aggregate function", pos)

    def parse_ref() -> Column:
        if peek().kind != 'IDENT':
            raise SQLSyntaxError(f"Expected identifier or table.name", pos)
        name = parse_identifier()

        if peek().kind == 'DOT':
            advance()
            table_name = parse_identifier()
            return Column(name + "." + table_name)
        return Column(name)

    # Parse SELECT
    if peek().kind != 'KEYWORD' or peek().value != 'SELECT':
        raise SQLSyntaxError("Expected SELECT", pos)
    advance()

    items = []
    columns = []

    if peek().kind == 'STAR':
        advance()
        items.append((None, "ALL")) # Placeholder for *
        columns.append("ALL")
    elif peek().kind == 'IDENT':
        while True:
            if peek().kind == 'KEYWORD' and peek().value == 'AS':
                advance()
                key = parse_identifier()
            else:
                expr = parse_primary_condition()
                if isinstance(expr, Aggregate):
                    text = expr.text
                else:
                    text = expr.text
                if peek().kind == 'KEYWORD' and peek().value == 'AS':
                    advance()
                    key = parse_identifier()
                else:
                    key = text

            # Validate * in grouped query
            if isinstance(expr, Aggregate):
                if peek().kind == 'GROUP': # Lookahead for GROUP
                    pass # Will be handled later

            items.append((expr, key))
            columns.append(key)

            if peek().kind != 'COMMA':
                break
            advance() # consume comma

    if peek().kind != 'KEYWORD' or peek().value != 'FROM':
        raise SQLSyntaxError("Expected FROM", pos)
    advance()
    from_table = parse_identifier()

    join = None
    if peek().kind == 'KEYWORD' and peek().value == 'JOIN':
        advance()
        j_table, j_left, j_right = parse_join_term()
        join = Join(j_table, j_left, j_right)

    where = None
    if peek().kind == 'KEYWORD' and peek().value == 'WHERE':
        advance()
        where = parse_condition()

    group_by = []
    if peek().kind == 'KEYWORD' and peek().value == 'GROUP':
        advance()
        if peek().kind != 'KEYWORD' or peek().value != 'BY':
            raise SQLSyntaxError("Expected BY after GROUP", pos)
        advance()
        while True:
            ref = parse_ref()
            group_by.append(ref.text)
            if peek().kind == 'COMMA':
                advance()
            else:
                break

    order_by = []
    if peek().kind == 'KEYWORD' and peek().value == 'ORDER':
        advance()
        if peek().kind != 'KEYWORD' or peek().value != 'BY':
            raise SQLSyntaxError("Expected BY after ORDER", pos)
        advance()
        while True:
            item = parse_order_item()
            order_by.append(item)
            if peek().kind == 'COMMA':
                advance()
            else:
                break

    limit = None
    if peek().kind == 'KEYWORD' and peek().value == 'LIMIT':
        advance()
        tok = peek()
        if tok.kind != 'NUMBER':
            raise SQLSyntaxError(f"Expected number in LIMIT", pos)
        advance()
        limit = tok.value
        if peek().kind != 'EOF':
            raise SQLSyntaxError("Unexpected token after LIMIT", pos)

    if peek().kind != 'EOF':
        raise SQLSyntaxError(f"Unexpected token after statement: {peek().kind}", pos)

    # Post-processing checks
    # 1. * in grouped query
    is_grouped = len(group_by) > 0 or any(isinstance(item[0], Aggregate) for item in items)

    if is_grouped and items:
        for expr, _ in items:
            if isinstance(expr, Aggregate):
                raise SQLSyntaxError("SELECT * not allowed in grouped query", 0)
            # Check if ref is not in group_by
            if not isinstance(expr, Aggregate):
                ref_text = expr.text
                if ref_text not in group_by:
                    raise SQLSyntaxError(f"Select item {ref_text} not in GROUP BY", 0)

    # 2. Order by aggregates in non-grouped
    if not is_grouped and order_by:
        for text, _ in order_by:
            if any(isinstance(item[0], Aggregate) for item in items if item[0].text == text):
                raise SQLSyntaxError(f"Aggregate in ORDER BY in non-grouped query", 0)

    return Select(items, columns, from_table, where, join, group_by, order_by, limit)
