# minisql/execute.py

from .tokens import Token, SQLExecutionError
from .parser import Select, Column, Literal, Compare, And, Or, Not, IsNull, Aggregate, Join, SQLSyntaxError

def _value_to_python(val: Literal) -> None:
    if val is None:
        return None
    if isinstance(val.value, str):
        return val.value
    if isinstance(val.value, bool):
        return val.value
    return val.value

def _compare(a: Literal, b: Literal, op: str) -> bool | None:
    va = _value_to_python(a)
    vb = _value_to_python(b)

    if va is None or vb is None:
        return None

    if type(va) != type(vb):
        if op in ('=', '!='):
            if op == '=':
                return False
            else:
                return True
        else:
            raise SQLExecutionError(f"Cannot compare {type(va)} with {type(vb)} using {op}", 0)

    if op == '=':
        return va == vb
    elif op == '!=':
        return va != vb
    elif op in ('<', '<=', '>', '>='):
        if op == '<':
            return va < vb
        elif op == '<=':
            return va <= vb
        elif op == '>':
            return va > vb
        elif op == '>=':
            return va >= vb
    else:
        raise SQLExecutionError(f"Unknown operator {op}", 0)

def _eval_condition(cond: 'Condition', row: dict) -> bool | None:
    if isinstance(cond, Compare):
        res = _compare(cond.left.value, cond.right.value, cond.op)
        return res

    elif isinstance(cond, IsNull):
        val = row.get(cond.operand.name)
        if val is None:
            return not cond.negated
        else:
            return cond.negated

    elif isinstance(cond, Not):
        res = _eval_condition(cond.operand, row)
        if res is None:
            return None
        return not res

    elif isinstance(cond, And):
        l = _eval_condition(cond.left, row)
        r = _eval_condition(cond.right, row)
        if l is None or r is None:
            return None
        if l == False or r == False:
            return False
        return True

    elif isinstance(cond, Or):
        l = _eval_condition(cond.left, row)
        r = _eval_condition(cond.right, row)
        if l is True or r is True:
            return True
        if l is None or r is None:
            return None
        return False

    return False

def _get_sort_key(r: dict, text: str, descending: bool) -> tuple:
    # Check if it's an alias
    if text in r:
        val = r[text]
    else:
        # Try to find as column
        val = r.get(text)

    # Handle NULL sorting
    if val is None:
        if descending:
            return (1, float('inf'))
        else:
            return (0, float('-inf'))

    python_val = _value_to_python(Literal(val))
    if descending:
        return (0, -python_val)
    else:
        return (0, python_val)

def _sort_rows(rows: list[dict], order_by: list[tuple[str, bool]]) -> list[dict]:
    return sorted(rows, key=lambda r: tuple(_get_sort_key(r, t, d) for t, d in order_by))

def _apply_aggregation(expr: Aggregate, group_rows: list[dict]) -> Literal:
    vals = [_value_to_python(Literal(r.get(expr.arg.name))) for r in group_rows]
    vals = [v for v in vals if v is not None]

    if not vals:
        return Literal(None)

    if expr.func == 'COUNT':
        if expr.arg is None:
            return Literal(len(group_rows))
        else:
            return Literal(len(vals))

    if expr.func in ('SUM', 'AVG'):
        if not all(isinstance(v, (int, float)) for v in vals):
            raise SQLExecutionError(f"SUM/AVG over non-numeric values", 0)
        if expr.func == 'SUM':
            total = sum(vals)
            if isinstance(total, float) and total != int(total):
                return Literal(total)
            return Literal(int(total))
        else:
            return Literal(float(sum(vals)) / len(vals))

    if expr.func in ('MIN', 'MAX'):
        if not all(isinstance(v, (int, float, str, bool)) for v in vals):
            raise SQLExecutionError(f"MIN/MAX over mixed types", 0)
        if expr.func == 'MIN':
            return Literal(min(vals))
        else:
            return Literal(max(vals))

    raise SQLExecutionError(f"Unknown aggregate function {expr.func}", 0)

def execute(stmt: Select, tables: dict[str, list[dict]]) -> list[dict]:
    # Resolve tables and refs
    if stmt.join:
        left_table, right_table = stmt.join.table
        if left_table not in tables or right_table not in tables:
            raise SQLExecutionError(f"Unknown table in JOIN: {stmt.join.table}", 0)

        if left_table == right_table:
            raise SQLExecutionError("Cannot self-join with same table alias in this context", 0)

        left_rows = tables[left_table]
        right_rows = tables[right_table]

        joined_rows = []
        for lr in left_rows:
            for rr in right_rows:
                # Find matching column names
                l_cols = set(lr.keys())
                r_cols = set(rr.keys())

                # Determine which is which based on column existence
                # One must be unique to left, one unique to right
                only_left = l_cols - r_cols
                only_right = r_cols - l_cols

                if not only_left or not only_right:
                    # Try to find intersection if ambiguous? 
                    # Spec says: "One of p and q must name a column of a and the other a column of b"
                    # If names overlap, it's ambiguous unless we assume strict separation.
                    # Let's assume strict separation for this simple engine.
                    raise SQLExecutionError("Ambiguous column names in JOIN", 0)

                l_col = only_left.pop()
                r_col = only_right.pop()

                l_val = lr.get(l_col)
                r_val = rr.get(r_col)

                if _compare(l_val, r_val, '=') is True:
                    # Merge rows
                    merged = dict(lr)
                    for k, v in rr.items():
                        if k not in merged:
                            merged[k] = v
                    joined_rows.append(merged)

    else:
        rows = tables.get(stmt.table, [])

    # WHERE
    if stmt.where:
        rows = [r for r in rows if _eval_condition(stmt.where, r) is True]

    # GROUP BY
    is_grouped = len(stmt.group_by) > 0
    if is_grouped:
        # Group rows
        groups = {}
        for r in rows:
            key = tuple(r.get(g) for g in stmt.group_by)
            if key not in groups:
                groups[key] = []
            groups[key].append(r)
        rows = list(groups.values())

    # ORDER BY
    if stmt.order_by:
        rows = _sort_rows(rows, stmt.order_by)

    # LIMIT
    if stmt.limit is not None:
        rows = rows[:int(stmt.limit)]

    # Aggregates and Final Output
    result = []
    for group_rows in rows:
        new_row = {}
        if stmt.items:
            for expr, key in stmt.items:
                if isinstance(expr, Aggregate):
                    val = _apply_aggregation(expr, group_rows)
                elif isinstance(expr, Column):
                    val = group_rows.get(expr.name)
                    if val is None:
                        val = None # Missing column is NULL
                else:
                    raise SQLExecutionError(f"Unknown expression type", 0)

                new_row[key] = val

        result.append(new_row)

    return result

def query(sql: str, tables: dict[str, list[dict]]) -> list[dict]:
    from .parser import parse
    return execute(parse(sql), tables)
