"""
HTTP/1.1 Request and Response parsing and construction.
"""

import json
import re
import base64
from dataclasses import dataclass, field
from typing import Any, Optional, List, Tuple, Dict

# Reason phrases
REASONS = {
    200: "OK", 201: "Created", 204: "No Content",
    400: "Bad Request", 401: "Unauthorized", 404: "Not Found",
    405: "Method Not Allowed", 500: "Internal Server Error"
}

def _reason(status: int) -> str:
    return REASONS.get(status, "Unknown")

class HTTPError(Exception):
    """Base HTTP error."""
    status: int
    reason: str

    def __init__(self, status: int, reason: str):
        self.status = status
        self.reason = reason
        super().__init__(f"{status} {reason}")

class BadRequest(HTTPError):
    """Bad Request error."""
    def __init__(self, message: str = ""):
        super().__init__(400, "Bad Request")
        if message:
            self.args = (f"{message}: {super().__str__()}",)

class Headers:
    """Ordered, case-insensitive multi-map of headers."""
    def __init__(self, pairs: tuple = ()):
        self._items: List[Tuple[str, str]] = list(pairs)

    def add(self, name: str, value: str):
        # Append
        self._items.append((name, value))

    def set(self, name: str, value: str):
        # Replace all occurrences of this name
        self._items = [(n, v) for n, v in self._items if n != name]
        self._items.append((name, value))

    def get(self, name: str, default: Any = None):
        for n, v in self._items:
            if n.lower() == name.lower():
                return v
        return default

    def __getitem__(self, name: str):
        for n, v in self._items:
            if n.lower() == name.lower():
                return v
        raise KeyError(name)

    def get_all(self, name: str) -> List[str]:
        result = []
        for n, v in self._items:
            if n.lower() == name.lower():
                result.append(v)
        return result

    def __contains__(self, name: str):
        return any(n.lower() == name.lower() for n, _ in self._items)

    def __len__(self) -> int:
        return len(self._items)

    def items(self):
        return self._items

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers = field(default_factory=Headers)
    body: bytes = b""
    params: dict = field(default_factory=dict)
    state: dict = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        """Parse query string into a dict of name -> list of values."""
        if not self.query_string:
            return {}

        result: Dict[str, List[str]] = {}
        parts = self.query_string.split('&')

        for part in parts:
            if not part:
                continue
            if '=' in part:
                name, value = part.split('=', 1)
            else:
                name, value = part, ''

            # Decode name and value
            try:
                name = decode_url(name)
                value = decode_url(value)
            except Exception as e:
                raise BadRequest(str(e))

            if name:
                if name in result:
                    result[name].append(value)
                else:
                    result[name] = [value]

        return result

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        """Parse Content-Type header."""
        ct = self.headers.get('Content-Type', '')
        if not ct:
            return ('', {})

        parts = ct.split(';')
        media_type = parts[0].strip().lower()
        params: Dict[str, str] = {}

        for part in parts[1:]:
            part = part.strip()
            if not part:
                continue
            if '=' in part:
                name, value = part.split('=', 1)
                name = name.strip().lower()
                value = value.strip()
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]
                params[name] = value
            # Skip pieces without '='

        return (media_type, params)

    def text(self, encoding: str = None) -> str:
        """Decode body as text."""
        if not self.body:
            return ""
        ct, _ = self.content_type
        charset = encoding
        if charset is None:
            if 'charset' in ct:
                charset = ct['charset']
            else:
                charset = 'utf-8'

        try:
            return self.body.decode(charset)
        except UnicodeDecodeError:
            raise BadRequest(f"Invalid UTF-8 encoding: {charset}")

    def json(self) -> Any:
        """Parse body as JSON."""
        try:
            return json.loads(self.text())
        except json.JSONDecodeError:
            raise BadRequest("Invalid JSON")

@dataclass
class Response:
    status: int = 200
    headers: Headers = field(default_factory=Headers)
    body: bytes = b""

    @classmethod
    def text(cls, s: str, status: int = 200):
        r = cls(status=status)
        r.body = s.encode('utf-8')
        r.headers.add('Content-Type', 'text/plain; charset=utf-8')
        return r

    @classmethod
    def json(cls, obj: Any, status: int = 200):
        from dataclasses import fields
        # We need to serialize manually to match spec requirements
        r = cls(status=status)
        json_str = json.dumps(obj, separators=(',', ':'), sort_keys=True)
        r.body = json_str.encode('utf-8')
        r.headers.add('Content-Type', 'application/json')
        return r

    def to_bytes(self):
        # Status line
        lines = [f"HTTP/1.1 {self.status} {_reason(self.status)}"]

        # Headers
        # We need to ensure Content-Length is the last and unique
        # Spec says: Content-Length as last header, drop any existing one
        final_headers = []
        has_content_length = False

        for name, value in self.headers._items:
            if name.lower() == 'content-length':
                has_content_length = True
                if not has_content_length:
                    final_headers.append((name, value))
            else:
                final_headers.append((name, value))

        if not has_content_length:
            final_headers.append(('Content-Length', str(len(self.body))))

        # Sort final headers? Spec says "in order".
        # The logic above preserves order unless Content-Length was in the middle.
        # Re-reading: "Content-Length: <len(body)> as the last header".
        # So we should move it to the end if it wasn't there, or keep it if it was?
        # "any Content-Length already present is dropped" implies we just add one at the end.
        # Let's rebuild headers to guarantee Content-Length is last.

        h_list = []
        for name, value in self.headers._items:
            if name.lower() != 'content-length':
                h_list.append((name, value))

        h_list.append(('Content-Length', str(len(self.body))))

        for name, value in h_list:
            lines.append(f"{name}: {value}")

        # End of headers
        lines.append('')
        # Body
        lines.append(self.body.decode('latin-1')) # Wait, to_bytes returns bytes.
        # The doc says "then an empty line and the body". The body is bytes.
        # But lines is a list of strings.
        # We are building the string representation.
        # Actually, the method returns bytes.
        # Let's reconstruct properly.

        parts = []
        parts.append(f"HTTP/1.1 {self.status} {_reason(self.status)}")
        for name, value in h_list:
            parts.append(f"{name}: {value}")
        parts.append('')
        parts.append(self.body.decode('latin-1')) # To avoid double encoding, decode once as latin-1 (identity)

        return bytes("".join(parts), 'utf-8')

def decode_url(s: str) -> str:
    """Percent-decode URL string, handling + as space."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%':
            if i + 2 >= len(s):
                raise BadRequest("Invalid URL escape")
            hex_str = s[i+1:i+3]
            if not all(c in '0123456789abcdefABCDEF' for c in hex_str):
                raise BadRequest(f"Invalid URL escape: %{hex_str}")
            result.append(chr(int(hex_str, 16)))
            i += 3
        elif s[i] == '+':
            result.append(' ')
            i += 1
        else:
            result.append(s[i])
            i += 1
    return "".join(result)

def parse_request(data: bytes) -> Request:
    if not data:
        raise BadRequest("No request line")

    try:
        # Decode head as ISO-8859-1
        raw_head = data.decode('iso-8859-1')
    except UnicodeDecodeError:
        raise BadRequest("Invalid request encoding")

    lines = raw_head.split('\r\n')

    if not lines:
        raise BadRequest("Empty request")

    request_line = lines[0]
    if not request_line:
        raise BadRequest("Empty request line")

    # Parse request line: METHOD SP target SP version
    parts = request_line.split(' ')
    if len(parts) != 3:
        raise BadRequest("Invalid request line")

    method = parts[0]
    if not method.isupper() or not method.isascii():
        raise BadRequest("Invalid method")

    target = parts[1]
    if not target.startswith('/'):
        raise BadRequest("Invalid target")

    version = parts[2]
    if version not in ('HTTP/1.1', 'HTTP/1.0'):
        raise BadRequest("Invalid version")

    path, query_string = '', ''
    if '?' in target:
        path, query_string = target.split('?', 1)
    else:
        path = target

    # Parse headers
    headers = Headers()
    body_start = 0

    for i, line in enumerate(lines[1:], 1):
        if not line:
            # End of headers
            # Check for trailing content
            if body_start < len(data):
                raise BadRequest("Extra data after body")
            break

        # Check for obsolete line folding
        if line[0] in ' \t':
            raise BadRequest("Obsolete line folding")

        if ':' not in line:
            raise BadRequest(f"Invalid header line: {line}")

        name, _, value = line.partition(':')
        if not name or not name.isascii():
            raise BadRequest(f"Invalid header name: {name}")

        headers.add(name, value.strip())

    # Check for body
    transfer_encoding = headers.get('Transfer-Encoding', '').lower()
    content_length = headers.get('Content-Length')

    if content_length:
        try:
            length = int(content_length)
            if content_length != content_length.strip() or not content_length.isdigit():
                # Check if it's purely digits (no sign, no leading zeros unless 0)
                if len(content_length) > 1 and content_length[0] == '0':
                    raise BadRequest("Invalid Content-Length")
                raise BadRequest("Invalid Content-Length")
        except ValueError:
            raise BadRequest("Invalid Content-Length")

        if length > 0:
            if len(data) < length:
                raise BadRequest("Body truncated")
            body = data[body_start:]
            body_start = len(data)
        else:
            body = b''
            body_start = len(data)
    elif transfer_encoding == 'chunked':
        # Parse chunked
        body = b''
        offset = body_start

        while offset < len(data):
            line = data[offset:].split(b'\r\n', 1)[0]
            try:
                chunk_size_str = line.strip().encode('iso-8859-1') # line was already iso-8859-1? No, line is bytes here?
                # Wait, data is bytes. We need to parse bytes.
                # Let's restart the chunked parsing on bytes.
                pass
            except:
                raise BadRequest("Invalid chunked encoding")

        # Re-do chunked parsing properly on bytes
        body = b''
        pos = body_start

        while pos < len(data):
            chunk_line_end = data[pos:].find(b'\r\n')
            if chunk_line_end == -1:
                raise BadRequest("Incomplete chunked encoding")

            chunk_hex_str = data[pos:pos+chunk_line_end]
            try:
                chunk_size = int(chunk_hex_str, 16)
            except ValueError:
                raise BadRequest("Invalid chunk size")

            pos += chunk_line_end + 2 # skip \r\n

            if chunk_size == 0:
                # Check for trailers (ignored) and final \r\n
                while pos < len(data) and data[pos] != b'\r':
                    pos += 1
                if pos >= len(data):
                    raise BadRequest("Incomplete chunked encoding")
                pos += 2 # skip \r\n
                break
            else:
                chunk_data_len = chunk_size
                # Check if we have enough data
                if pos + chunk_data_len > len(data):
                    raise BadRequest("Incomplete chunk")
                body += data[pos:pos+chunk_data_len]
                pos += chunk_data_len
        else:
            # If we broke, we are done. If we didn't break, something is wrong?
            # The break happens when chunk_size is 0.
            # If loop finishes without break, it means no zero chunk found, which is invalid.
            # But the structure is `while pos < len`. If we hit end of data without 0 chunk, error.
            # The loop condition handles it.
            # Wait, if `chunk_size == 0` we break. If we exit loop normally, it means we reached end of data without seeing a 0 chunk.
