                else:
                    # Only HEAD or only GET (impossible if len>1 unless we have multiple GETs)
                    # If multiple GETs, we need to pick the first one.
                    # The spec says "patterns are tried in the order they were registered and the first match wins".
                    # But here we are iterating over self._routes which is a dict.
                    # We need to preserve order.
                    pass

        # Let's restart the resolve logic to strictly follow the spec.
        # The spec says: "patterns are tried in the order they were registered and the first match wins".
        # So we need a list of (handler, params, method) in registration order.

        # We need to store the order.
        # Let's modify the add method to store order.
        # But since we can't change the past, we will implement it now.

        # Actually, let's just iterate self._routes.items() and assume it preserves insertion order (Python 3.7+).
        # We need to handle the case where multiple patterns match.
        # The spec says "the first match wins" for patterns.
        # So we return the first one that matches?
        # No, "If no pattern matches... raise NotFound. If patterns match but none for this method, raise MethodNotAllowed with the methods of the matching patterns."
        # This implies we collect all matching patterns.

        # Let's do this:
        # 1. Collect all matching patterns (handler, params, method).
        # 2. If no matches -> NotFound.
        # 3. If matches exist:
        #    a. If only one method -> return that handler.
        #    b. If multiple methods (e.g., GET and HEAD) -> return GET handler (if HEAD requested).
        #    c. If multiple methods but not HEAD/GET mix? Then MethodNotAllowed.

        # Wait, the spec says "If patterns match but none for this method, raise MethodNotAllowed".
        # So if we have GET and POST for /users, and request GET -> return GET.
        # If request POST -> return POST.
        # If request GET and only POST matches -> MethodNotAllowed.

        # So we need to filter candidates by method first?
        # No, we need to find all patterns that match the path, regardless of method.
        # Then check if any of them match the requested method.

        all_matches = []
        for (method, pattern), handler in self._routes.items():
            if method not in ('GET', 'HEAD'):
                continue

            try:
                regex, param_groups, param_types = self._build_pattern_regex(pattern)
            except Exception:
                continue

            if regex.match(request_path):
                groups = regex.groups()
                params = {}
                for i, (name, conv_type) in enumerate(param_groups):
                    if i < len(groups):
                        val = groups[i]
                        if conv_type == 'path':
                            params[name] = val
                        elif conv_type == 'int':
                            params[name] = int(val)

                all_matches.append((handler, params, method))

        if not all_matches:
            raise NotFound()

        # Separate by method
        method_matches = {}
        for handler, params, m in all_matches:
            method_matches.setdefault(m, []).append((handler, params))

        # Check if we have a match for the requested method
        if method in method_matches:
            # If multiple handlers for the same method, pick the first one (registration order)
            return method_matches[method][0][0], method_matches[method][0][1]
        else:
            # No match for this method
            if 'HEAD' in method_matches and method == 'HEAD':
                # Serve GET
                for handler, params in method_matches['GET']:
                    return handler, params
            elif 'HEAD' in method_matches and method != 'HEAD':
                # This case shouldn't happen if we filtered by GET/HEAD
                pass
            else:
                methods_list = sorted(set(method_matches.keys()))
                raise MethodNotAllowed(methods_list)
