"""
Middleware handling and application setup.
"""

import base64
from dataclasses import dataclass
from typing import Callable, Dict, List, Tuple
from .request import Request, Response, HTTPError, BadRequest

@dataclass
class App:
    router: 'Router'
    middleware: tuple = ()

    def use(self, mw: Callable):
        self.middleware = self.middleware + (mw,)

    def handle(self, request: Request) -> Response:
        def call_next(req: Request) -> Response:
            return self._run_middleware(req)

        # Run middleware in order, first outermost
        for mw in self.middleware:
            try:
                req = mw(request, call_next)
                if not isinstance(req, Response):
                    raise BadRequest("Middleware must return Response")
                request = req
            except Exception as e:
                # Convert exception to 500 error
                response = Response(status=500)
                response.body = f"Internal Server Error: {str(e)}".encode('utf-8')
                return response

        # Innermost: router dispatch
        try:
            response = self.router.dispatch(request)
            return response
        except HTTPError as e:
            # Convert error to response
            response = Response(status=e.status)
            response.body = f"{e.status} {e.reason}".encode('utf-8')
            if isinstance(e, HTTPError):
                response.headers.add('Content-Type', 'text/plain')
            return response
        except Exception as e:
            # Any other exception becomes 500
            response = Response(status=500)
            response.body = f"Internal Server Error: {str(e)}".encode('utf-8')
            return response

    def _run_middleware(self, request: Request) -> Response:
        # This is a helper to run the rest of the chain
        # But the loop above handles the recursion.
        # Let's simplify.
        # The loop above calls call_next which eventually calls router.dispatch.
        # We need to ensure the router dispatch handles errors.
        # The router dispatch does not catch exceptions.
        # So the middleware loop must catch exceptions from router.dispatch.
        # Wait, the loop I wrote:
        # for mw in self.middleware:
        #     req = mw(request, call_next)
        # The last middleware calls call_next, which is defined as:
        # def call_next(req: Request) -> Response: return self._run_middleware(req)
        # And _run_middleware is... wait, I don't have a _run_middleware defined in App.
        # Let's fix the handle logic.

        # Correct logic:
        # def run_chain(req):
        #     if not self.middleware:
        #         return self.router.dispatch(req)
        #     else:
        #         mw = self.middleware[-1]
        #         return mw(req, lambda r: run_chain(r))

        # But the spec says: "the first one outermost".
        # So if we have mw1, mw2, router.
        # mw1(request, run_chain)
        #   run_chain -> mw2(request, run_chain)
        #     run_chain -> router.dispatch(request)
        # So the last middleware is the innermost.

        # Let's implement a closure.
        def inner(req: Request):
            if not self.middleware:
                return self.router.dispatch(req)
            mw = self.middleware[-1]
            return mw(req, inner)

        try:
            response = inner(request)
            return response
        except Exception as e:
            # Convert to 500
            response = Response(status=500)
            response.body = f"Internal Server Error: {str(e)}".encode('utf-8')
            return response

    def handle_bytes(self, data: bytes) -> bytes:
        try:
            request = parse_request(data)
            response = self.handle(request)
            return response.to_bytes()
        except BadRequest as e:
            # 400 error without middleware
            response = Response(status=400)
            response.body = f"Bad Request".encode('utf-8')
            return response.to_bytes()
        except Exception as e:
            # 500 error without middleware
            response = Response(status=500)
            response.body = f"Internal Server Error: {str(e)}".encode('utf-8')
            return response.to_bytes()

def logger(lines: list):
    def mw(request, call_next):
        response = call_next(request)
        # Extract status from response
        status = response.status
        method = request.method
        path = request.path
        lines.append(f"{method} {path} {status}")
        return response
    return mw

def cookies():
    def mw(request, call_next):
        try:
            cookie_header = request.headers.get('Cookie', '')
            if cookie_header:
                # Parse similar to Content-Type params
                parts = cookie_header.split(';')
                cookie_dict = {}
                for part in parts:
                    part = part.strip()
                    if not part:
                        continue
                    if '=' in part:
                        name, value = part.split('=', 1)
                        name = name.strip()
                        value = value.strip()
                        if value.startswith('"') and value.endswith('"'):
                            value = value[1:-1]
                        # Cookie names keep their case
                        cookie_dict[name] = value
                request.state['cookies'] = cookie_dict
            return call_next(request)
        except Exception as e:
            # Don't propagate errors from cookie parsing unless it breaks the request
            # But spec doesn't say errors in middleware are caught.
            # We assume cookies parsing is safe.
            return call_next(request)
    return mw

def basic_auth(users: dict, realm: str = 'app'):
    def mw(request, call_next):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Basic '):
            response = Response(status=401)
            response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            response.body = f"Unauthorized".encode('utf-8')
            return response

        # Decode Base64
        try:
            encoded = auth_header[6:]
            user_pass = base64.b64decode(encoded).decode('utf-8')
        except Exception:
            response = Response(status=401)
            response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            response.body = f"Unauthorized".encode('utf-8')
            return response

        user, password = user_pass.split(':', 1)

        if users.get(user) == password:
            request.state['user'] = user
            return call_next(request)
        else:
            response = Response(status=401)
            response.headers.add('WWW-Authenticate', f'Basic realm="{realm}"')
            response.body = f"Unauthorized".encode('utf-8')
            return response
    return mw
