# sheet/formula.py
import re
from dataclasses import dataclass
from typing import Any, Dict, Set, Optional, List

class FormulaError(ValueError):
    """Raised when formula syntax is invalid or references are out of bounds."""
    pass

class ErrorValue(str):
    """A string representing an error value."""
    # Compare equal to their text representation
    def __eq__(self, other):
        return str(self) == str(other)

    def __hash__(self):
        return hash(str(self))

    def __repr__(self):
        return f"ErrorValue('{self}')"

    def __str__(self):
        return self

CYCLE_ERROR = ErrorValue("#CYCLE!")
ERROR_ERROR = ErrorValue("#ERROR!")

@dataclass
class Number:
    value: float

@dataclass
class Ref:
    name: str
    value: Any

@dataclass
class Unary:
    sign: bool  # True for -, False for + (though + is handled as identity or explicit)
    operand: Any

@dataclass
class Binary:
    op: str
    left: Any
    right: Any

@dataclass
class Expr:
    # The grammar is recursive: expr = term { (+|-) term }
    # We will represent this as a list of terms separated by operators, 
    # but flattened into a tree structure that can be traversed left-to-right 
    # according to operator precedence rules during evaluation.
    # To simplify parsing and evaluation logic matching the spec:
    # We will build an expression tree where operators bind according to precedence.
    # However, a simpler approach for "left associative" and specific precedence 
    # is to build an AST.
    # Let's define a generic AST node.
    pass

# Redefining AST structure for clarity in implementation
@dataclass
class Node:
    type: str
    value: Any = None
    left: Optional['Node'] = None
    right: Optional['Node'] = None
    op: Optional[str] = None
    sign: Optional[bool] = None

    def __repr__(self):
        if self.type == "Number":
            return f"Num({self.value})"
        elif self.type == "Ref":
            return f"Ref({self.name})"
        elif self.type == "Unary":
            return f"Unary({self.sign}, {self.left})"
        elif self.type == "Binary":
            return f"Bin({self.op}, {self.left}, {self.right})"
        else:
            return f"Node({self.type})"

def parse_formula(source: str) -> Node:
    """
    Parses the text after '=' into an AST.
    Raises FormulaError on invalid syntax, references, etc.
    """
    if not source.strip():
        raise FormulaError("Empty formula")

    # Remove whitespace around the source for tokenization logic, 
    # but we need to handle spaces inside tokens? No, grammar says whitespace allowed 
    # anywhere between tokens.
    # We will use a tokenizer approach.

    tokens = tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    pos = 0
    root = parse_expr(tokens, pos)

    # Check for trailing garbage
    if pos < len(tokens):
        raise FormulaError("Unexpected characters after expression")

    return root

def tokenize(source: str) -> List[tuple]:
    """
    Tokenizes the formula string.
    Returns a list of (type, value) tuples.
    """
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        c = source[i]

        if c.isspace():
            i += 1
            continue

        if c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '*':
            tokens.append(('MULT', '*'))
            i += 1
        elif c == '/':
            tokens.append(('DIV', '/'))
            i += 1
        elif c.isdigit():
            # Number
            j = i
            has_dot = False
            if source[j] == '.':
                has_dot = True
                j += 1
            while j < n and source[j].isdigit():
                j += 1
            tokens.append(('NUMBER', float(source[i:j])))
            i = j
        elif c.isalpha():
            # Reference: letters followed by digits
            j = i
            while j < n and (source[j].isalpha() or source[j].isdigit()):
                j += 1
            name = source[i:j].upper()
            if not name[0].isalpha():
                raise FormulaError("Reference must start with a letter")
            if len(name) > 1:
                raise FormulaError("Reference can have only one letter")
            tokens.append(('REF', name))
            i = j
        else:
            raise FormulaError(f"Invalid character: {c}")

    return tokens

def parse_expr(tokens: List[tuple], pos: int) -> Node:
    """
    Parses expr := term { (+ | -) term }
    """
    left = parse_term(tokens, pos)
    pos = left.pos

    while pos < len(tokens) and tokens[pos][0] in ('PLUS', 'MINUS'):
        op = tokens[pos][1]
        pos += 1
        right = parse_term(tokens, pos)
        pos = right.pos
        left = Node(type='Binary', op=op, left=left, right=right)

    left.pos = pos
    return left

def parse_term(tokens: List[tuple], pos: int) -> Node:
    """
    Parses term := unary { (* | /) unary }
    """
    left = parse_unary(tokens, pos)
    pos = left.pos

    while pos < len(tokens) and tokens[pos][0] in ('MULT', 'DIV'):
        op = tokens[pos][1]
        pos += 1
        right = parse_unary(tokens, pos)
        pos = right.pos
        left = Node(type='Binary', op=op, left=left, right=right)

    left.pos = pos
    return left

def parse_unary(tokens: List[tuple], pos: int) -> Node:
    """
    Parses unary := (+ | -) unary | number | ref | ( expr )
    """
    if pos >= len(tokens):
        raise FormulaError("Unexpected end of formula")

    token = tokens[pos]

    if token[0] == 'PLUS':
        pos += 1
        return parse_unary(tokens, pos)
    elif token[0] == 'MINUS':
        pos += 1
        operand = parse_unary(tokens, pos)
        operand.sign = True
        return operand
    elif token[0] == 'NUMBER':
        pos += 1
        return Node(type='Number', value=token[1])
    elif token[0] == 'LPAREN':
        pos += 1
        expr = parse_expr(tokens, pos)
        pos = expr.pos
        if pos < len(tokens) and tokens[pos][0] == 'RPAREN':
            pos += 1
        return expr
    elif token[0] == 'REF':
        pos += 1
        return Node(type='Ref', name=token[1])
    else:
        raise FormulaError(f"Unexpected token: {token[0]}")

def references(tree: Node) -> Set[str]:
    """Returns the set of cell references in the formula."""
    refs = set()
    if tree.type == 'Ref':
        refs.add(tree.name)
    elif tree.type == 'Number':
        pass
    elif tree.type == 'Unary':
        if tree.left:
            refs.update(references(tree.left))
    elif tree.type == 'Binary':
        if tree.left:
            refs.update(references(tree.left))
        if tree.right:
            refs.update(references(tree.right))
    return refs

def evaluate(tree: Node, lookup: Dict[str, Any]) -> Any:
    """
    Evaluates the formula tree.
    lookup(name) returns the cell value (int, float, str, None, or ErrorValue).
    """
    # Helper to get operand value with error propagation
    def get_val(node):
        if node.type == 'Number':
            return node.value
        elif node.type == 'Ref':
            val = lookup.get(node.name)
            if val is None:
                return 0
            return val
        elif node.type == 'Unary':
            # Unary binds tighter than binary, but here we are inside unary parsing.
            # The logic: if operand is error, result is error.
            operand = get_val(node.left)
            if isinstance(operand, ErrorValue):
                return operand
            if node.sign:
                return -operand
            return +operand
        elif node.type == 'Binary':
            left_val = get_val(node.left)
            right_val = get_val(node.right)

            # Rule 3: If operand is text, result is #ERROR!
            if isinstance(left_val, str) or isinstance(right_val, str):
                return ERROR_ERROR

            # Rule 3: If operand is error, result is that error (left if both)
            if isinstance(left_val, ErrorValue):
                return left_val
            if isinstance(right_val, ErrorValue):
                return right_val

            # Type coercion and arithmetic
            if left_val == 0 and right_val == 0:
                if isinstance(left_val, int) and isinstance(right_val, int):
                    return ERROR_ERROR
                # Division by zero float check is implicit in Python 3 but let's be explicit per spec
                # Actually Python 3 / always returns float, 0/0 is ErrorValue.
                # But spec says: "dividing by zero gives #ERROR!".
                if left_val == 0.0:
                    return ERROR_ERROR

            if isinstance(left_val, float) or isinstance(right_val, float):
                if node.op == '/':
                    return left_val / right_val
                elif node.op == '*':
                    return left_val * right_val
                elif node.op == '+':
                    return left_val + right_val
                elif node.op == '-':
                    return left_val - right_val
            else:
                # Both ints
                if node.op == '/':
                    return left_val / right_val
                elif node.op == '*':
                    return left_val * right_val
                elif node.op == '+':
                    return left_val + right_val
                elif node.op == '-':
                    return left_val - right_val

    return get_val(tree)
