from typing import Set, Dict

class DependencyGraph:
    def __init__(self):
        # precedents[cell] -> set of cells this cell refers to
        self._precedents: Dict[str, Set[str]] = {}
        # dependents[cell] -> set of cells that refer to this cell
        self._dependents: Dict[str, Set[str]] = {}

        # Initialize with empty sets for potential keys
        self._all_keys: Set[str] = set()

    def set_dependencies(self, cell: str, precedents: Set[str]) -> None:
        """
        Replaces the precedents for 'cell' with the given set.
        All names are assumed to be upper case.
        """
        if cell not in self._all_keys:
            self._all_keys.add(cell)
            self._dependents[cell] = set()
            self._precedents[cell] = set()

        # Remove old dependents if they existed (since precedents are being replaced)
        # Wait, the spec says "replaces cell's precedents". 
        # If we change precedents, we must update dependents.
        # Old dependents are those that had this cell as a precedent.

        # 1. Clear current dependents of this cell
        if cell in self._dependents:
            old_deps = self._dependents[cell]
            del self._dependents[cell]

        # 2. Update this cell's dependents
        for dep in old_deps:
            if dep in self._precedents and cell in self._precedents[dep]:
                self._precedents[dep].discard(cell)
                # We don't need to remove from _dependents of dep here because we cleared it above?
                # No, we need to track who depends on whom.
                # Let's rethink:
                # _precedents[A] = {B, C} means A depends on B and C.
                # _dependents[B] should contain A.

                # So when replacing precedents of A:
                # 1. Identify who currently has A in their _precedents. These are A's old dependents.
                # 2. Remove A from those sets.
                # 3. Add the new precedents to the sets of dependents.
                pass

        # Let's do it cleanly:
        # Step 1: Find all cells that currently have 'cell' as a precedent.
        old_dependents = set()
        for other_cell, preds in self._precedents.items():
            if cell in preds:
                old_dependents.add(other_cell)

        # Step 2: Remove 'cell' from the precedents of those old dependents
        for other_cell in old_dependents:
            self._precedents[other_cell].discard(cell)

        # Step 3: Remove 'cell' from its own dependents (it doesn't depend on itself via precedents logic usually, 
        # but if it was added via a cycle, it should be handled. Actually, precedents are explicit links).
        # If 'cell' was in its own precedents, it would be in old_dependents.
        # We removed it. So 'cell' is no longer a dependent of itself? 
        # Yes, unless the new precedents include it.

        # Step 4: Add the new precedents to the dependents of those new cells.
        for pred in precedents:
            if pred in self._precedents:
                self._dependents.setdefault(pred, set()).add(cell)
            else:
                # If pred is not in _all_keys yet (e.g. a new formula reference), 
                # we need to ensure it exists in _dependents but it has no dependents yet.
                # Actually, if pred is not in _precedents, it has no dependents.
                # But we need to track 'all_dependents' which might traverse into it.
                # We should add 'pred' to _all_keys if not present.
                if pred not in self._all_keys:
                    self._all_keys.add(pred)
                    self._precedents[pred] = set() # Ensure existence
                self._dependents.setdefault(pred, set()).add(cell)

        self._precedents[cell] = precedents
        if cell not in self._dependents:
            self._dependents[cell] = set()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct cells this cell refers to."""
        self._ensure_key(cell)
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct cells that refer to this cell."""
        self._ensure_key(cell)
        return self._dependents.get(cell, set())

    def _ensure_key(self, cell: str):
        if cell not in self._all_keys:
            self._all_keys.add(cell)
            self._dependents[cell] = set()
            self._precedents[cell] = set()

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or indirectly.
        Includes 'cell' itself only if 'cell' is on a cycle.
        """
        result = set()
        queue = list(self.dependents(cell))

        while queue:
            current = queue.pop(0)
            if current not in result:
                result.add(current)
                queue.extend(self.dependents(current))

        # Check if cell is on a cycle
        # A cell is on a cycle if there exists a path from cell to cell via precedents.
        # Since we only need to know if 'cell' is in the set of all_dependents if it's on a cycle:
        # If cell is on a cycle, it must be reachable from itself via precedents.
        # Does all_dependents include itself on a cycle?
        # "It contains cell itself only when cell is on a cycle."
        # If cell is on a cycle, then cell depends on ... depends on ... depends on cell.
        # So cell is in the transitive closure of dependents?
        # Not necessarily. 
        # Example: A -> B -> A. 
        # dependents(A) = {B}. dependents(B) = {A}.
        # BFS from A: {B}, then {A}. Result {A, B}. Correct.
        # Example: A -> B. 
        # dependents(A) = {B}. Result {B}. A is not in cycle. Correct.

        return result

    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle.
        A cell is on a cycle if following its precedents leads back to itself.
        """
        cycles = set()
        # Find all cells that can reach themselves
        for cell in self._all_keys:
            if self._is_on_cycle(cell):
                cycles.add(cell)
        return cycles

    def _is_on_cycle(self, cell: str) -> bool:
        """
        Check if 'cell' is part of a cycle.
        We do a DFS/BFS on the PRECEDENTS graph starting from 'cell'.
        If we encounter 'cell' again, it's a cycle.
        """
        visited = set()
        stack = [cell]

        while stack:
            current = stack.pop()
            if current in visited:
                # If we visited current again, it's a cycle?
                # Wait, standard cycle detection in directed graph:
                # If we see a node that is currently in the recursion stack (gray), it's a cycle.
                pass

            if current == cell:
                # We found a path back to cell
                return True

            visited.add(current)

            for pred in self.precedents(current):
                if pred not in visited:
                    stack.append(pred)

        return False
