        # However, we must respect the cycle rule: cycle cells are not evaluated.

        # First, find all cells that will be affected.
        # The spec says: "set evaluates each formula cell in its returned list that is not on a cycle exactly once".
        # The returned list includes all_dependents.

        cells_to_eval = self._graph.all_dependents(name)
        if name in cells_to_eval:
            cells_to_eval.discard(name) # Don't evaluate 'name' again if it's a cycle? 
            # Wait, if 'name' is on a cycle, it's not evaluated. 
