                # We need to create a lookup for the current values of cells_to_update
                current_vals = {c: self._cells[c] for c in cells_to_update}
                val = evaluate(tree, current_vals)
                self._cells[cell] = val
                self._evaluations += 1
            else:
                # It's a literal or None or ErrorValue. 
                # But wait, if it's a literal, we set it in 'set'.
                # If it's an error value from a previous cycle, it stays.
                # If it's a formula that resulted in an error, we updated it.
                # If it's a formula that resulted in a cycle, we set it to #CYCLE! in the first place?
                # The spec: "A cell on a cycle has the value #CYCLE! and is not evaluated."
                # We filtered cycle_cells, so we don't evaluate them.
                # But what about a cell that is NOT a cycle, but refers to a cycle?
                # It gets #CYCLE! via evaluation.
                # Our loop handles this: if it's a formula, we evaluate it. The evaluation returns #CYCLE! (propagated).
                # So we overwrite the old value with the new calculated value.
                pass

    def _sort_row_major(self, items: Set[str]) -> List[str]:
        """Sorts cell names by row number, then column letter."""
        def sort_key(name):
            # Extract column and row
            # Name: A1, Z100, etc.
            # Column is letter(s)? Spec says "one column letter".
            # "A to Z", "one column letter".
            col_char = name[0]
            row = int(name[1:])
            # Order: Row first, then Col
            # Row is ascending. Col is A, B, ..., Z.
            # Python string comparison for A-Z works.
            return (row, col_char)

        return sorted(items, key=sort_key)
