# sheet/formula.py
import re
from dataclasses import dataclass
from typing import Any, Dict, Set, List, Optional, Tuple

# Error Values
class FormulaError(ValueError):
    """Raised when formula syntax is invalid."""
    pass

class ErrorValue(str):
    """A string representing an error value."""
    def __eq__(self, other):
        return str(self) == str(other)
    def __hash__(self):
        return hash(str(self))
    def __repr__(self):
        return f"ErrorValue('{self}')"
    def __str__(self):
        return self

DIV_ZERO = ErrorValue("#DIV/0!")
VALUE_ERROR = ErrorValue("#VALUE!")
REF_ERROR = ErrorValue("#REF!")
CYCLE_ERROR = ErrorValue("#CYCLE!")

# AST Nodes
@dataclass
class Number:
    value: float

@dataclass
class Ref:
    name: str
    value: Any

@dataclass
class Unary:
    sign: bool
    operand: Any

@dataclass
class Binary:
    op: str
    left: Any
    right: Any

@dataclass
class Call:
    name: str
    args: List[Any]  # List of evaluated results

@dataclass
class RangeNode:
    min_ref: str
    max_ref: str

@dataclass
class ArgNode:
    # For a range: contains the two refs. For an expr: contains the parsed tree.
    range_refs: Optional[Tuple[str, str]] = None
    tree: Optional[Number] = None # Used temporarily during parsing for ranges, or None if it's a sub-call
    is_range: bool = False

    @property
    def is_range(self):
        return self.range_refs is not None

    @property
    def tree(self):
        return self.tree

# Renamed to avoid conflict with standard list
@dataclass
class Node:
    type: str
    value: Any = None
    left: Optional['Node'] = None
    right: Optional['Node'] = None
    op: Optional[str] = None
    sign: Optional[bool] = None
    call_name: Optional[str] = None
    args: Optional[List[Any]] = None
    min_ref: Optional[str] = None
    max_ref: Optional[str] = None

    def __repr__(self):
        if self.type == "Number":
            return f"Num({self.value})"
        elif self.type == "Ref":
            return f"Ref({self.name})"
        elif self.type == "Unary":
            return f"Unary({self.sign}, {self.left})"
        elif self.type == "Binary":
            return f"Bin({self.op}, {self.left}, {self.right})"
        elif self.type == "Call":
            return f"Call({self.call_name}, {self.args})"
        elif self.type == "RangeNode":
            return f"Range({self.min_ref}:{self.max_ref})"
        else:
            return f"Node({self.type})"

def tokenize(source: str) -> List[tuple]:
    """Tokenizes the formula string."""
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        c = source[i]

        if c.isspace():
            i += 1
            continue

        if c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
        elif c == ',':
            tokens.append(('COMMA', ','))
            i += 1
        elif c == ':':
            tokens.append(('COLON', ':'))
            i += 1
        elif c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
        elif c == '*':
            tokens.append(('MULT', '*'))
            i += 1
        elif c == '/':
            tokens.append(('DIV', '/'))
            i += 1
        elif c.isdigit():
            j = i
            if source[j] == '.':
                j += 1
            while j < n and source[j].isdigit():
                j += 1
            tokens.append(('NUMBER', float(source[i:j])))
            i = j
        elif c.isalpha():
            j = i
            while j < n and (source[j].isalpha() or source[j].isdigit()):
                j += 1
            name = source[i:j].upper()
            if not name[0].isalpha() or len(name) > 1:
                raise FormulaError("Reference or function name must be a single letter")
            tokens.append(('NAME', name))
            i = j
        else:
            raise FormulaError(f"Invalid character: {c}")

    return tokens

def parse_formula(source: str) -> Node:
    """Parses the text after '=' into an AST."""
    if not source.strip():
        raise FormulaError("Empty formula")

    tokens = tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    pos = 0
    root = parse_expr(tokens, pos)

    if pos < len(tokens):
        raise FormulaError("Unexpected characters after expression")

    return root

def parse_expr(tokens: List[tuple], pos: int) -> Node:
    """expr := term { (+ | -) term }"""
    left = parse_term(tokens, pos)
    pos = left.pos

    while pos < len(tokens) and tokens[pos][0] in ('PLUS', 'MINUS'):
        op = tokens[pos][1]
        pos += 1
        right = parse_term(tokens, pos)
        pos = right.pos
        left = Node(type='Binary', op=op, left=left, right=right)

    left.pos = pos
    return left

def parse_term(tokens: List[tuple], pos: int) -> Node:
    """term := unary { (* | /) unary }"""
    left = parse_unary(tokens, pos)
    pos = left.pos

    while pos < len(tokens) and tokens[pos][0] in ('MULT', 'DIV'):
        op = tokens[pos][1]
        pos += 1
        right = parse_unary(tokens, pos)
        pos = right.pos
        left = Node(type='Binary', op=op, left=left, right=right)

    left.pos = pos
    return left

def parse_unary(tokens: List[tuple], pos: int) -> Node:
    """unary := (+ | -) unary | number | ref | call | ( expr )"""
    if pos >= len(tokens):
        raise FormulaError("Unexpected end of formula")

    token = tokens[pos]

    if token[0] == 'PLUS':
        pos += 1
        operand = parse_unary(tokens, pos)
        operand.sign = True
        return operand
    elif token[0] == 'MINUS':
        pos += 1
        operand = parse_unary(tokens, pos)
        operand.sign = True
        return operand
    elif token[0] == 'NUMBER':
        pos += 1
        return Node(type='Number', value=token[1])
    elif token[0] == 'LPAREN':
        pos += 1
        expr = parse_expr(tokens, pos)
        pos = expr.pos
        if pos < len(tokens) and tokens[pos][0] == 'RPAREN':
            pos += 1
        return expr
    elif token[0] == 'NAME':
        fname = token[1]
        # Check function call
        if pos + 1 >= len(tokens) or tokens[pos+1][0] != 'LPAREN':
            raise FormulaError(f"Function '{fname}' missing arguments")

        pos += 2 # Skip name and '('

        # Parse arguments
        args = []
        while pos < len(tokens):
            if tokens[pos][0] == 'RPAREN':
                pos += 1
                break

            arg_node = parse_arg(tokens, pos)
            pos = arg_node.pos
            args.append(arg_node)

            if pos < len(tokens) and tokens[pos][0] == 'COMMA':
                pos += 1
            else:
                break

        if not args:
            raise FormulaError(f"Function '{fname}' requires at least one argument")

        # Check for trailing garbage
        if pos < len(tokens) and tokens[pos][0] != 'RPAREN':
            raise FormulaError(f"Unexpected characters after function call for '{fname}'")

        return Node(type='Call', call_name=fname, args=args)
    else:
        raise FormulaError(f"Unexpected token: {token[0]}")

def parse_arg(tokens: List[tuple], pos: int) -> ArgNode:
    """arg := ref : ref | expr"""
    node = ArgNode()

    # Check if this is a range: starts with a reference
    if tokens[pos][0] == 'REF':
        pos += 1
        min_ref = tokens[pos-1][1]

        # Expect colon
        if pos >= len(tokens) or tokens[pos][0] != 'COLON':
            raise FormulaError("Range separator ':' missing")
        pos += 1

        # Expect second reference
        if pos >= len(tokens) or tokens[pos][0] != 'REF':
            raise FormulaError("Range end reference missing")

        node.range_refs = (min_ref, tokens[pos][1])
        pos += 1
        node.is_range = True

        # Consume rest of the range if it had parentheses? No, range is just ref:ref
        return node

    # Otherwise it's an expression
    tree = parse_expr(tokens, pos)
    node.tree = tree
    pos = tree.pos

    # Check for trailing garbage inside arg? The grammar says arg is either range or expr.
    # If it was expr, there shouldn't be unexpected tokens unless they are part of next arg.
    return node

def references(tree: Node) -> Set[str]:
    """Returns the set of cell references inside the formula (inside ranges)."""
    refs = set()

    def visit(node):
        if node.type == 'Ref':
            refs.add(node.name)
        elif node.type == 'Number':
            pass
        elif node.type == 'Unary':
            if node.left:
                visit(node.left)
        elif node.type == 'Binary':
            if node.left:
                visit(node.left)
            if node.right:
                visit(node.right)
        elif node.type == 'Call':
            for arg in node.args:
                if hasattr(arg, 'range_refs'):
                    if arg.range_refs:
                        r1, r2 = arg.range_refs
                        refs.add(r1)
                        refs.add(r2)
                elif hasattr(arg, 'tree'):
                    visit(arg.tree)
                elif hasattr(arg, 'type'):
                    visit(arg)
        elif node.type == 'RangeNode':
            refs.add(node.min_ref)
            refs.add(node.max_ref)

    visit(tree)
    return refs

def evaluate(tree: Node, lookup: Dict[str, Any]) -> Any:
    """Evaluates the formula tree."""
    def get_val(node):
        if node.type == 'Number':
            return node.value
        elif node.type == 'Ref':
            val = lookup.get(node.name)
            if val is None:
                return 0
            return val
        elif node.type == 'Unary':
            operand = get_val(node.left)
            if isinstance(operand, ErrorValue):
                return operand
            if node.sign:
                return -operand
            return +operand
        elif node.type == 'Binary':
            # Evaluate left to right
            left_val = get_val(node.left)
            right_val = get_val(node.right)

            # Error propagation: if any operand is error, result is leftmost error
            if isinstance(left_val, ErrorValue):
                return left_val
            if isinstance(right_val, ErrorValue):
                return right_val

            # Text check
            if isinstance(left_val, str) or isinstance(right_val, str):
                return VALUE_ERROR

            # Arithmetic
            if left_val == 0.0 or right_val == 0.0:
                if isinstance(left_val, int) and isinstance(right_val, int):
                    return DIV_ZERO
                # Python 3 division always yields float
                if left_val == 0.0 or right_val == 0.0:
                     return DIV_ZERO

            if isinstance(left_val, float) or isinstance(right_val, float):
                return eval_op(node.op, left_val, right_val)
            else:
                return eval_op(node.op, left_val, right_val)

        elif node.type == 'Call':
            return eval_call(node)

        elif node.type == 'RangeNode':
            return eval_range(node, lookup)

        return 0

    def eval_call(call_node: Node) -> Any:
        # Evaluate arguments left to right
        results = []
        for arg in call_node.args:
            if hasattr(arg, 'range_refs'):
                # Range arg
                if not arg.range_refs:
                    return VALUE_ERROR # Missing refs
                min_r, max_r = arg.range_refs

                # Check if range is valid (corners in sheet)
                # We need to check if min_r and max_r are valid sheet cells.
                # Note: The lookup dict only contains cells we have.
                # If a ref is in the formula but not in 'lookup' (i.e., outside sheet),
                # get_val returns 0, which is wrong for REF_ERROR.
                # However, get_val checks lookup.get(name). If name not in lookup, returns 0.
                # We must handle REF_ERROR specifically here or in get_val.
                # The spec says: "Any reference to a cell outside the sheet ... gives #REF!".
                # But get_val is used for nested expressions too. 
                # Let's handle REF_ERROR in get_val if the cell is not in lookup.
                pass

                min_val = get_val_for_ref(min_r)
                max_val = get_val_for_ref(max_r)

                if isinstance(min_val, ErrorValue):
                    return min_val
                if isinstance(max_val, ErrorValue):
                    return max_val

                # Collect numbers
                nums = collect_range(min_r, max_r)
                if not nums:
                    # Empty range of numbers
                    if call_node.call_name == 'AVG':
                        return DIV_ZERO
                    elif call_node.call_name in ('MIN', 'MAX'):
                        return 0
                    else:
                        return 0 # SUM of empty is 0
                elif isinstance(nums[0], ErrorValue):
                    return nums[0]
                else:
                    return process_call(call_node.call_name, nums)

            elif hasattr(arg, 'tree'):
                # Expression arg
                val = get_val(arg.tree)
                results.append(val)
                if isinstance(val, ErrorValue):
                    return val
            else:
                # Should not happen with valid parse
                results.append(get_val(arg))
                if isinstance(results[-1], ErrorValue):
                    return results[-1]

        # All args evaluated successfully
        if call_node.call_name == 'SUM':
            return process_call('SUM', results)
        elif call_node.call_name == 'AVG':
            return process_call('AVG', results)
        elif call_node.call_name == 'MIN':
            return process_call('MIN', results)
        elif call_node.call_name == 'MAX':
            return process_call('MAX', results)
        else:
            raise FormulaError(f"Unknown function: {call_node.call_name}")

    def get_val_for_ref(name: str) -> Any:
        val = lookup.get(name)
        if val is None:
            return REF_ERROR
        return val

    def collect_range(min_r: str, max_r: str) -> List[Any]:
        # Determine bounds
        c1, r1 = parse_cell(min_r)
        c2, r2 = parse_cell(max_r)

        # Normalize order
        start_c, start_r = min(c1, c2), min(r1, r2)
        end_c, end_r = max(c1, c2), max(r1, r2)

        # Check if corners are outside sheet
        if start_c < 'A' or start_r < 1 or end_c > 'Z' or end_r > 999:
            return [REF_ERROR]

        # Collect numbers
        nums = []
        # Row major traversal
        for row in range(start_r, end_r + 1):
            for col_code in range(ord(start_c), ord(end_c) + 1):
                col_char = chr(col_code)
                cell_name = col_char + str(row)
                val = get_val_for_ref(cell_name)
                if isinstance(val, ErrorValue):
                    return [val]
                if val is not None and not isinstance(val, str):
                    nums.append(val)

        return nums

    def process_call(func: str, nums: List[Any]) -> Any:
        if not nums:
            if func == 'AVG':
                return DIV_ZERO
            elif func in ('MIN', 'MAX'):
                return 0
            else:
                return 0

        if func == 'SUM':
            # Integers -> Int, else Float
            all_int = all(isinstance(n, int) and not isinstance(n, bool) for n in nums)
            if all_int:
                return sum(nums)
            else:
                return float(sum(nums))

        if func == 'AVG':
            return float(sum(nums)) / len(nums)

        if func == 'MIN':
            return min(nums)

        if func == 'MAX':
            return max(nums)

        return 0

    def eval_range(node: Node, lookup: Dict[str, Any]) -> Any:
        # This function is called by get_val for RangeNode
        # It effectively does the same as the range arg logic but returns the result directly.
        # But wait, RangeNode in the AST represents the result of parsing "B3:A1".
        # The evaluation logic for a range is identical to the argument logic.

        # We need to re-parse the range refs to determine bounds because the node has them.
        # Actually, parse_cell is sufficient.
        c1, r1 = parse_cell(node.min_ref)
        c2, r2 = parse_cell(node.max_ref)

        start_c, start_r = min(c1, c2), min(r1, r2)
        end_c, end_r = max(c1, c2), max(r1, r2)

        if start_c < 'A' or start_r < 1 or end_c > 'Z' or end_r > 999:
            return REF_ERROR

        nums = []
        for row in range(start_r, end_r + 1):
            for col_code in range(ord(start_c), ord(end_c) + 1):
                col_char = chr(col_code)
                cell_name = col_char + str(row)
                val = lookup.get(cell_name)
                if val is None:
                    val = 0
                    # If val is 0, it's a number.
                    # Wait, lookup returns None for empty.
                    # If val is None, we treat as 0.
                    # But we need to distinguish between "empty (0)" and "error".
                    # If val is None, it's 0.
                    # If val is ErrorValue, we propagate.
                    # If val is string, it's error.

                if isinstance(val, ErrorValue):
                    return val
                if val is not None and not isinstance(val, str):
                    nums.append(val)

        if not nums:
            return 0 # SUM of empty range is 0. AVG is DIV_ZERO.

        if node.call_name == 'AVG': # Wait, RangeNode doesn't store call_name in my previous definition?
            # Ah, my RangeNode definition above didn't have call_name.
            # But in the grammar, range is an ARGUMENT.
            # So when evaluating a formula containing "=SUM(A1:A3)", 
            # the parser creates a Call node with args=[ArgNode(range_refs=(A1, A3))].
            # It does NOT create a RangeNode for the whole formula.
            # So `evaluate` should never see a `RangeNode` type unless I changed the grammar.
            # The grammar says: call := fname ( arg {, arg} ). arg := ref : ref | expr.
            # So the tree for "=SUM(A1:A3)" is Call -> [ArgNode(range_refs=(A1,A3))].
            # So I don't need to handle RangeNode in evaluate().
            # I only need to handle ArgNode where is_range is True.
            pass

        if nums:
            return process_call(node.call_name, nums) # Wait, node.call_name is not on RangeNode
            # Re-check: RangeNode is not in the AST for args. ArgNode is.
            # So `evaluate` logic inside `get_val` for ArgNode handles the range.
            # So I don't need a RangeNode type in the main AST?
            # Yes, `arg` is represented by `ArgNode`.
            # So I can remove `RangeNode` from the AST and just use `ArgNode`.
            pass

        return 0

    def parse_cell(name: str) -> Tuple[str, int]:
        """Parse a cell name to column char and row int."""
        # Ensure uppercase
        name = name.upper()
        if not name[0].isalpha() or not name[1:].isdigit():
            raise ValueError(f"Invalid cell name: {name}")

        col_char = name[0]
        if col_char < 'A' or col_char > 'Z':
            raise ValueError(f"Invalid column: {col_char}")

        try:
            row = int(name[1:])
            if row <= 0 or row > 999:
                raise ValueError(f"Row out of bounds: {row}")
        except ValueError:
            raise ValueError(f"Invalid row: {name[1:]}")

        return col_char, row

    return get_val(tree)
