from typing import Set, Dict

class DependencyGraph:
    def __init__(self):
        self._precedents: Dict[str, Set[str]] = {}
        self._dependents: Dict[str, Set[str]] = {}
        self._all_keys: Set[str] = set()

    def set_dependencies(self, cell: str, precedents: Set[str]) -> None:
        if cell not in self._all_keys:
            self._all_keys.add(cell)
            self._dependents[cell] = set()
            self._precedents[cell] = set()

        # Identify old dependents (cells that have 'cell' as a precedent)
        old_dependents = set()
        for other_cell, preds in self._precedents.items():
            if cell in preds:
                old_dependents.add(other_cell)

        # Remove 'cell' from their precedents
        for other_cell in old_dependents:
            self._precedents[other_cell].discard(cell)

        # Remove 'cell' from its own dependents (it shouldn't be in its own dependents unless it's a cycle, 
        # but we are updating precedents, so we clear the link first).
        # Actually, if 'cell' was in its own precedents, it was in old_dependents.
        # We removed it. So 'cell' is no longer a dependent of itself.
        # We need to ensure 'cell' exists in _dependents.
        if cell not in self._dependents:
            self._dependents[cell] = set()

        # Add new dependents
        for pred in precedents:
            if pred in self._precedents:
                self._dependents.setdefault(pred, set()).add(cell)
            else:
                if pred not in self._all_keys:
                    self._all_keys.add(pred)
                    self._precedents[pred] = set()
                    self._dependents[pred] = set()
                self._dependents[pred].add(cell)

        self._precedents[cell] = precedents

    def precedents(self, cell: str) -> Set[str]:
        self._ensure_key(cell)
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        self._ensure_key(cell)
        return self._dependents.get(cell, set())

    def _ensure_key(self, cell: str):
        if cell not in self._all_keys:
            self._all_keys.add(cell)
            self._dependents[cell] = set()
            self._precedents[cell] = set()

    def all_dependents(self, cell: str) -> Set[str]:
        result = set()
        queue = list(self.dependents(cell))

        while queue:
            current = queue.pop(0)
            if current not in result:
                result.add(current)
                queue.extend(self.dependents(current))

        # Check if cell is on a cycle
        if self._is_on_cycle(cell):
            result.add(cell)

        return result

    def cycle_cells(self) -> Set[str]:
        cycles = set()
        for cell in self._all_keys:
            if self._is_on_cycle(cell):
                cycles.add(cell)
        return cycles

    def _is_on_cycle(self, cell: str) -> bool:
        visited = set()
        stack = [cell]

        while stack:
            current = stack.pop()
            if current in visited:
                continue

            visited.add(current)

            for pred in self.precedents(current):
                if pred == cell:
                    return True
                if pred not in visited:
                    stack.append(pred)

        return False
