# sheet/sheet.py
from typing import Dict, List, Set, Any
from .formula import parse_formula, references, evaluate, ErrorValue
from .graph import DependencyGraph

class Sheet:
    def __init__(self):
        self._cells: Dict[str, Any] = {}
        self._raw_values: Dict[str, str] = {}
        self._graph = DependencyGraph()
        self._evaluations = 0
        self._all_cells: Set[str] = set()

    def _validate_name(self, name: str) -> None:
        if not (1 <= len(name) <= 3 and name[0].isalpha() and name[1:].isdigit()):
            raise ValueError(f"Invalid cell name: {name}")
        if len(name) > 1:
            row = int(name[1:])
            if row < 1 or row > 999:
                raise ValueError(f"Row out of bounds: {name}")

    def set(self, name: str, raw: str) -> List[str]:
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        self._validate_name(name)
        self._raw_values[name] = raw

        if raw.startswith('='):
            formula_text = raw[1:].strip()
            try:
                tree = parse_formula(formula_text)
                new_precs = references(tree)
                self._graph.set_dependencies(name, new_precs)

                # Ensure the cell is in all_cells if it's a formula
                if name not in self._all_cells:
                    self._all_cells.add(name)

                self._recalculate(name)

            except FormulaError:
                raise

        else:
            cleaned = raw.strip()
            if cleaned == '':
                self._cells[name] = None
            elif cleaned.startswith('-'):
                num_str = cleaned[1:]
                if '.' in num_str:
                    self._cells[name] = float(num_str)
                else:
                    self._cells[name] = int(num_str)
            else:
                self._cells[name] = raw

            self._graph.set_dependencies(name, set())

        changed = set()
        changed.add(name)
        for dep in self._graph.all_dependents(name):
            changed.add(dep)

        return self._sort_row_major(changed)

    def get(self, name: str) -> Any:
        self._validate_name(name)
        return self._cells.get(name)

    def raw(self, name: str) -> str:
        self._validate_name(name)
        return self._raw_values.get(name, '')

    def cells(self) -> List[str]:
        non_empty = {k for k, v in self._cells.items() if v is not None}
        return self._sort_row_major(non_empty)

    @property
    def evaluations(self) -> int:
        return self._evaluations

    def _recalculate(self, name: str) -> None:
        cycle_set = self._graph.cycle_cells()

        # Cells to update: {name} + all_dependents
        cells_to_update = {name} | set(self._graph.all_dependents(name))
        cells_to_update = cells_to_update - cycle_set

        # Identify subgraph nodes (only those that need evaluation)
        # We need to ensure we only evaluate formulas in this set.
        # Precedents outside this set are assumed up-to-date.

        # Build local precedents map for the subset
        local_precs = {}
        for c in cells_to_update:
            # Get precedents that are ALSO in cells_to_update
            # If a cell refers to something outside, that something is already fresh.
            precs = self._graph.precedents(c) & cells_to_update
            local_precs[c] = precs

        # Topological sort
        in_degree = {c: len(local_precs[c]) for c in cells_to_update}
        queue = [c for c in cells_to_update if in_degree[c] == 0]
        result_order = []

        while queue:
            node = queue.pop(0)
            result_order.append(node)

            for dependent in self._dependents.get(node, set()):
                if dependent in cells_to_update:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        queue.append(dependent)

        # Evaluate in order
        for cell in result_order:
            if cell in self._cells and self._cells[cell] is not None:
                # Check if it was a formula
                raw_val = self._raw_values.get(cell)
                if raw_val and raw_val.startswith('='):
                    # It's a formula. Evaluate.
                    # But wait, if it's on a cycle, we excluded it.
                    # If it's not on a cycle, we evaluate it.
                    # However, we must be careful: if a formula cell refers to a cell that is NOT in cells_to_update,
                    # but that cell is an error, we propagate the error.

                    # We need a lookup that includes ALL cells in the sheet (or at least the ones referenced).
                    # But we only care about evaluating THIS cell.
                    # The spec says: "evaluates ... after all of the cells it refers to are up to date".
                    # Cells it refers to that are NOT in cells_to_update are already up to date.
                    # Cells it refers to that ARE in cells_to_update are being evaluated now (and earlier in this loop).

                    # So we need a fresh lookup for the current state of all referenced cells.
                    # The easiest way is to just use `self._cells` but ensure it reflects the new values we just computed.
                    # Since we iterate topologically, when we are at `cell`, all its precedents in the subgraph 
                    # have already been updated in `self._cells`.

                    # One edge case: a cell refers to a cell outside the subgraph.
                    # That cell's value is in `self._cells` and hasn't changed.
                    # So `self._cells` is sufficient.

                    tree = parse_formula(raw_val)
                    # Evaluate with current state
                    val = evaluate(tree, self._cells)
                    self._cells[cell] = val
                    self._evaluations += 1
                else:
                    # It's a literal or None or ErrorValue.
                    # If it was an ErrorValue from a previous cycle, we leave it alone?
                    # No, if it's in `cells_to_update`, it must have been a formula that resulted in an error?
                    # Or maybe it was a literal that we didn't set?
                    # If it's a literal, we set it in `set`.
                    # If it's an error, we evaluate the formula and get the error.
                    # If it's None (empty), we leave it None.
                    pass

    def _sort_row_major(self, items: Set[str]) -> List[str]:
        def sort_key(name):
            col_char = name[0]
            row = int(name[1:])
            return (row, col_char)
        return sorted(items, key=sort_key)
