        o_count = board.count('O')
        if o_count > x_count or x_count > o_count + 1:
            raise ValueError("Board state is impossible")

        self._board = board
        self._x_count = x_count
        self._o_count = o_count
        self._player = 'X' if self._x_count == self._o_count else 'O'
        self._over = False

