        if self._board[move] != '.':
            raise ValueError("Square is taken")

        new_board = list(self._board)
        new_board[move] = self._player
        self._player = 'X' if self._player == 'O' else 'O'

        x_count = new_board.count('X')
        o_count = new_board.count('O')
        self._x_count = x_count
        self._o_count = o_count

        if x_count == o_count + 1 or x_count == o_count:
            # Check win
            winner = self._check_winner(new_board)
            if winner:
                self._over = True
        else:
            self._over = False

        # Note: The implementation above modifies self. 
        # The spec says "play(move) -> a new state".
        # I need to return a new instance without mutating self.

