        if nx == no + 1 or nx == no:
            new_state._over = self._check_winner(''.join(new_board)) != None
        else:
             # Actually, let's just compute winner and set over based on that
             w = self._check_winner(''.join(new_board))
             new_state._over = w is not None

        # Correct logic for _over inside the new state creation to be safe
        # Re-implementing play to be purely functional as per spec
        pass

    def _check_winner(self, b: str) -> Optional[str]:
        # Rows
        for i in range(0, 9, 3):
            if b[i] != '.' and b[i] == b[i+1] == b[i+2] == b[i]:
                return b[i]
        # Cols
        for i in range(3):
            if b[i] != '.' and b[i] == b[i+3] == b[i+6] == b[i]:
                return b[i]
        # Diagonals
        if b[0] != '.' and b[0] == b[4] == b[8] == b[0]:
            return b[0]
        if b[2] != '.' and b[2] == b[4] == b[6] == b[2]:
            return b[2]
        return None

    def play_correct(self, move: int) -> TicTacToe:
        if self._over:
            raise ValueError("Game is over")
        if not (0 <= move < 9):
            raise ValueError("Move index out of range")
        if self._board[move] != '.':
            raise ValueError("Square is taken")

        new_board = list(self._board)
        new_board[move] = self._player

        # Determine next player and counts for the new state
        if self._player == 'X':
            self._player = 'O'
        else:
            self._player = 'X'

        nx = new_board.count('X')
        no = new_board.count('O')

        # Calculate winner for the new state
        w = self._check_winner(''.join(new_board))
        is_over = (w is not None) or (nx == no == 4) # 5 marks means over

        return TicTacToe(''.join(new_board))

    @property
    def winner(self) -> Optional[str]:
        return self._check_winner(self._board)

    @property
    def is_over(self) -> bool:
        return self._over or (self._board.count('X') == 4 and self._board.count('O') == 4)

    def __str__(self) -> str:
        return self._board

    def __eq__(self, other):
        if not isinstance(other, TicTacToe):
            return False
        return self._board == other._board

    def __hash__(self):
        return hash(self._board)

    def __repr__(self):
        return f"TicTacToe({self!r})"

    @classmethod
    def from_moves(cls, moves: list[int]) -> TicTacToe:
        if len(moves) > 9:
            raise ValueError("Too many moves")

        # Check for duplicates or out of bounds during construction
        seen = set()
        for m in moves:
            if m < 0 or m >= 9:
                raise ValueError(f"Move {m} out of range")
            if m in seen:
                raise ValueError(f"Move {m} repeated")
            seen.add(m)

        board = ['.'] * 9
        for i, m in enumerate(moves):
            board[m] = 'X' if i % 2 == 0 else 'O'

        t = cls(''.join(board))
        # Check if the resulting state is valid (counts)
        # If X=4, O=3, it's valid. If X=5, O=4, it's invalid input, but the constructor handles counts.
        # However, the spec says "raising ValueError at the first illegal one" for the moves list itself.
        # The counts check is inside __init__.
        return t
