from __future__ import annotations
from typing import Callable, Optional

class ConnectFour:
    def __init__(self, columns: int = 7, rows: int = 6):
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1")
        if columns * rows == 0:
             raise ValueError("Columns and rows must be at least 1")

        self._columns = columns
        self._rows = rows
        self._board = [['.'] for _ in range(columns)]
        for r in range(rows):
            self._board[r] = ['.'] * columns

        self._player = 'X'

    @property
    def columns(self) -> int:
        return self._columns

    @property
    def rows(self) -> int:
        return self._rows

    @property
    def player(self) -> str:
        return self._player

    @property
    def moves(self) -> list:
        if self._is_over():
            return []
        moves = []
        for c in range(self._columns):
            if self._can_move(c):
                moves.append(c)
        return moves

    def _can_move(self, col: int) -> bool:
        if col < 0 or col >= self._columns:
            return False
        if self._board[0][col] != '.':
            return False
        return True

    def play(self, move: int) -> ConnectFour:
        if not self._can_move(move):
            raise ValueError(f"Cannot move to column {move}: full or out of bounds")
        if self._is_over():
             raise ValueError("Game is over")

        # Drop piece
        new_board = [row[:] for row in self._board]
        for r in range(self._rows):
            if new_board[r][move] == '.':
                new_board[r][move] = self._player
                break

        # Update internal state for new instance
        # Actually, let's just create a new instance and return it, ensuring immutability

        next_player = 'O' if self._player == 'X' else 'X'
        is_over = self._check_winner(new_board, next_player) or self._is_board_full(new_board)

        new_state = ConnectFour.__new__(ConnectFour)
        new_state._columns = self._columns
        new_state._rows = self._rows
        new_state._board = new_board
        new_state._player = next_player
        new_state._over = is_over

        return new_state

    def _check_winner(self, b: list[list[str]], looking_for: str) -> bool:
        cols = self._columns
        rows = self._rows

        # Horizontal
        for r in range(rows):
            for c in range(cols - 3):
                if b[r][c] == looking_for and b[r][c+1] == looking_for and b[r][c+2] == looking_for and b[r][c+3] == looking_for:
                    return True

        # Vertical
        for r in range(rows - 3):
            for c in range(cols):
                if b[r][c] == looking_for and b[r+1][c] == looking_for and b[r+2][c] == looking_for and b[r+3][c] == looking_for:
                    return True

        # Diagonal \
        for r in range(rows - 3):
            for c in range(cols - 3):
                if b[r][c] == looking_for and b[r+1][c+1] == looking_for and b[r+2][c+2] == looking_for and b[r+3][c+3] == looking_for:
                    return True

        # Diagonal /
        for r in range(3, rows):
            for c in range(cols - 3):
                if b[r][c] == looking_for and b[r-1][c+1] == looking_for and b[r-2][c+2] == looking_for and b[r-3][c+3] == looking_for:
                    return True

        return False

    def _is_over(self) -> bool:
        return self._over

    @property
    def winner(self) -> Optional[str]:
        # Check for winner of current player (looking_for) or previous player
        # Actually, simpler: just check if anyone has 4 in a row
        for p in ['X', 'O']:
            if self._check_winner(self._board, p):
                return p
        return None

    @property
    def is_over(self) -> bool:
        return self._over or self._is_board_full()

    def _is_board_full(self) -> bool:
        for c in range(self._columns):
            if self._board[0][c] == '.':
                return False
        return True

    def cell(self, column: int, row: int) -> str:
        if not (0 <= column < self._columns and 0 <= row < self._rows):
            raise IndexError("Column or row out of bounds")
        return self._board[row][column]

    def __str__(self) -> str:
        lines = []
        # Top row first
        for r in range(self._rows):
            row_str = "".join(self._board[r])
            lines.append(row_str)
        return "\n".join(lines)

    def __eq__(self, other):
        if not isinstance(other, ConnectFour):
            return False
        return self._board == other._board

    def __hash__(self):
        return hash(tuple(tuple(row) for row in self._board))

    def __repr__(self):
        return f"ConnectFour(columns={self._columns}, rows={self._rows})"

    @classmethod
    def from_moves(cls, moves: list[int], columns: int = 7, rows: int = 6) -> 'ConnectFour':
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1")

        # Validate moves
        seen_cols = set()
        for m in moves:
