    def agent(state: StateType) -> int:
        return best_move(state, depth, evaluate)
    return agent

def random_agent(seed: int) -> Callable[[StateType], int]:
    rng = random.Random(seed)
    def agent(state: StateType) -> int:
        if state.is_over():
            raise ValueError("Game is over")
        return rng.choice(state.moves())
    return agent

def play_game(state: StateType, agents: dict) -> tuple[StateType, list[int]]:
    history = []
    current_state = state

    while not current_state.is_over():
        player = current_state.player
        if player not in agents:
            raise ValueError(f"No agent defined for player {player}")

        move = agents[player](current_state)
        current_state = current_state.play(move)
        history.append(move)

    return current_state, history
