"""
Scanner module: tokenizes JSON text into a list of Token objects.
Handles positions, errors, numbers, strings, and surrogates.
"""

import re
from dataclasses import dataclass
from typing import List, Optional, Tuple, Union

# Positions are 1-based.
# Token kind
TokenKind = Literal[
    '{', '}', '[', ']', ':', ',', 'STRING', 'NUMBER', 'TRUE', 'FALSE', 'NULL', 'EOF'
]

# Token structure
@dataclass
class Token:
    kind: TokenKind
    value: Optional[Union[str, int, float, bool, None]] = None
    line: int = 1
    column: int = 1

    def __str__(self) -> str:
        return f"Token(kind={self.kind!r}, value={self.value!r}, line={self.line}, column={self.column})"


class JSONError(ValueError):
    """
    A custom error class for JSON parsing/serialization.
    Attributes: msg, line, column.
    str(e) formats as: "{msg} at line {line} column {column}"
    """
    def __init__(self, msg: str, line: int, column: int):
        super().__init__(msg)
        self.msg = msg
        self.line = line
        self.column = column

    def __str__(self) -> str:
        return f"{self.msg} at line {self.line} column {self.column}"


def _get_position(text: str, index: int) -> Tuple[int, int]:
    """Returns (line, column) for the character at `index` in `text`."""
    if index < 0 or index >= len(text):
        if index >= len(text):
            last_line, last_col = _get_position(text, len(text) - 1)
            return last_line, last_col + 1
        else:
            return _get_position(text, index)

    start_of_line = text.rfind('\n', 0, index)
    line_num = text[:start_of_line].count('\n') + 1
    col_num = index - start_of_line + 1
    return line_num, col_num


