    n = len(text)

    while pos < n:
        char = text[pos]
        line, col = _get_position(text, pos)

        # Whitespace handling
        if char in ' \t\n\r':
            pos += 1
            continue

        if char == '{' or char == '[':
            tokens.append(Token(kind=char, value=None, line=line, column=col))
            pos += 1
            continue

        if char == '}' or char == ']':
            tokens.append(Token(kind=char, value=None, line=line, column=col))
            pos += 1
            continue

        if char == ':':
            tokens.append(Token(kind=':', value=None, line=line, column=col))
            pos += 1
            continue

        if char == ',':
            tokens.append(Token(kind=',', value=None, line=line, column=col))
            pos += 1
            continue

        if char.isalpha():
            start = pos
            while pos < n and text[pos].isalpha():
                pos += 1
            word = text[start:pos]

            # Check for standard literals
            if allow_nan:
                if word == 'true':
                    tokens.append(Token(kind='TRUE', value=True, line=line, column=start+1))
                elif word == 'false':
                    tokens.append(Token(kind='FALSE', value=False, line=line, column=start+1))
                elif word == 'null':
                    tokens.append(Token(kind='NULL', value=None, line=line, column=start+1))
                elif word == 'NaN':
                    tokens.append(Token(kind='NUMBER', value=float('nan'), line=line, column=start+1))
                elif word == 'Infinity':
                    tokens.append(Token(kind='NUMBER', value=float('inf'), line=line, column=start+1))
                elif word == '-Infinity':
