    return tokens


def _parse_string(text: str, start: int, n: int) -> Tuple[str, int]:
    """
    Parses a string starting at `start` (which is the index of '"').
    Returns (decoded_string, end_index_exclusive).
    Raises JSONError on invalid string content.
    """
    pos = start + 1
    result_chars: List[int] = []
    end_pos = start

    while pos < n:
        char = text[pos]
        if char == '"':
            end_pos = pos + 1
            return ''.join(chr(cp) for cp in result_chars), end_pos
        elif char == '\\':
            pos += 1
            if pos >= n:
                raise JSONError("unterminated string", start + 1, pos + 1)

            next_char = text[pos]

            if next_char == '"':
                result_chars.append(0x22)
                pos += 1
            elif next_char == '\\':
                result_chars.append(0x5C)
                pos += 1
            elif next_char == '/':
                result_chars.append(0x2F)
                pos += 1
            elif next_char == 'b':
                result_chars.append(0x08)
                pos += 1
            elif next_char == 'f':
                result_chars.append(0x0C)
                pos += 1
            elif next_char == 'n':
