"""
Parser module: converts a list of Tokens into a Python value.
Handles nesting, keys, arrays, objects, and errors.
"""

from typing import Any, Dict, List, Optional, Tuple
from .scanner import Token, JSONError

def loads(text: str, *, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
    """
    Parses JSON text into a Python object.
    """
    if duplicate_keys not in ('last', 'first', 'error'):
        raise ValueError(f"invalid duplicate_keys value: {duplicate_keys!r}")
    if max_depth is not None and not isinstance(max_depth, int) or max_depth < 1:
        raise ValueError(f"invalid max_depth value: {max_depth}")

    tokens_iter = iter(tokenize(text, allow_nan=allow_nan))

    def peek():
        try:
            return next(tokens_iter)
        except StopIteration:
            return None

    def consume():
        tok = next(tokens_iter)
        return tok

    def expect(kind):
        tok = peek()
        if tok is None:
            raise JSONError("unexpected end of input", 1, 1)
        if tok.kind != kind:
            raise JSONError(f"expected {kind!r}, got {tok.kind!r}", tok.line, tok.column)
        return consume()

    def parse_value():
        tok = peek()
        if tok is None:
            raise JSONError("unexpected end of input", 1, 1)

        if tok.kind == 'TRUE':
            consume()
            return True
        elif tok.kind == 'FALSE':
            consume()
            return False
        elif tok.kind == 'NULL':
            consume()
            return None
        elif tok.kind == 'NUMBER':
            return tok.value
        elif tok.kind == 'STRING':
            return tok.value
        elif tok.kind == '{':
            return parse_object()
        elif tok.kind == '[':
            return parse_array()
        else:
            raise JSONError(f"unexpected token", tok.line, tok.column)

    def parse_array():
        consume() # Expect [
        result = []

        if peek() is None:
            consume() # Expect ]
            return result
        elif peek().kind == ']':
            consume()
            return result

        result.append(parse_value())

        while True:
            tok = peek()
            if tok.kind == ']':
                consume()
                return result
            elif tok.kind == ',':
                consume()
                result.append(parse_value())
            else:
                raise JSONError(f"expected ',' or ']', got {tok.kind!r}", tok.line, tok.column)

    def parse_object():
        consume() # Expect {
        result: Dict[Any, Any] = {}

        if peek() is None:
            consume() # Expect }
            return result
        elif peek().kind == '}':
            consume()
            return result

        key_token = parse_object_key()

        if peek() is None:
            raise JSONError("unexpected end of input", 1, 1)
        if peek().kind != ':':
            raise JSONError(f"expected ':', got {peek().kind!r}", peek().line, peek().column)
        consume()

        result[key_token] = parse_value()

        while True:
            tok = peek()
            if tok.kind == '}':
                consume()
                return result
            elif tok.kind == ',':
                consume()
                key_token = parse_object_key()
                if peek() is None:
                    raise JSONError("unexpected end of input", 1, 1)
                if peek().kind != ':':
                    raise JSONError(f"expected ':', got {peek().kind!r}", peek().line, peek().column)
                consume()
                result[key_token] = parse_value()
            else:
