# js/dump.py
"""
Serializer module: converts a Python object to a JSON string.
Handles indentation, sorting, escaping, and surrogates.
"""

import math
from typing import Any, Optional, List, Dict

from .scanner import JSONError

def _check_cycle(obj: Any, path: List[Any], visited: Dict[Any, Any]) -> bool:
    """
    Checks if the object is part of a cycle.
    Returns True if a cycle is detected.
    """
    if obj in visited:
        return True

    if isinstance(obj, dict):
        visited.add(obj)
        for key, value in obj.items():
            if _check_cycle(value, path + [key], visited):
                return True
        visited.discard(obj)
    elif isinstance(obj, (list, tuple)):
        visited.add(obj)
        for item in obj:
            if _check_cycle(item, path + [obj], visited):
                return True
        visited.discard(obj)
    return False


def _serialize_string(s: str, ensure_ascii: bool) -> str:
    """
    Serializes a string to JSON, handling escapes and surrogates.
    """
    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        code = ord(char)

        if code < 0x20:
            result.append('\\u00')
            result.append(f"{code:02x}")
            i += 1
            continue

        if code > 0x7F:
            if ensure_ascii:
                if code <= 0xFFFF:
                    result.append('\\u')
                    result.append(f"{code:04x}")
                else:
                    high = ((code - 0x00010000) >> 10) + 0xD800
                    low = (code - 0x00010000) & 0x03FF + 0xDC00
                    result.append('\\u')
                    result.append(f"{high:04x}")
                    result.append('\\u')
                    result.append(f"{low:04x}")
            else:
                result.append(char)
                i += 1
                continue

        if char == '"':
            result.append('\\\"')
        elif char == '\\':
            result.append('\\\\')
        elif char == '\b':
            result.append('\\b')
        elif char == '\f':
            result.append('\\f')
        elif char == '\n':
            result.append('\\n')
        elif char == '\r':
            result.append('\\r')
        elif char == '\t':
            result.append('\\t')
        else:
            result.append(char)

        i += 1

    return '"' + ''.join(result) + '"'

def _serialize_scalar(val: Any, ensure_ascii: bool) -> str:
    if val is None:
        return "null"
    elif val is True:
        return "true"
    elif val is False:
        return "false"
    elif isinstance(val, int):
        return str(val)
    elif isinstance(val, float):
        if math.isnan(val) or math.isinf(val):
            raise ValueError("NaN and infinities are not allowed")
        return repr(val)
    elif isinstance(val, str):
        return _serialize_string(val, ensure_ascii)
    else:
        raise TypeError(f"Object of type {type(val).__name__} is not JSON serializable")

def _serialize_array(arr: List, depth: int, ensure_ascii: bool) -> str:
    indent_open = " " * (depth * 4)
    indent_items = " " * ((depth + 1) * 4)

    if not arr:
        return indent_open + "[]"

    lines = [indent_open + "["]

    for i, item in enumerate(arr):
        if i < len(arr) - 1:
            lines.append(indent_items + _serialize_value(item, depth + 1, ensure_ascii) + ",")
        else:
            lines.append(indent_items + _serialize_value(item, depth + 1, ensure_ascii))

    lines.append(indent_open + "]")
    return "\n".join(lines)

def _serialize_object(obj: Dict, depth: int, ensure_ascii: bool) -> str:
    indent_open = " " * (depth * 4)
    indent_items = " " * ((depth + 1) * 4)

    if not obj:
        return indent_open + "{}"

    lines = [indent_open + "{"]

    for i, (k, v) in enumerate(obj.items()):
        if i < len(obj) - 1:
            lines.append(indent_items + f'"{_serialize_scalar(k, ensure_ascii)}": {_serialize_value(v, depth + 1, ensure_ascii)},')
        else:
            lines.append(indent_items + f'"{_serialize_scalar(k, ensure_ascii)}": {_serialize_value(v, depth + 1, ensure_ascii)}')

    lines.append(indent_open + "}")
    return "\n".join(lines)

def _serialize_value(val: Any, depth: int, ensure_ascii: bool) -> str:
    if isinstance(val, dict):
        return _serialize_object(val, depth, ensure_ascii)
    elif isinstance(val, (list, tuple)):
        return _serialize_array(list(val), depth, ensure_ascii)
    else:
        return _serialize_scalar(val, ensure_ascii)

def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = False, allow_nan: bool = False) -> str:
    if not isinstance(obj, (dict, list, tuple)):
        if obj is None:
            return "null"
        elif obj is True:
            return "true"
        elif obj is False:
            return "false"
        elif isinstance(obj, int):
            return str(obj)
        elif isinstance(obj, float):
            if math.isnan(obj) or math.isinf(obj):
                if allow_nan:
                    if math.isnan(obj):
                        return "NaN"
                    elif math.isinf(obj):
                        return "Infinity" if obj > 0 else "-Infinity"
                else:
                    raise ValueError("NaN and infinities are not allowed")
            return repr(obj)
        elif isinstance(obj, str):
            return _serialize_string(obj, ensure_ascii)
        else:
            raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")

    if _check_cycle(obj, [], set()):
        raise ValueError("Object contains a cycle")

    if indent is not None and not isinstance(indent, int) or indent < 0:
        raise ValueError("indent must be a non-negative integer")

    if sort_keys and isinstance(obj, dict):
        return _serialize_object(obj, 0, ensure_ascii)
    else:
        if isinstance(obj, dict):
            return _serialize_object(obj, 0, ensure_ascii)
        elif isinstance(obj, list):
            return _serialize_array(obj, 0, ensure_ascii)
        elif isinstance(obj, tuple):
            return _serialize_array(list(obj), 0, ensure_ascii)
        else:
            raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")
