from dataclasses import dataclass
from typing import List, Tuple


class Version:
    """
    Represents a semantic version MAJOR.MINOR.PATCH.
    Parsing rules: exactly three parts, non-negative integers, no leading zeros (except "0").
    """

    def __init__(self, text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: {text}")

        self._major = int(parts[0])
        self._minor = int(parts[1])
        self._patch = int(parts[2])

        # Validate parts: must be digits only, no leading zeros (unless the part is just "0")
        for p in parts:
            if not p.isdigit():
                raise ValueError(f"Version part must be digits only: {text}")
            if len(p) > 1 and p[0] == '0':
                raise ValueError(f"Leading zeros not allowed: {text}")

    @property
    def major(self) -> int:
        return self._major

    @property
    def minor(self) -> int:
        return self._minor

    @property
    def patch(self) -> int:
        return self._patch

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return (self.major, self.minor, self.patch) > (other.major, other.minor, other.patch)

    def __ge__(self, other):
        return self == other or self > other

    def __hash__(self):
