    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self):
        return f"Version({self})"


@dataclass
class Range:
    """
    Represents a version constraint.
    Supports: *, ==, !=, >, >=, <, <=, ^, ~.
    Stored as a list of (operator, version) tuples.
    """

    constraints: List[Tuple[str, Version]]

    def __str__(self):
        # Reconstruct the spec string. 
        # Note: The spec string reconstruction needs to handle the original format or a canonical one.
        # Based on the prompt: "str(r) is the spec with all whitespace removed."
        # We need to reconstruct the operators.
        parts = []
        for op, ver in self.constraints:
            if op == '*':
                parts.append('*')
            elif op == '==':
                parts.append(f"=={ver}")
            elif op == '!=':
                parts.append(f"!={ver}")
            elif op == '>':
                parts.append(f">{ver}")
            elif op == '>=':
                parts.append(f">={ver}")
            elif op == '<':
                parts.append(f"<{ver}")
            elif op == '<=':
                parts.append(f"<={ver}")
            elif op == '^':
                parts.append(f"^{ver}")
            elif op == '~':
                parts.append(f"~{ver}")
            else:
                raise ValueError(f"Unknown operator in range: {op}")
        return ''.join(parts)

    def __hash__(self):
        return hash(tuple(self.constraints))

    def __eq__(self, other):
        if not isinstance(other, Range):
            return NotImplemented
        return self.constraints == other.constraints


def parse_version(text: str) -> Version:
    return Version(text)


def parse_range(spec: str) -> Range:
    """
    Parses a comma-separated list of version constraints.
    """
    # Normalize whitespace
    if not spec or not spec.strip():
        raise ValueError("Empty spec")

    parts = spec.split(',')
    constraints = []

    for part in parts:
        part = part.strip()
        if not part:
            # Handle trailing comma or multiple commas
            continue

        # Parse operator and version
        if part.startswith('=='):
            op, ver_str = '==', part[2:]
        elif part.startswith('!='):
            op, ver_str = '!=', part[2:]
        elif part.startswith('>'):
            op, ver_str = '>', part[1:]
        elif part.startswith('>='):
            op, ver_str = '>=', part[2:]
        elif part.startswith('<'):
            op, ver_str = '<', part[1:]
        elif part.startswith('<='):
            op, ver_str = '<=', part[2:]
        elif part.startswith('^'):
            op, ver_str = '^', part[1:]
        elif part.startswith('~'):
            op, ver_str = '~', part[1:]
        elif part == '*':
            op, ver_str = '*', ''
            ver = None
        else:
            # Assume exact version match without operator
            op, ver_str = '==', part
            # Try to parse as version, if fails, maybe it's a bad spec? 
            # Prompt says "1.2.3 or ==1.2.3". So if it starts with digit, it's a version.
            if ver_str[0].isdigit():
                ver = parse_version(ver_str)
            else:
                raise ValueError(f"Invalid version or spec: {part}")

        if ver is None:
            raise ValueError(f"Version missing after operator: {part}")

        constraints.append((op, ver))

    return Range(constraints)


def version_in_range(version: Version, range_spec: Range) -> bool:
    """Check if a version satisfies all constraints in the range."""
    for op, ver in range_spec.constraints:
        if op == '*':
            continue
        elif op == '==':
            if version != ver:
                return False
        elif op == '!=':
            if version == ver:
                return False
        elif op == '>':
            if version <= ver:
                return False
        elif op == '>=':
            if version < ver:
                return False
        elif op == '<':
            if version >= ver:
                return False
        elif op == '<=':
            if version > ver:
                return False
        elif op == '^':
            # Caret operator: ^1.2.3 -> >=1.2.3, <2.0.0 (if major > 0)
            # ^0.2.3 -> >=0.2.3, <0.3.0
            # ^0.0.3 -> >=0.0.3, <0.0.4
            # ^0.0.0 -> >=0.0.0, <0.0.1
            if version < ver:
                return False

            # Determine upper bound
            # Find the first non-zero part
            if ver.major > 0:
                upper = Version(ver.major + 1, 0, 0)
            elif ver.minor > 0:
                upper = Version(ver.major, ver.minor + 1, 0)
            else:
                upper = Version(ver.major, ver.minor, ver.patch + 1)

            if version >= upper:
                return False
        elif op == '~':
            # Tilde operator: ~1.2.3 -> >=1.2.3, <1.3.0
            if version < ver:
                return False
            upper = Version(ver.major, ver.minor + 1, 0)
            if version >= upper:
                return False
    return True


class RangeParserError(Exception):
    pass


def parse_range_str(spec: str) -> Range:
    """Wrapper to handle ValueError from parse_range."""
    try:
        return parse_range(spec)
    except ValueError as e:
        raise RangeParserError(str(e)) from e


