from typing import Dict, List, Optional, Union
from .versions import Version, Range


class PackageIndexError(Exception):
    pass


class PackageIndex:
    def __init__(self):
        self._data: Dict[str, Dict[Version, Dict[str, Range]]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """
        Adds a release.
        Raises ValueError if name/version already exists, or if version/spec is invalid.
        """
        version = Version(version_str)
        if name in self._data:
            if version in self._data[name]:
                raise ValueError(f"Duplicate release: {name} {version}")
            else:
                raise ValueError(f"Duplicate release: {name} {version}")

        deps = {}
        if requires:
            for dep_name, dep_spec_str in requires.items():
                try:
                    deps[dep_name] = parse_range(dep_spec_str)
                except RangeParserError as e:
                    raise ValueError(f"Invalid range spec for {name} {version} {dep_name}: {e}")

        self._data[name][version] = deps

    def versions(self, name: str) -> List[Version]:
        if name not in self._data:
            return []
        # Return newest first
        return sorted(self._data[name].keys(), reverse=True)

    def requirements(self, name: str, version_str: str) -> Dict[str, Range]:
        version = Version(version_str)
        if name not in self._data or version not in self._data[name]:
            raise KeyError(f"Unknown release: {name} {version}")
        return self._data[name][version]

    @staticmethod
    def from_dict(data: Dict[Union[str, Dict], Dict]) -> 'PackageIndex':
        """
        Builds an index from a dict structure:
        {name: {version: {dep: spec}, ...}, ...}
        """
        index = PackageIndex()
        for name, releases in data.items():
            # Handle if name is already a dict (nested structure from dict() call sometimes)
            # But the prompt says data is {name: {version: ...}}
            if isinstance(name, dict):
                # This case shouldn't happen based on description, but handle gracefully if passed flat list of dicts
                # Actually, standard dict iteration key-value. If key is dict, that's weird.
                # Let's assume strict input format.
                pass

            if not isinstance(releases, dict):
                raise ValueError(f"Expected dict of versions for package {name}, got {type(releases)}")

            for version_str, deps in releases.items():
                try:
                    version = Version(version_str)
                except ValueError as e:
                    raise ValueError(f"Invalid version string for {name}: {e}")

                if not isinstance(deps, dict):
                    raise ValueError(f"Expected dict of dependencies for {name} {version}, got {type(deps)}")

                for dep_name, dep_spec_str in deps.items():
                    try:
                        parse_range(dep_spec_str)
                    except RangeParserError as e:
                        raise ValueError(f"Invalid range spec for {name} {version} {dep_name}: {e}")

                index.add(name, version_str, deps)

        return index


