            # They are at the end.
            ctx.order = ctx.order[:-len(deps)] # Wait, this assumes all deps were added.
            # We added `len(deps)` items. Yes.
            # But wait, if some deps were already in order, we didn't add them.
            # So we need to count how many we added.
            added_count = 0
            for dep_name in deps:
                if dep_name not in ctx.order:
                    ctx.order.append(dep_name)
                    added_count += 1
            # Now we need to remove `added_count` items from the end.
            ctx.order = ctx.order[:-added_count]

        return False

    ctx.order = sorted(requirements.keys())

    if dfs():
        return {name: ctx.selected[name] for name in ctx.selected}
    else:
        raise ResolutionError(next_pkg, ctx.build_explanation(next_pkg))


