        for item_id, item_data in items_data.items():
            name = item_data.get("name")
            description = item_data.get("description")
            portable = item_data.get("portable", True)

            item = Item(
                id=item_id,
                name=name,
                description=description,
                portable=portable
            )
            items[item_id] = item

