# adventure/parser.py
from dataclasses import dataclass
from typing import Optional, NamedTuple
import re

@dataclass
class Command:
    verb: str
    arg: Optional[str]

class ParseError(ValueError):
    """Custom exception for parsing errors."""
    def __str__(self):
        return self._message

class Parser:
    _articles = {'a', 'an', 'the'}

    def __init__(self):
        self._message = None

    def set_message(self, msg: str):
        self._message = msg

    def parse(self, line: str) -> Command:
        if not line or line.isspace():
            self.set_message("Say something.")
            raise ParseError()

        parts = line.lower().split()
        if not parts:
            self.set_message("Say something.")
            raise ParseError()

        word = parts[0]
        if word not in self._articles:
            if not parts:
                self.set_message("Say something.")
                raise ParseError()
            if word in self._articles:
                # Skip articles until first non-article word
                i = 1
                while i < len(parts) and parts[i] in self._articles:
                    i += 1
                if i == len(parts):
                    self.set_message("Say something.")
                    raise ParseError()
                # Re-evaluate word after skipping articles if needed, 
                # but spec says "unknown first word", usually implies the first word in the command line structure.
                # However, looking at "I don't know the word...", it implies the first non-article word if articles are leading.
                # But strict interpretation of "first word" usually means parts[0]. 
                # Let's follow the logic: if parts[0] is 'the', we skip. If the next is 'unknown', that's the error.
                # Actually, standard behavior for these parsers: if the first word is 'the', 'a', or 'an', it's an article and should be skipped.
                # If the first word is NOT an article, it's the command verb.

                if word not in self._articles:
                    self.set_message(f"I don't know the word \"{word}\".")
                    raise ParseError()
                else:
                    # Skip leading articles
                    i = 1
                    while i < len(parts) and parts[i] in self._articles:
                        i += 1
                    if i >= len(parts):
                        self.set_message("Say something.")
                        raise ParseError()
                    word = parts[i]
                    if word not in self._articles:
                        self.set_message(f"I don't know the word \"{word}\".")
                        raise ParseError()

        if word == 'go':
            if len(parts) < 2:
                self.set_message("Go where?")
                raise ParseError()
            arg_str = ' '.join(parts[1:])
            if self._is_direction(arg_str):
                self.set_message(f"\"{arg_str}\" is not a direction.")
                raise ParseError()

            direction = self._normalize_direction(arg_str)
            if direction:
                return Command('go', direction)
            else:
                self.set_message("Go where?")
                raise ParseError()

        elif word == 'take' or word == 'get':
            if len(parts) < 2:
                self.set_message("Take what?")
                raise ParseError()
            arg_str = ' '.join(parts[1:])
            if not self._strip_articles(arg_str):
                self.set_message("Take what?")
                raise ParseError()
            return Command('take', arg_str)

        elif word == 'drop':
            if len(parts) < 2:
                self.set_message("Drop what?")
                raise ParseError()
            arg_str = ' '.join(parts[1:])
            if not self._strip_articles(arg_str):
                self.set_message("Drop what?")
                raise ParseError()
            return Command('drop', arg_str)

        elif word in ('look', 'l'):
            if len(parts) == 1:
                return Command('look', None)
            elif len(parts) >= 2 and parts[1].lower() in ('at', 'examine'):
                if len(parts) < 3:
                    self.set_message("Examine what?")
                    raise ParseError()
                arg_str = ' '.join(parts[2:])
                if not self._strip_articles(arg_str):
                    self.set_message("Examine what?")
                    raise ParseError()
                return Command('look', arg_str)
            else:
                arg_str = ' '.join(parts[1:])
                if self._strip_articles(arg_str):
                    return Command('look', arg_str)
                else:
                    self.set_message("Look what?")
                    raise ParseError()

        elif word in ('inventory', 'inv', 'i'):
            if len(parts) > 1:
                rest = ' '.join(parts[1:])
                if not rest.isspace():
                    self.set_message("I don't understand that.")
                    raise ParseError()
            return Command('inventory', None)
        else:
            self.set_message(f"I don't know the word \"{word}\".")
            raise ParseError()

    def _is_direction(self, s: str) -> bool:
        return s in DIRECTIONS

    def _normalize_direction(self, s: str) -> Optional[str]:
        if s in DIRECTIONS:
            return s
        for d in DIRECTIONS:
            if s.startswith(d):
                return d
        return None

    def _strip_articles(self, s: str) -> str:
        words = s.lower().split()
        if not words:
            return ""
        filtered = [w for w in words if w not in self._articles]
        return ' '.join(filtered)

    def parse(self, line: str) -> Command:
        self.set_message(None)
        return self._parse(line)

def parse(line: str) -> Command:
    parser = Parser()
    try:
        return parser.parse(line)
    except ParseError:
        raise
