# adventure/game.py
import json
from typing import Dict, List, Optional
from adventure.world import World, Room, Item, DIRECTIONS

class SaveError(ValueError):
    """Custom exception for save/load errors."""
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room_id = world.start
        self.inventory: List[str] = []
        self.moves = 0

    @property
    def room(self) -> Room:
        return self.world.rooms[self.room_id]

    @property
    def items_in_room(self) -> List[str]:
        return list(self.room.items)

    def do(self, line: str) -> str:
        try:
            cmd = self._parser.parse(line)
        except Exception:
            # Should not happen as Parser handles errors, but safe guard
            return "Say something."

        if cmd.verb == 'look':
            return self._do_look(cmd.arg)
        elif cmd.verb == 'go':
            return self._do_go(cmd.arg)
        elif cmd.verb == 'take':
            return self._do_take(cmd.arg)
        elif cmd.verb == 'drop':
            return self._do_drop(cmd.arg)
        elif cmd.verb in ('inventory', 'inv', 'i'):
            return self._do_inventory()
        else:
            # Should be covered by parser errors, but fallback
            return "I don't understand that."

    def _do_look(self, arg: Optional[str]) -> str:
        if arg:
            return self._do_look_item(arg)
        else:
            # Standard look
            lines = [
                self.room.name,
                self.room.description,
                f"Exits: {', '.join(self.room.exits[d] for d in DIRECTIONS if d in self.room.exits)}." if self.room.exits else "Exits: none.",
            ]
            if self.items_in_room:
                lines.append(f"You see: {', '.join(self.world.items[i].name for i in self.items_in_room)}.")
            return '\n'.join(lines)

    def _do_look_item(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if item_id:
            item = self.world.items[item_id]
            return item.description
        else:
            return f"You see no {arg} here."

    def _do_go(self, arg: str) -> str:
        if not arg:
            return "Go where?"
        if not self._is_direction(arg):
            return f"\"{arg}\" is not a direction."
        if arg not in self.room.exits:
            return "You can't go that way."
        self.room_id = self.room.exits[arg]
        self.moves += 1
        return self._do_look(None)

    def _do_take(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if not item_id:
            return self._do_look_item(arg)

        item = self.world.items[item_id]
        if item_id in self.items_in_room:
            if not item.portable:
                return f"You can't take the {item.name}."
            self.items_in_room.remove(item_id)
            self.inventory.append(item_id)
            return f"Taken: {item.name}."
        elif item_id in self.inventory:
            return f"You already have the {item.name}."
        else:
            return f"You see no {arg} here."

    def _do_drop(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if not item_id:
            return self._do_look_item(arg)

        if item_id in self.inventory:
            self.inventory.remove(item_id)
            self.items_in_room.append(item_id)
            return f"Dropped: {self.world.items[item_id].name}."
        else:
            return "You aren't carrying that."

    def _do_inventory(self) -> str:
        names = [self.world.items[i].name for i in self.inventory]
        if names:
            return f"You are carrying: {', '.join(names)}."
        else:
            return "You are carrying nothing."

    def _match_item(self, arg: str) -> Optional[str]:
        arg_lower = arg.lower()
        for item_id, item in self.world.items.items():
            if item_id.lower() == arg_lower or item.name.lower() == arg_lower:
                return item_id
        return None

    def _is_direction(self, s: str) -> bool:
        return s in DIRECTIONS

    def save(self) -> str:
        room_items = {rid: list(self.items_in_room) for rid, r in self.world.rooms.items()}
        data = {
            "version": 1,
            "room": self.room_id,
            "inventory": self.inventory,
            "items": room_items,
            "moves": self.moves
        }
        return json.dumps(data)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("Save file must be an object")

        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            raise SaveError(f"Missing keys in save file. Expected: {required_keys}")

        if data["version"] != 1:
            raise SaveError("Version mismatch")

        if data["room"] not in world.rooms:
            raise SaveError(f"Room {data['room']} not in world")

        for room_id, item_list in data["items"].items():
            if room_id not in world.rooms:
                raise SaveError(f"Room {room_id} in save file not in world")
            for item_id in item_list:
                if item_id not in world.items:
                    raise SaveError(f"Item {item_id} in save file not in world")

        # Check for duplicates across inventory and rooms
        all_ids = set(data["inventory"])
        for room_id, room_items in data["items"].items():
            all_ids.update(room_items)

        if len(all_ids) != len(data["inventory"]) + sum(len(v) for v in data["items"].values()):
            raise SaveError("Item appears more than once")

        if not isinstance(data["moves"], int) or data["moves"] < 0:
            raise SaveError("Invalid moves count")

        return cls(world)

    def _parser(self):
        # Lazy import to avoid circular dependencies if any, though handled in module structure
        from adventure.parser import parse
        return parse
