from dataclasses import dataclass, field
from typing import Dict, FrozenSet, Optional, Tuple, Set
import enum

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True
    treasure: int = 0

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str] = field(default_factory=dict)
    items: FrozenSet[str] = field(default_factory=frozenset)
    locks: Dict[str, str] = field(default_factory=dict)

class WorldError(ValueError):
    """Custom exception for world validation errors."""
    pass

class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        if not start or start not in rooms:
            raise WorldError("start room is missing or invalid")

        for room_id, room in rooms.items():
            if not room.name:
                raise WorldError(f"Room {room_id} lacks a name")
            if not room.description:
                raise WorldError(f"Room {room_id} lacks a description")

            for direction, target_id in room.exits.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Invalid direction '{direction}' in room {room_id}")
                if target_id not in rooms:
                    raise WorldError(f"Exit from {room_id} in direction {direction} leads to unknown room {target_id}")

        # Check for duplicate items
        all_item_ids: Set[str] = set()
        for room_id, room in rooms.items():
            for item_id in room.items:
                if item_id in all_item_ids:
                    raise WorldError(f"Item {item_id} is listed in multiple rooms")
                all_item_ids.add(item_id)

        super().__init__()
        self.start = start
        self.rooms = rooms
        self.items = items

    @classmethod
    def from_dict(cls, data: dict) -> "World":
        start = data.get("start")
        rooms_data = data.get("rooms", {})
        items_data = data.get("items", {})

        if not start:
            raise WorldError("start room is missing")
        if start not in rooms_data:
            raise WorldError(f"start room '{start}' is not a known room")

        rooms: Dict[str, Room] = {}
        for room_id, room_data in rooms_data.items():
            name = room_data.get("name")
            description = room_data.get("description")

            # Handle exits: can be a string or a dict
            exits = {}
            if "exits" in room_data:
                exits_list = room_data["exits"]
                if isinstance(exits_list, dict):
                    for direction, exit_info in exits_list.items():
                        if direction not in DIRECTIONS:
                            raise WorldError(f"Invalid direction '{direction}' in room {room_id}")
                        target_id = exit_info.get("to")
                        key_id = exit_info.get("key")

                        if not target_id:
                            raise WorldError(f"Exit {direction} from {room_id} lacks 'to'")
                        if target_id not in rooms:
                            raise WorldError(f"Exit from {room_id} in direction {direction} leads to unknown room {target_id}")

                        if key_id:
                            if not isinstance(key_id, str):
                                raise WorldError(f"Key for {direction} in {room_id} is not an item")
                            if key_id not in items:
                                raise WorldError(f"Key '{key_id}' for {direction} in {room_id} is not an item")

                            if "locks" not in room_data:
                                room_data["locks"] = {}
                            room_data["locks"][direction] = key_id

                        exits[direction] = target_id
                else:
                    # Backward compatibility: string exits
                    for direction, target_id in exits_list.items():
                        if direction not in DIRECTIONS:
                            raise WorldError(f"Invalid direction '{direction}' in room {room_id}")
                        if target_id not in rooms:
                            raise WorldError(f"Exit from {room_id} in direction {direction} leads to unknown room {target_id}")
                        exits[direction] = target_id
            else:
                # No exits defined
                pass

            item_ids = room_data.get("items", [])
            room = Room(
                id=room_id,
                name=name,
                description=description,
                exits=exits,
                items=frozenset(item_ids),
                locks=room_data.get("locks", {})
            )
            rooms[room_id] = room

        items: Dict[str, Item] = {}
        for item_id, item_data in items_data.items():
            name = item_data.get("name")
            description = item_data.get("description")
            portable = item_data.get("portable", True)
            treasure = item_data.get("treasure", 0)

            if not isinstance(treasure, int) or treasure < 0:
                raise WorldError(f"Treasure value for {item_id} must be a non-negative integer")

            item = Item(
                id=item_id,
                name=name,
                description=description,
                portable=portable,
                treasure=treasure
            )
            items[item_id] = item

        return cls(start, rooms, items)
