            elif len(parts) >= 2 and parts[1].lower() in ('at', 'examine'):
                if len(parts) < 3:
                    self.set_message("Examine what?")
                    raise ParseError()
                arg_str = ' '.join(parts[2:])
                if not self._strip_articles(arg_str):
                    self.set_message("Examine what?")
                    raise ParseError()
                return Command('look', arg_str)
            else:
                arg_str = ' '.join(parts[1:])
                if self._strip_articles(arg_str):
                    return Command('look', arg_str)
                else:
                    self.set_message("Look what?")
                    raise ParseError()

        elif word == 'use':
            if len(parts) < 2:
                self.set_message("Use what?")
                raise ParseError()
            arg_str = ' '.join(parts[1:])
            if not self._strip_articles(arg_str):
                self.set_message("Use what?")
                raise ParseError()
            return Command('use', arg_str)

        elif word == 'score':
            if len(parts) > 1:
                rest = ' '.join(parts[1:])
                if not rest.isspace():
