            return Command('score', None)
        else:
            self.set_message(f"I don't know the word \"{word}\".")
            raise ParseError()

    def _is_direction(self, s: str) -> bool:
        return s in DIRECTIONS

    def _normalize_direction(self, s: str) -> Optional[str]:
        if s in DIRECTIONS:
            return s
        for d in DIRECTIONS:
            if s.startswith(d):
                return d
        return None

    def _strip_articles(self, s: str) -> str:
        words = s.lower().split()
        if not words:
            return ""
        filtered = [w for w in words if w not in self._articles]
        return ' '.join(filtered)

    def parse(self, line: str) -> Command:
        self.set_message(None)
        return self._parse(line)

def parse(line: str) -> Command:
    parser = Parser()
    try:
        return parser.parse(line)
    except ParseError:
        raise
