# adventure/game.py
import json
from typing import Dict, List, Optional, Set
from adventure.world import World, Room, Item, DIRECTIONS

class SaveError(ValueError):
    """Custom exception for save/load errors."""
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room_id = world.start
        self.inventory: List[str] = []
        self.moves = 0
        self.unlocked: List[tuple] = []  # [(room_id, direction), ...]
        self.visited: Set[str] = {world.start}
        self.scored_items: Set[str] = set()
        self.score = 0

    @property
    def room(self) -> Room:
        return self.world.rooms[self.room_id]

    @property
    def items_in_room(self) -> List[str]:
        return list(self.room.items)

    def do(self, line: str) -> str:
        try:
            cmd = self._parser.parse(line)
        except Exception:
            return "Say something."

        if cmd.verb == 'look':
            return self._do_look(cmd.arg)
        elif cmd.verb == 'go':
            return self._do_go(cmd.arg)
        elif cmd.verb == 'take':
            return self._do_take(cmd.arg)
        elif cmd.verb == 'drop':
            return self._do_drop(cmd.arg)
        elif cmd.verb == 'use':
            return self._do_use(cmd.arg)
        elif cmd.verb in ('inventory', 'inv', 'i'):
            return self._do_inventory()
        elif cmd.verb == 'score':
            return self._do_score()
        else:
            return "I don't understand that."

    def _do_look(self, arg: Optional[str]) -> str:
        if arg:
            return self._do_look_item(arg)
        else:
            lines = [
                self.room.name,
                self.room.description,
                self._format_exits(),
            ]
            if self.items_in_room:
                lines.append(f"You see: {', '.join(self.world.items[i].name for i in self.items_in_room)}.")
            return '\n'.join(lines)

    def _format_exits(self) -> str:
        exit_strs = []
        for d in DIRECTIONS:
            if d in self.room.exits:
                target = self.room.exits[d]
                if d in self.room.locks:
                    exit_strs.append(f"{d} (locked)")
                else:
                    exit_strs.append(target)

        if exit_strs:
            return f"Exits: {', '.join(exit_strs)}."
        else:
            return "Exits: none."

    def _do_look_item(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if item_id:
            item = self.world.items[item_id]
            return item.description
        else:
            return f"You see no {arg} here."

    def _do_go(self, arg: str) -> str:
        if not arg:
            return "Go where?"
        if not self._is_direction(arg):
            return f"\"{arg}\" is not a direction."
        if arg not in self.room.exits:
            return "You can't go that way."

        direction = arg
        target = self.room.exits[direction]

        # Check if locked
        if direction in self.room.locks:
            return f"The way {direction} is locked."

        # Move
        self.room_id = target
        self.moves += 1

        # Score entry
        if self.room_id not in self.visited:
            self.visited.add(self.room_id)
            self.score += 10

        return self._do_look(None)

    def _do_take(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if not item_id:
            return self._do_look_item(arg)

        item = self.world.items[item_id]
        if item_id in self.items_in_room:
            if not item.portable:
                return f"You can't take the {item.name}."
            self.items_in_room.remove(item_id)
            self.inventory.append(item_id)

            # Score treasure
            if item.treasure > 0 and item_id not in self.scored_items:
                self.scored_items.add(item_id)
                self.score += item.treasure

            return f"Taken: {item.name}."
        elif item_id in self.inventory:
            return f"You already have the {item.name}."
        else:
            return f"You see no {arg} here."

    def _do_drop(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if not item_id:
            return self._do_look_item(arg)

        if item_id in self.inventory:
            self.inventory.remove(item_id)
            self.items_in_room.append(item_id)
            return f"Dropped: {self.world.items[item_id].name}."
        else:
            return "You aren't carrying that."

    def _do_use(self, arg: str) -> str:
        item_id = self._match_item(arg)
        if not item_id:
            return self._do_look_item(arg)

        if item_id not in self.inventory:
            return f"You aren't carrying that."

        item = self.world.items[item_id]
        # Find which exits in current room are locked by this item
        keys_to_unlock = []
        for d in DIRECTIONS:
            if d in self.room.locks and self.room.locks[d] == item_id:
                keys_to_unlock.append(d)

        if keys_to_unlock:
            self.unlocked.extend([(self.room_id, d) for d in keys_to_unlock])
            sorted_keys = sorted(keys_to_unlock)
            return f"Unlocked: {', '.join(sorted_keys)}."
        else:
            return f"Nothing here to use the {item.name} on."

    def _do_inventory(self) -> str:
        names = [self.world.items[i].name for i in self.inventory]
        if names:
            return f"You are carrying: {', '.join(names)}."
        else:
            return "You are carrying nothing."

    def _do_score(self) -> str:
        return f"Your score is {self.score}."

    def _match_item(self, arg: str) -> Optional[str]:
        arg_lower = arg.lower()
        for item_id, item in self.world.items.items():
            if item_id.lower() == arg_lower or item.name.lower() == arg_lower:
                return item_id
        return None

    def _is_direction(self, s: str) -> bool:
        return s in DIRECTIONS

    def save(self) -> str:
        room_items = {rid: list(self.items_in_room) for rid, r in self.world.rooms.items()}
        data = {
            "version": 2,
            "room": self.room_id,
            "inventory": self.inventory,
            "items": room_items,
            "moves": self.moves,
            "unlocked": sorted(self.unlocked),
            "visited": sorted(self.visited),
            "scored": sorted(self.scored_items),
            "score": self.score
        }
        return json.dumps(data)

    @classmethod
    def load(cls, world: World, text: str) -> "Game":
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON")

        if not isinstance(data, dict):
            raise SaveError("Save file must be an object")

        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            raise SaveError(f"Missing keys in save file. Expected: {required_keys}")

        version = data["version"]

        # Validate base keys and items exist
        if data["room"] not in world.rooms:
            raise SaveError(f"Room {data['room']} not in world")

        for room_id, item_list in data["items"].items():
            if room_id not in world.rooms:
                raise SaveError(f"Room {room_id} in save file not in world")
            for item_id in item_list:
                if item_id not in world.items:
                    raise SaveError(f"Item {item_id} in save file not in world")

        # Check for duplicates across inventory and rooms
        all_ids = set(data["inventory"])
        for room_id, room_items in data["items"].items():
            all_ids.update(room_items)

        if len(all_ids) != len(data["inventory"]) + sum(len(v) for v in data["items"].values()):
            raise SaveError("Item appears more than once")

        if not isinstance(data["moves"], int) or data["moves"] < 0:
            raise SaveError("Invalid moves count")

        if version == 1:
            # Backward compatibility: version 1 save
            return cls(world, version=1, extra_data=data)
        elif version == 2:
            return cls(world, version=2, extra_data=data)
        else:
            raise SaveError(f"Unsupported version: {version}")

    def __init__(self, world: World, version: int = 1, extra_data: Optional[dict] = None):
        # Initialize base state
        self.world = world
        self.room_id = world.start
        self.inventory: List[str] = []
        self.moves = 0
        self.unlocked: List[tuple] = []
        self.visited: Set[str] = {world.start}
        self.scored_items: Set[str] = set()
        self.score = 0

        # Apply version specific data
        if version == 2 and extra_data:
            self.unlocked = [tuple(x) for x in extra_data.get("unlocked", [])]
            self.visited = set(extra_data.get("visited", []))
            self.scored_items = set(extra_data.get("scored", []))
            self.score = extra_data.get("score", 0)

            # Verify new fields against world
            for room_id, direction in self.unlocked:
                if room_id not in world.rooms:
                    raise SaveError(f"Unlocked room {room_id} not in world")
                if direction not in world.rooms[room_id].exits:
                    raise SaveError(f"Unlocked direction {direction} not in room {room_id}")
                if direction not in world.rooms[room_id].locks:
                    raise SaveError(f"Direction {direction} in room {room_id} is not locked in world")

            for room_id in self.visited:
                if room_id not in world.rooms:
                    raise SaveError(f"Visited room {room_id} not in world")

            for item_id in self.scored_items:
                if item_id not in world.items:
                    raise SaveError(f"Scored item {item_id} not in world")

            if not isinstance(self.score, int) or self.score < 0:
                raise SaveError("Invalid score count")
