# logagg/parsers.py
import json
import re
from datetime import datetime, timezone
from dataclasses import dataclass, field
from typing import Any, Iterable, List, Optional, Tuple


@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float] = None


class ParseError(ValueError):
    pass


def normalize(
    time: datetime,
    client: str,
    method: str,
    path: str,
    status: int,
    size: int,
    latency_ms: Optional[float],
) -> Record:
    # Validate time (already assumed valid input to this function, but ensure it's UTC-aware)
    if time.tzinfo is None:
        raise ParseError("time must be timezone-aware")
    if time.tzinfo.utcoffset(time) != timezone.utc.utcoffset(None):
        # Convert to UTC explicitly
        time = time.astimezone(timezone.utc)

    # Validate client
    if not isinstance(client, str) or not client:
        raise ParseError("client must be a non-empty string")

    # Validate method
    if not isinstance(method, str) or not method:
        raise ParseError("method must be a non-empty string")
    if not method.isascii() or not method.isalpha():
        raise ParseError("method must be ASCII letters")
    method = method.upper()

    # Validate path
    if not path.startswith("/"):
        raise ParseError("path must start with /")
    # Remove query string and fragments
    if "?" in path:
        path = path[: path.index("?")]
    if "#" in path:
        path = path[: path.index("#")]
    # Collapse slashes
    path = re.sub(r"/+", "/", path)
    if not path.startswith("/"):
        raise ParseError("path must start with /")

    # Validate status
    try:
        status_int = int(status)
    except (ValueError, TypeError):
        raise ParseError("status must be an int or a string of digits")
    if not (100 <= status_int <= 599):
        raise ParseError("status must be between 100 and 599")

    # Validate size
    if size is None or size == "-":
        size_int = 0
    elif isinstance(size, str):
        try:
            size_int = int(size)
        except ValueError:
            raise ParseError("size must be a non-negative int or a string of digits")
    elif isinstance(size, int):
        size_int = size
    else:
        raise ParseError("size must be an int, str, None, or '-'")
    if size_int < 0:
        raise ParseError("size must be non-negative")

    # Validate latency_ms
    if latency_ms is None:
        latency_float = None
    elif isinstance(latency_ms, (int, float)):
        if latency_ms < 0:
            raise ParseError("latency_ms must be non-negative")
        latency_float = float(latency_ms)
    else:
        raise ParseError("latency_ms must be None or a number")

    return Record(
        time=time,
        client=client,
        method=method,
        path=path,
        status=status_int,
        size=size_int,
        latency_ms=latency_float,
    )


def _parse_clf_time(s: str) -> datetime:
    """Parse Apache common log time string: DD/Mon/YYYY:HH:MM:SS ±HHMM"""
    # Regex for: 10/Oct/2000:13:55:36 -0700
    pattern = r"(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2}) ([+-]\d{4})"
    m = re.match(pattern, s)
    if not m:
        raise ParseError(f"Invalid time format: {s}")

    day, month_str, year, hour, minute, second, tz_offset = m.groups()

    months = {
        "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
        "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
    }
    month = months.get(month_str)
    if month is None:
        raise ParseError(f"Invalid month abbreviation: {month_str}")

    tz_sign = 1 if tz_offset[0] == "+" else -1
    tz_hours = int(tz_offset[1:3])
    tz_minutes = int(tz_offset[3:5])
    tz_offset_seconds = tz_sign * (tz_hours * 3600 + tz_minutes * 60)

    naive = datetime(
        int(year), month, int(day), int(hour), int(minute), int(second)
    )

    # Create timezone object manually since we need UTC conversion
    tz = timezone(timedelta(seconds=tz_offset_seconds))
    aware = naive.replace(tzinfo=tz)

    return aware.astimezone(timezone.utc)


def parse_clf(line: str) -> Record:
    # Split by spaces, but be careful with the quoted request line
    # Format: client ident user [time] "method path protocol" status size [latency_us]

    # Find the closing bracket for time
    bracket_end = line.find("]")
    if bracket_end == -1:
        raise ParseError("Missing closing bracket for time")

    prefix_part = line[:bracket_end].strip()
    suffix_part = line[bracket_end + 1:].strip()

    # Parse prefix: client ident user [time]
    # We know the last part is [time], so split everything before it
    prefix_parts = prefix_part.split(" ")
    if len(prefix_parts) < 3:
        raise ParseError("Invalid prefix format")

    time_str = prefix_parts[-1]
    try:
        time = _parse_clf_time(time_str)
    except ParseError:
        raise

    client = prefix_parts[0]
    # ident and user are ignored

    # Parse suffix: "method path protocol" status size [latency_us]
    if not suffix_part.startswith('"'):
        raise ParseError("Request line must be quoted")

    # Remove quotes
    inner = suffix_part[1:-1]

    # Split inner by spaces to get method, path, protocol
    req_parts = inner.split(" ")
    if len(req_parts) != 3:
        raise ParseError("Request line must have exactly 3 parts")

    method, path, protocol = req_parts

    # Parse status and size
    parts_after_req = suffix_part[len(inner) + 1 :].strip().split(" ")
    if len(parts_after_req) < 2:
        raise ParseError("Missing status or size")

    status_str = parts_after_req[0]
    size_str = parts_after_req[1]

    try:
        status = int(status_str)
    except ValueError:
        raise ParseError("Invalid status")

    size = parse_size_like(size_str)

    # Optional latency
    latency_ms = None
    if len(parts_after_req) > 2:
        latency_us_str = parts_after_req[2]
        try:
            latency_us = int(latency_us_str)
            latency_ms = latency_us / 1000.0
        except ValueError:
            raise ParseError("Invalid latency value")

    return normalize(time, client, method, path, status, size, latency_ms)


def parse_size_like(s: str) -> int:
    """Helper to parse size string like "-" or digits"""
    if s == "-":
        return 0
    try:
        return int(s)
    except ValueError:
        raise ParseError("Invalid size string")


def parse_jsonl(line: str) -> Record:
    try:
        data = json.loads(line)
    except json.JSONDecodeError:
        raise ParseError("Invalid JSON")

    if not isinstance(data, dict):
        raise ParseError("JSON must be an object")

    # Check required keys
    required_keys = ["ts", "client", "method", "path", "status"]
    for key in required_keys:
        if key not in data:
            raise ParseError(f"Missing required key: {key}")

    ts_str = data["ts"]
    client = data["client"]
    method = data["method"]
    path = data["path"]
    status_str = data["status"]

    # Parse timestamp
    if not ts_str:
        raise ParseError("ts cannot be empty")

    # Handle 'Z' suffix
    if ts_str.endswith("Z"):
        ts_str = ts_str[:-1] + "+00:00"

    # ISO 8601 parsing
    try:
        # Python's fromisoformat handles the offset
        time = datetime.fromisoformat(ts_str)
    except ValueError:
        raise ParseError(f"Invalid ISO 8601 timestamp: {ts_str}")

    # Validate time
    if time.tzinfo is None:
        raise ParseError("ts must include timezone offset")
    if time.tzinfo.utcoffset(time) != timezone.utc.utcoffset(None):
        time = time.astimezone(timezone.utc)

    # Validate client, method, path, status
    client = normalize_client(client)
    method = normalize_method(method)
    path = normalize_path(path)
    status = int(status_str)

    # Validate status range
    if not (100 <= status <= 599):
        raise ParseError("status must be between 100 and 599")

    # Optional bytes/size
    size = 0
    if "bytes" in data:
        val = data["bytes"]
        if val is None or val == "-":
            size = 0
        elif isinstance(val, str):
            try:
                size = int(val)
            except ValueError:
                raise ParseError("bytes must be a string of digits, None, or '-'")
        elif isinstance(val, int):
            size = val
        else:
            raise ParseError("bytes must be a number")

    # Optional latency
    latency_ms = None
    if "latency_ms" in data:
        val = data["latency_ms"]
        if val is None:
            latency_ms = None
        elif isinstance(val, (int, float)):
            if val < 0:
                raise ParseError("latency_ms must be non-negative")
            latency_ms = float(val)
        else:
            raise ParseError("latency_ms must be a number")

    return normalize(time, client, method, path, status, size, latency_ms)


def normalize_client(s: str) -> str:
    if not isinstance(s, str) or not s:
        raise ParseError("client must be a non-empty string")
    return s


def normalize_method(s: str) -> str:
    if not isinstance(s, str) or not s:
        raise ParseError("method must be a non-empty string")
    if not s.isascii() or not s.isalpha():
        raise ParseError("method must be ASCII letters")
    return s.upper()


def normalize_path(s: str) -> str:
    if not s.startswith("/"):
        raise ParseError("path must start with /")
    if "?" in s:
        s = s[: s.index("?")]
    if "#" in s:
        s = s[: s.index("#")]
    s = re.sub(r"/+", "/", s)
    if not s.startswith("/"):
        raise ParseError("path must start with /")
    return s


def parse_line(line: str, fmt: str = "auto") -> Record:
    if fmt == "clf":
        return parse_clf(line)
    elif fmt == "jsonl":
        return parse_jsonl(line)
    elif fmt == "auto":
        stripped = line.strip()
        if stripped.startswith("{"):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError(f"Invalid format: {fmt}")


def read_records(lines: Iterable[str], fmt: str = "auto") -> Tuple[List[Record], List[int]]:
    records: List[Record] = []
    bad_lines: List[int] = []

    for i, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            # Skip empty lines, do not record as bad
            continue

        try:
            record = parse_line(stripped, fmt)
            records.append(record)
        except ParseError:
            bad_lines.append(i)

    return records, bad_lines
