# logagg/stats.py
import math
from collections import Counter
from datetime import datetime, timezone
from typing import Any, Dict, List, Optional, Tuple


def percentile(values: List[float], p: float) -> float:
    if not values:
        raise ValueError("percentile cannot be called with empty values")
    if p <= 0 or p > 100:
        raise ValueError("p must be in (0, 100]")

    sorted_values = sorted(values)
    n = len(sorted_values)

    # Nearest rank method: ceil(p / 100 * n) -> 1-based rank
    rank = math.ceil(p / 100.0 * n)
    # Convert to 0-based index
    index = rank - 1

    return sorted_values[index]


def filter_records(
    records: List[Record],
    since: Optional[datetime] = None,
    until: Optional[datetime] = None,
    status: Any = None,
) -> List[Record]:
    filtered = []

    for rec in records:
        # Time filter
        if since is not None and rec.time < since:
            continue
        if until is not None and rec.time >= until:
            continue

        # Status filter
        if status is not None:
            if isinstance(status, int):
                if rec.status != status:
                    continue
            elif isinstance(status, str):
                if status.startswith("4xx"):
                    start, end = int(status[3]), int(status[3]) + 9
                    if not (start <= rec.status <= end):
                        continue
                elif status.startswith("5xx"):
                    start, end = int(status[3]), int(status[3]) + 9
                    if not (start <= rec.status <= end):
                        continue
                elif status.isdigit():
                    if rec.status != int(status):
                        continue
                else:
                    raise ValueError(f"Invalid status format: {status}")
            else:
                raise ValueError(f"Invalid status type: {status}")

        filtered.append(rec)

    return filtered


def summarize(records: List[Record], top: int = 3) -> Dict[str, Any]:
    if top < 0:
        raise ValueError("top must be >= 0")

    n = len(records)

    # Basic counts
    requests = n

    bytes_total = sum(r.size for r in records)

    # Status classes
    classes: Dict[str, int] = {
        "1xx": 0, "2xx": 0, "3xx": 0, "4xx": 0, "5xx": 0,
    }
    for r in records:
        if 100 <= r.status <= 199:
            classes["1xx"] += 1
        elif 200 <= r.status <= 299:
            classes["2xx"] += 1
        elif 300 <= r.status <= 399:
            classes["3xx"] += 1
        elif 400 <= r.status <= 499:
            classes["4xx"] += 1
        elif 500 <= r.status <= 599:
            classes["5xx"] += 1

    # Status codes
    status_counter: Counter[int] = Counter(r.status for r in records)
    codes: Dict[str, int] = {str(k): v for k, v in sorted(status_counter.items())}

    # Latency stats
    latencies = [r.latency_ms for r in records if r.latency_ms is not None]

    latency_summary = {
        "count": len(latencies),
        "p50": percentile(latencies, 50) if latencies else None,
        "p95": percentile(latencies, 95) if latencies else None,
        "max": max(latencies) if latencies else None,
    }

    # Top paths
    path_counter: Counter[str] = Counter(r.path for r in records)
    # Sort by count descending, then path ascending
    sorted_paths = sorted(path_counter.items(), key=lambda x: (-x[1], x[0]))
    top_paths = sorted_paths[:top]
    top_paths_list = [[path, count] for path, count in top_paths]

    # First and last
    if records:
        first_time = min(r.time for r in records)
        last_time = max(r.time for r in records)
        first_str = first_time.isoformat()
        last_str = last_time.isoformat()
    else:
        first_str = None
        last_str = None

    return {
        "requests": requests,
        "bytes": bytes_total,
        "classes": classes,
        "codes": codes,
        "latency_ms": latency_summary,
        "top_paths": top_paths_list,
        "first": first_str,
        "last": last_str,
    }
