# logagg/cli.py
import argparse
import json
import sys
from datetime import datetime, timezone
from typing import List, Optional

from .parsers import read_records, ParseError
from .stats import filter_records, summarize


def parse_time_arg(s: str) -> datetime:
    """Parse ISO 8601 time string, handling optional offset."""
    # Python's fromisoformat handles most cases including +HH:MM or +HHMM
    try:
        dt = datetime.fromisoformat(s)
    except ValueError:
        # Try to handle missing offset by assuming UTC if it looks like ISO but lacks offset
        # Actually, the spec says "one without an offset is taken as UTC".
        # Python 3.11+ fromisoformat raises error if offset missing.
        # We need manual handling.

        # Simple heuristic: if it ends with Z, handle as UTC.
        # If it lacks offset, assume UTC.
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"

        # If still no offset, add one
        if "+" not in s and "-" not in s:
            s = s + "+00:00"

        dt = datetime.fromisoformat(s)

    # Ensure UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    elif dt.tzinfo.utcoffset(dt) != timezone.utc.utcoffset(None):
        dt = dt.astimezone(timezone.utc)

    return dt


def parse_status_arg(s: str) -> Optional[str]:
    """Parse status filter string. Returns None if no filter."""
    if s is None:
        return None
    if s.isdigit():
        return s
    if s.startswith("4xx") or s.startswith("5xx"):
        return s
    raise ValueError(f"Invalid status filter: {s}")


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Aggregate web server logs.")
    parser.add_argument("files", nargs="+", help="Log files to process")
    parser.add_argument(
        "--format",
        choices=["auto", "clf", "jsonl"],
        default="auto",
        help="Log format to use",
    )
    parser.add_argument(
        "--since",
        dest="since_str",
        help="Filter records since this time (ISO 8601)",
    )
    parser.add_argument(
        "--until",
        dest="until_str",
        help="Filter records until this time (ISO 8601)",
    )
    parser.add_argument(
        "--status",
        dest="status_str",
        help="Filter records by status (class like '4xx' or exact code like '404')",
    )
    parser.add_argument(
        "--top",
        type=int,
        default=3,
        help="Number of top paths to show",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="Output summary as JSON",
    )

    args = parser.parse_args(argv)

    try:
        # Parse time filters
        since = None
        if args.since_str:
            since = parse_time_arg(args.since_str)

        until = None
        if args.until_str:
            until = parse_time_arg(args.until_str)

        # Parse status filter
        status_filter = parse_status_arg(args.status_str)

        # Parse top
        if args.top < 0:
            print("error: --top must be non-negative", file=sys.stderr)
            return 2

        # Read and parse all files
        all_records: List[Record] = []
        all_bad_lines: List[int] = []

        for filepath in args.files:
            try:
                with open(filepath, "r", encoding="utf-8") as f:
                    lines = f.readlines()
            except (IOError, OSError) as e:
                print(f"error: cannot read file {filepath}: {e}", file=sys.stderr)
                return 2

            records, bad_lines = read_records(lines, args.format)
            all_records.extend(records)
            all_bad_lines.extend(bad_lines)

        # Filter records
        filtered_records = filter_records(
            all_records,
            since=since,
            until=until,
            status=status_filter,
        )

        # Summarize
        summary = summarize(filtered_records, args.top)

        # Prepare output
        if args.json:
            output_summary = summary.copy()
            output_summary["bad_lines"] = len(all_bad_lines)
            print(json.dumps(output_summary, indent=2))
        else:
            bad_count = len(all_bad_lines)

            lines = [
                f"requests: {summary['requests']}",
                f"bad lines: {bad_count}",
                f"bytes: {summary['bytes']}",
            ]

            # Status classes line
            status_line_parts = []
            for key in ["1xx", "2xx", "3xx", "4xx", "5xx"]:
                status_line_parts.append(f"{key}={summary['classes'][key]}")
            lines.append("status: " + " ".join(status_line_parts))

            # Latency line
            lat = summary["latency_ms"]
            if lat["count"] == 0:
                lines.append("latency: n/a")
            else:
                p50 = lat["p50"]
                p95 = lat["p95"]
                max_lat = lat["max"]
                lines.append(
                    f"latency: p50={p50:.1f} ms p95={p95:.1f} ms max={max_lat:.1f} ms"
                )

            # Top paths
            lines.append("top paths:")
            if not summary["top_paths"]:
                lines.append("  none")
            else:
                for path, count in summary["top_paths"]:
                    lines.append(f"  {count} {path}")

            for line in lines:
                print(line)

        return 0

    except (ValueError, ParseError) as e:
        if "error:" in str(e):
            print(f"error: {e}", file=sys.stderr)
        else:
            print(f"error: {e}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
