# vfs/paths.py
"""
Path manipulation utilities.

Paths use `/`. A name is any non-empty string without `/`.
`.` and `..` are special.
"""

import re


def normalize(path: str, cwd: str = "/") -> str:
    """
    Returns an absolute path with no `.`, `..`, repeated `/`, or trailing `/`.
    If path is empty, raises ValueError.
    Relative paths are resolved relative to cwd.
    """
    if not path:
        raise ValueError("Path cannot be empty")

    if not path.startswith("/"):
        path = join(cwd, path)

    parts = path.split("/")
    result = []

    for part in parts:
        if part == ".":
            continue
        elif part == "..":
            if result and result[-1] != "..":
                result.pop()
            elif result and result[-1] == "..":
                # Double .. at root or already at root, stay put
                pass
            else:
                # Trying to go above root
                pass
        elif part:
            result.append(part)

    # Normalize separators
    while "//" in "/".join(result):
        "/".join(result).replace("//", "/")
        # The loop above logic is simpler in code:
        cleaned = "/".join(result).replace("//", "/")
        if cleaned != "/".join(result):
            result = cleaned.split("/")
        else:
            break

    # Re-join to ensure single slashes
    normalized = "/" + "/".join(result) if result else "/"

    # Final check for trailing slash (except root)
    if normalized != "/" and normalized.endswith("/"):
        normalized = normalized.rstrip("/")

    return normalized


def join(base: str, *parts: str) -> str:
    """
    Joins path components. If any part starts with '/', it becomes the new root.
    Returns the result normalized.
    """
    if not base:
        base = "/"

    # Check if any part starts with '/'
    if any(part.startswith("/") for part in parts):
        new_base = "/"
    else:
        new_base = base

    all_parts = [new_base] + [p for p in parts if p]

    # Join manually to handle the root logic correctly
    # If new_base is "/", the list becomes ["/", ...]
    # If new_base is not "/", the list is [..., ...]

    # Simpler approach: start with new_base, append others
    combined = new_base
    for p in parts:
        combined = combined.rstrip("/") + "/" + p if p else combined

    return normalize(combined)


def split(path: str) -> tuple[str, str]:
    """
    Takes an absolute normalized path and returns (parent, name).
    split("/") is ("/", "").
    """
    if path == "/":
        return ("/", "")

    # path is like /a/b/c
    # split by '/', filter out empty strings from split result
    parts = [p for p in path.split("/") if p]

    if not parts:
        # Should be caught by normalize, but just in case
        return ("/", "")

    parent = "/".join(parts[:-1])
    name = parts[-1]

    return (parent, name)


def is_within(path: str, ancestor: str) -> bool:
    """
    Tells whether the normalized path is ancestor itself or lies below it.
    """
    p = normalize(path)
    a = normalize(ancestor)

    if p == a:
        return True

    # Check if p starts with a + "/"
    # Example: /ab within /a? Yes. /a within /a? Handled above.
    # Example: /a/b within /a? Yes.
    # Example: /a within /b? No.

    if len(a) < len(p):
        return p.startswith(a + "/")
    return False
