# vfs/fs.py
"""
The in-memory FileSystem implementation.
"""

import os
import fnmatch
from pathlib import Path
from typing import List, Tuple, Optional, Union

from .paths import normalize, join, split

class FSError(Exception):
    """Base class for filesystem errors."""
    pass

class NotFound(FSError):
    def __init__(self, path: str):
        super().__init__(normalize(path))

class AlreadyExists(FSError):
    def __init__(self, path: str):
        super().__init__(normalize(path))

class NotADirectory(FSError):
    def __init__(self, path: str):
        super().__init__(normalize(path))

class IsADirectory(FSError):
    def __init__(self, path: str):
        super().__init__(normalize(path))

class InvalidOperation(FSError):
    def __init__(self, path: str):
        super().__init__(normalize(path))


class FileSystem:
    def __init__(self):
        # Structure: parent -> { 'children': [ (name, type), ... ], 'content': str }
        # Root is always there.
        self._data: dict[str, dict] = {
            "/": {"children": {}, "content": None}
        }
        self._cwd = "/"

    def _get_path_node(self, path: str) -> dict:
        """Returns the node dict for the given path. Path must be normalized and absolute."""
        current = self._data
        for part in path.split("/")[1:]:
            if part not in current["children"]:
                raise NotFound(path)
            current = current["children"][part]
        return current

    def _ensure_parent(self, path: str) -> dict:
        """Ensures all parents exist, returns the parent node dict."""
        current = self._data
        parts = path.split("/")
        for i, part in enumerate(parts[:-1]):
            if i == 0 and part == "":
                continue
            node = current
            if part not in node["children"]:
                if part == "":
                    # This shouldn't happen with normalized paths except root logic
                    continue
                raise NotFound(path)
            node = node["children"][part]
            if "content" in node:
                raise IsADirectory(path)
        return current

    def _is_parent_of(self, path: str) -> bool:
        """Checks if path is a parent of the current directory."""
        # We check if current directory ends with '/' + path
        if self._cwd == path:
            return True
        # Check if path + "/" is a prefix of cwd
        if self._cwd.startswith(path + "/"):
            return True
        return False

    def _get_name(self, path: str) -> str:
        """Extracts the name component from an absolute path."""
        parent, name = split(path)
        return name

    def pwd(self) -> str:
        """Returns the current directory."""
        return self._cwd

    def cd(self, path: str) -> None:
        """Change directory."""
        abs_path = normalize(path, self._cwd)
        node = self._get_path_node(abs_path)
        if "content" in node:
            raise NotADirectory(abs_path)
        self._cwd = abs_path

    def mkdir(self, path: str, parents: bool = False) -> None:
        """Create directory."""
        abs_path = normalize(path, self._cwd)

        # Check if parent is missing
        if not parents:
            parent_node = self._ensure_parent(abs_path)
            # Check if parent is a file
            if "content" in parent_node:
                raise IsADirectory(abs_path)
            # Check if parent is not /
            if abs_path == "/" and not parents:
                raise InvalidOperation(abs_path)
        else:
            # With parents, we create missing dirs.
            # But we still need to ensure the immediate parent exists.
            # If path is /a/b and /a doesn't exist, create it.
            parts = abs_path.split("/")
            current = self._data
            for i, p in enumerate(parts):
                if i == 0:
                    continue
                if p not in current["children"]:
                    if p == "":
                        continue
                    current["children"][p] = {"children": {}, "content": None}
                    if i == len(parts) - 1:
                        current = current["children"][p]
                    else:
                        current = current["children"][p]["children"]

            # Check if the target path itself already exists as a file
            if "content" in self._get_path_node(abs_path):
                raise AlreadyExists(abs_path)

        # Check if target exists as directory
        if abs_path in self._data["children"]:
            raise AlreadyExists(abs_path)

        self._data["children"][self._get_name(abs_path)] = {"children": {}, "content": None}

    def write(self, path: str, text: str, append: bool = False) -> None:
        """Write text to file."""
        abs_path = normalize(path, self._cwd)
        parent_node = self._ensure_parent(abs_path)

        if "content" in parent_node:
            raise IsADirectory(abs_path)

        if "content" in self._data.get("/"):
            raise NotADirectory(abs_path)

        if append:
            # Check if file exists
            if abs_path not in self._data["children"]:
                raise NotFound(path)
            existing = self._data["children"][self._get_name(abs_path)]
            if existing["content"] is None:
                existing["content"] = ""
            existing["content"] += text
        else:
            parent_node["content"] = text
            parent_node["children"][self._get_name(abs_path)] = {"children": {}, "content": text}

    def read(self, path: str) -> str:
        """Read file text."""
        abs_path = normalize(path, self._cwd)
        node = self._get_path_node(abs_path)
        if node["content"] is None:
            raise NotFound(path)
        return node["content"]

    def ls(self, path: str = ".") -> List[str]:
        """List directory entries."""
        abs_path = normalize(path, self._cwd)
        node = self._get_path_node(abs_path)
        entries = []
        for name, child in node["children"].items():
            if "content" in child:
                entries.append(name)
            else:
                entries.append(f"{name}/")
        return sorted(entries)

    def rm(self, path: str, recursive: bool = False) -> None:
        """Remove file or directory."""
        abs_path = normalize(path, self._cwd)

        # Check if path is / or ancestor
        if self._is_parent_of(abs_path):
            raise InvalidOperation(abs_path)

        # Check if exists
        if abs_path not in self._data["children"]:
            # It might be a file directly under /
            if abs_path not in self._data["children"]:
                raise NotFound(path)
            # It is a file
            # Check if it is current dir
            if abs_path == self._cwd:
                raise InvalidOperation(abs_path)
            # Check if it is ancestor (handled above mostly, but root case)
            if abs_path == "/":
                raise InvalidOperation(abs_path)

        # Check if file
        if "content" in self._data["children"][self._get_name(abs_path)]:
            # It is a file
            if recursive:
                self._data["children"][self._get_name(abs_path)] = {"children": {}, "content": None}
                del self._data["children"][self._get_name(abs_path)]["children"]
                del self._data["children"][self._get_name(abs_path)]["content"]
                # Actually we need to delete the key from children
                # Wait, logic error above. 
                # If recursive and it's a file, we delete it.
                del self._data["children"][self._get_name(abs_path)]
            else:
                raise IsADirectory(abs_path)
        elif abs_path in self._data["children"]:
            # It is a directory
            if recursive:
                self._remove_directory_recursive(self._data["children"][self._get_name(abs_path)])
                del self._data["children"][self._get_name(abs_path)]
            else:
                raise IsADirectory(abs_path)
        else:
            raise NotFound(path)

    def _remove_directory_recursive(self, node: dict) -> None:
        """Helper to delete a directory and its contents."""
        for child_name, child in node["children"].items():
            if "content" in child:
                del self._data["children"][self._get_name(child_name)]
            else:
                self._remove_directory_recursive(child)
        del node["children"]
        if node["content"] is not None:
            del node["content"]

    def mv(self, src: str, dst: str) -> None:
        """Move or rename."""
        abs_src = normalize(src, self._cwd)

        # Check src validity
        if self._is_parent_of(abs_src):
            raise InvalidOperation(src)

        # Check if src exists
        if abs_src not in self._data["children"]:
            raise NotFound(src)

        # Check if dst parent exists
        parent_dst = normalize(str(dst).rsplit("/", 1)[0], self._cwd)
        if parent_dst not in self._data["children"]:
            if parent_dst == "/":
                # dst is just a name
                raise NotFound(dst)
            else:
                raise NotFound(dst)

        # Check if dst is inside src
        if is_within(dst, src):
            raise InvalidOperation(src)

        # Check if dst exists
        abs_dst = normalize(dst, self._cwd)
        if abs_dst in self._data["children"]:
            raise AlreadyExists(abs_dst)

        # Check if dst parent is a file? No, dst parent must be a directory.
        # But dst itself could be a file.
        # If dst is a file, we overwrite.

        # Perform move
        src_node = self._data["children"][self._get_name(abs_src)]

        # If dst is a directory, rename to dst/NAME
        if abs_dst in self._data["children"]:
            # dst is a directory
            parent = self._get_path_node(abs_dst)
            dst_name = f"{self._get_name(abs_src)}{self._get_name(abs_dst)}"
            dst_path = join(parent, dst_name)
            self._data["children"][dst_name] = src_node
        else:
            # dst is a file or new file
            dst_name = self._get_name(abs_dst)
            parent_node = self._data["children"][self._get_name(parent_dst)]
            parent_node["children"][dst_name] = src_node
            self._data["children"][self._get_name(abs_src)] = src_node # Temp move? No, just swap content reference

        # Clean up src
        del self._data["children"][self._get_name(abs_src)]

    def find(self, path: str = ".", pattern: str = "*") -> List[str]:
        """Find files matching pattern."""
        abs_path = normalize(path, self._cwd)

        # Check if path exists
        if abs_path not in self._data["children"]:
            # Check if it is a file directly
            if abs_path == "/":
                return []
            raise NotFound(path)

        results = []

        if "content" in self._data["children"][self._get_name(abs_path)]:
            # It is a file
            if fnmatch.fnmatch(self._get_name(abs_path), pattern):
                results.append(abs_path)
            return results

        # It is a directory
        current_node = self._data["children"][self._get_name(abs_path)]

        def dfs(node: dict, current_full_path: str):
            for name, child in node["children"].items():
                full_path = join(current_full_path, name)
                if "content" in child:
                    if fnmatch.fnmatch(name, pattern):
                        results.append(full_path)
                else:
                    dfs(child, full_path)

        dfs(current_node, abs_path)
        return sorted(results)

    def exists(self, path: str) -> bool:
        """Check if path exists (file or dir)."""
        try:
            normalize(path, self._cwd)
            return path in self._data or (
                self._data.get("children", {}).get(self._get_name(path)) is not None
            )
        except:
            return False

    def is_dir(self, path: str) -> bool:
        """Check if path is a directory."""
        abs_path = normalize(path, self._cwd)
        # Check if path itself is a directory entry
        if abs_path not in self._data["children"]:
            return False
        node = self._data["children"][abs_path]
        return "content" not in node
