"""
A tiny shell that runs scripts against the FileSystem.
"""

import sys
import shlex
from typing import Tuple, Optional

from .fs import FileSystem, FSError, NotFound, AlreadyExists, NotADirectory, IsADirectory, InvalidOperation
from .paths import normalize, join

class Shell:
    def __init__(self, fs: Optional[FileSystem] = None):
        self.fs = fs if fs is not None else FileSystem()
        self._cwd = self.fs.pwd()

    def _parse_args(self, line: str) -> list:
        """Split line into args using shlex, handling errors."""
        try:
            return shlex.split(line)
        except ValueError:
            raise ValueError("Quoting error")

    def _run_command(self, line: str, line_num: int) -> Tuple[Optional[str], int]:
        """
        Runs a single command.
        Returns (output_string, status_code) or (None, 1) if error occurred.
        """
        parts = self._parse_args(line)
        if not parts:
            return ("", 0)

        cmd = parts[0]
        args = parts[1:]

        # Flag handling
        p_flag = False
        r_flag = False

        if cmd == "write" and args and args[0] == "-p":
            p_flag = True
            args = args[1:]
        elif cmd == "write" and args and args[0] == "-r":
            r_flag = True
            args = args[1:]
        elif cmd == "append" and args and args[0] == "-p":
            p_flag = True
            args = args[1:]
        elif cmd == "append" and args and args[0] == "-r":
            r_flag = True
            args = args[1:]
        elif cmd == "mkdir" and args and args[0] == "-p":
            p_flag = True
            args = args[1:]
        elif cmd == "mkdir" and args and args[0] == "-r":
            r_flag = True
            args = args[1:]

        # Special case: mv doesn't have -p or -r
        # rm doesn't have -p, only -r
        # find doesn't have -p, only -n/-name

        try:
            if cmd == "pwd":
                self.fs.cd(self._cwd)
                output = f"{self._cwd}\n"
                return (output, 0)

            elif cmd == "cd":
                if not args:
                    raise ValueError("Usage")
                path = join(self._cwd, *args)
                try:
                    self.fs.cd(path)
                except NotFound as e:
                    return (f"line {line_num}: cd: {type(e).__name__}: {e}", 1)
                except NotADirectory as e:
                    return (f"line {line_num}: cd: {type(e).__name__}: {e}", 1)

            elif cmd == "mkdir":
                if not args:
                    raise ValueError("Usage")
                for i, arg in enumerate(args):
                    full_path = join(self._cwd, *args[:i+1])
                    if i < len(args) - 1:
                        # Check if intermediate parent exists and is dir
                        # Actually mkdir handles parents internally if -p is set, but if not set, parent must exist.
                        # The spec says: NotFound(path) if parent is missing and not parents.
                        # So we need to check the immediate parent of the target.
                        pass
                    try:
                        self.fs.mkdir(full_path, parents=p_flag)
                    except AlreadyExists as e:
                        return (f"line {line_num}: mkdir: {type(e).__name__}: {e}", 1)
                    except NotFound as e:
                        return (f"line {line_num}: mkdir: {type(e).__name__}: {e}", 1)
                    except IsADirectory as e:
                        return (f"line {line_num}: mkdir: {type(e).__name__}: {e}", 1)

            elif cmd == "ls":
                if args:
                    path = join(self._cwd, *args)
                    try:
                        entries = self.fs.ls(path)
                        for e in entries:
                            output += e + "\n"
                    except NotFound as e:
                        return (f"line {line_num}: ls: {type(e).__name__}: {e}", 1)
                else:
                    try:
                        entries = self.fs.ls(self._cwd)
                        for e in entries:
                            output += e + "\n"
                    except NotFound as e:
                        return (f"line {line_num}: ls: {type(e).__name__}: {e}", 1)

            elif cmd == "rm":
                if not args:
                    raise ValueError("Usage")
                recursive = r_flag
                for i, arg in enumerate(args):
                    full_path = join(self._cwd, *args[:i+1])
                    try:
                        self.fs.rm(full_path, recursive=recursive)
                    except NotFound as e:
                        return (f"line {line_num}: rm: {type(e).__name__}: {e}", 1)
                    except InvalidOperation as e:
                        return (f"line {line_num}: rm: {type(e).__name__}: {e}", 1)
                    except IsADirectory as e:
                        return (f"line {line_num}: rm: {type(e).__name__}: {e}", 1)

            elif cmd == "mv":
                if len(args) != 2:
                    raise ValueError("Usage")
                src, dst = args
                # Check src validity first
                src_abs = join(self._cwd, src)
                try:
                    # Check if src is / or ancestor
                    if self.fs._is_parent_of(src_abs):
                        raise InvalidOperation(src)

                    if self.fs._is_parent_of(src_abs):
                        raise InvalidOperation(src)

                    # Check existence
                    try:
                        self.fs._ensure_parent(src_abs)
                        # Check if src is file
                        if "content" in self.fs._data["children"][self.fs._get_name(src_abs)]:
                            pass
                        else:
                            raise NotFound(src)
                    except NotFound:
                        raise NotFound(src)

                    # Check dst
                    dst_abs = join(self._cwd, dst)
                    if dst_abs == src_abs:
                        raise InvalidOperation(src)

                    # Check if dst parent is missing
                    parent_dst = join(self._cwd, dst)
                    # If dst is a name, parent is /
                    # If dst is a path, parent is ...

                    # Check if dst exists
                    if dst_abs in self.fs._data["children"]:
                        raise AlreadyExists(dst_abs)

                    # Perform move
                    self.fs.mv(src_abs, dst_abs)
                except NotFound as e:
                    return (f"line {line_num}: mv: {type(e).__name__}: {e}", 1)
                except InvalidOperation as e:
                    return (f"line {line_num}: mv: {type(e).__name__}: {e}", 1)
                except AlreadyExists as e:
                    return (f"line {line_num}: mv: {type(e).__name__}: {e}", 1)
                except NotFound as e:
                    return (f"line {line_num}: mv: {type(e).__name__}: {e}", 1)

            elif cmd == "write":
                if not args:
                    raise ValueError("Usage")
                path = args[0]
                content = " ".join(args[1:])
                try:
                    self.fs.write(path, content, append=p_flag)
                except IsADirectory as e:
                    return (f"line {line_num}: write: {type(e).__name__}: {e}", 1)
                except NotFound as e:
                    return (f"line {line_num}: write: {type(e).__name__}: {e}", 1)

            elif cmd == "append":
                if not args:
                    raise ValueError("Usage")
                path = args[0]
                content = " ".join(args[1:])
                try:
                    self.fs.append(path, content)
                except IsADirectory as e:
                    return (f"line {line_num}: append: {type(e).__name__}: {e}", 1)
                except NotFound as e:
                    return (f"line {line_num}: append: {type(e).__name__}: {e}", 1)

            elif cmd == "cat":
                if not args:
                    raise ValueError("Usage")
                for i, arg in enumerate(args):
                    full_path = join(self._cwd, *args[:i+1])
                    try:
                        self.fs._ensure_parent(full_path)
                        if "content" in self.fs._data["children"][self.fs._get_name(full_path)]:
                            output += self.fs.read(full_path) + "\n"
                        else:
                            raise NotADirectory(full_path)
                    except NotFound as e:
                        return (f"line {line_num}: cat: {type(e).__name__}: {e}", 1)
                    except IsADirectory as e:
                        return (f"line {line_num}: cat: {type(e).__name__}: {e}", 1)

            elif cmd == "find":
                path = "."
                pattern = "*"
                if args:
                    if not args[0].startswith("-name"):
                        path = args[0]
                    elif args[0] == "-name":
                        if len(args) < 2:
                            raise ValueError("Usage")
                        pattern = args[1]
                    else:
                        raise ValueError("Usage")

                # Handle path logic: if path is relative, join cwd
                if path != ".":
                    path = join(self._cwd, path)

                try:
                    results = self.fs.find(path, pattern)
                    for r in results:
                        output += r + "\n"
                except NotFound as e:
                    return (f"line {line_num}: find: {type(e).__name__}: {e}", 1)

            else:
                return (f"line {line_num}: {cmd}: unknown command", 2)

        except ValueError as e:
            return (f"line {line_num}: {cmd}: usage", 2)

        return (output, 0)

    def run(self, script: str) -> Tuple[str, int]:
        """
        Run a script string.
        Returns (full_output, status_code).
        """
        lines = script.split("\n")
        output_parts = []
        error_occurred = False
        last_status = 0

        for i, line in enumerate(lines, 1):
            # Strip
            stripped = line.strip()
            if not stripped:
                continue
            if stripped.startswith("#"):
                continue

            output, status = self._run_command(line, i)
            output_parts.append(output)

            if output:
                if status != 0:
                    # Error happened
                    if error_occurred:
                        # Multiple errors? Spec says "The first error stops the script".
                        # So subsequent errors are ignored.
                        pass
                    else:
                        error_occurred = True
                        last_status = status

            if error_occurred:
                break

        return ("\n".join(output_parts), last_status)


def run_script(script_path: str) -> int:
    """
    Run a script file.
    Prints output to stdout and status to sys.exit code.
    Prints error to stderr.
    """
    try:
        with open(script_path, "r", encoding="utf-8") as f:
            script_content = f.read()
    except FileNotFoundError:
        print(f"error: {script_path}", file=sys.stderr)
        return 2
    except Exception as e:
        print(f"error: {e}", file=sys.stderr)
        return 2

    shell = Shell()
    output, status = shell.run(script_content)

    print(output, end="")
    return status


if __name__ == "__main__":
    if len(sys.argv) > 1:
        sys.exit(run_script(sys.argv[1]))
    else:
        # If no script provided, maybe show usage? 
        # The spec implies usage is for running against a file.
        # But let's just print usage to stderr and exit 2.
        print("usage: python -m vfs.shell SCRIPT", file=sys.stderr)
        sys.exit(2)
