# objstore/objects.py
from dataclasses import dataclass, field
from typing import Iterable, NamedTuple, Tuple
from pathlib import PurePosixPath

import hashlib

@dataclass(frozen=True)
class Blob:
    data: bytes

@dataclass(frozen=True)
class Commit:
    tree: str
    parents: Tuple[str, ...]
    author: str
    timestamp: int
    message: str

@dataclass(frozen=True)
class Tree:
    entries: Tuple[TreeEntry, ...]

class TreeEntry(NamedTuple):
    name: str
    kind: str
    oid: str

    def __hash__(self):
        return hash((self.name, self.kind, self.oid))

def _validate_name(name: str) -> None:
    if not name:
        raise ValueError("Name cannot be empty")
    if name in ('.', '..'):
        raise ValueError("Name cannot be '.' or '..'")
    for bad_char in ('/', '\\0', '\t', '\n'):
        if bad_char in name:
            raise ValueError(f"Name contains forbidden character: {repr(bad_char)}")

def _validate_commit_message(msg: str) -> None:
    if '\n' in msg:
        raise ValueError("Commit message cannot contain newlines")

def _serialize_header(type_: str, length: int) -> bytes:
    return f"{type_} {length}\x00".encode('ascii')

def serialize(blob: Blob) -> bytes:
    body = blob.data
    header = _serialize_header("blob", len(body))
    return header + body

def serialize(tree: Tree) -> bytes:
    body_parts = []
    for entry in tree.entries:
        line = f"{entry.kind} {entry.oid}\t{entry.name}\n"
        body_parts.append(line.encode('utf-8'))
    body = b''.join(body_parts)
    header = _serialize_header("tree", len(body))
    return header + body

def serialize(commit: Commit) -> bytes:
    lines: list[bytes] = []
    lines.append(f"tree {commit.tree}\n".encode('utf-8'))
    for p in commit.parents:
        lines.append(f"parent {p}\n".encode('utf-8'))
    lines.append(f"author {commit.author}\n".encode('utf-8'))
    lines.append(f"time {commit.timestamp}\n".encode('utf-8'))
    lines.append(b"\n")
    lines.append(commit.message.encode('utf-8'))
    body = b''.join(lines)
    header = _serialize_header("commit", len(body))
    return header + body

def object_id(obj: object) -> str:
    data = serialize(obj)
    return hashlib.sha1(data).hexdigest()

class CorruptObject(ValueError):
    pass

def parse_object(raw: bytes) -> object:
    if len(raw) < 11:
        raise CorruptObject("Header too short")

    header_end = raw.find(b'\x00')
    if header_end == -1:
        raise CorruptObject("No null terminator in header")

    header = raw[:header_end].decode('ascii')
    parts = header.split(' ', 1)
    if len(parts) != 2:
        raise CorruptObject("Malformed header")

    obj_type = parts[0].lower()
    try:
        length = int(parts[1])
    except ValueError:
        raise CorruptObject("Invalid header length")

    if obj_type not in ('blob', 'tree', 'commit'):
        raise CorruptObject(f"Unknown object type: {obj_type}")

    body_start = header_end + 1
    body_end = len(raw)
    body = raw[body_start:body_end]

    if len(body) != length:
        raise CorruptObject(f"Body length mismatch: expected {length}, got {len(body)}")

    if obj_type == 'blob':
        return Blob(body)

    if obj_type == 'tree':
        entries: list[TreeEntry] = []
        idx = 0
        while idx < len(body):
            line_start = body.find(b'\n', idx)
            if line_start == -1:
                raise CorruptObject("Unexpected end of tree body")
            line = body[idx:line_start]

            try:
                line_str = line.decode('utf-8')
            except UnicodeDecodeError:
                raise CorruptObject("Tree entry contains non-UTF-8 data")

            parts = line_str.split('\t', 1)
            if len(parts) != 2:
                raise CorruptObject(f"Invalid tree entry format: {repr(line_str)}")

            kind_oid_part, name = parts

            if not kind_oid_part or not name:
                raise CorruptObject("Invalid tree entry content")

            kind, oid = kind_oid_part.split(' ', 1)
            if kind not in ('blob', 'tree'):
                raise CorruptObject(f"Invalid kind in tree entry: {kind}")

            _validate_name(name)
            entries.append(TreeEntry(name=name, kind=kind, oid=oid))

            idx = line_start + 1

        if not entries:
            return Tree(())

        # Sort entries by UTF-8 bytes of names
        sorted_entries = sorted(entries, key=lambda e: e.name.encode('utf-8'))
        return Tree(tuple(sorted_entries))

    if obj_type == 'commit':
        idx = 0
        fields: list[Tuple[str, str]] = []

        while idx < len(body):
            line_start = body.find(b'\n', idx)
            if line_start == -1:
                raise CorruptObject("Unexpected end of commit body")

            line = body[idx:line_start].decode('utf-8')
            parts = line.split(' ', 1)

            if not parts:
                raise CorruptObject("Empty line in commit body")

            field_name, value = parts[0], parts[1] if len(parts) > 1 else ''

            if field_name == 'tree':
                if not value:
                    raise CorruptObject("Empty tree oid")
                fields.append(('tree', value))
            elif field_name == 'parent':
                if not value:
                    raise CorruptObject("Empty parent oid")
                fields.append(('parent', value))
            elif field_name == 'author':
                if not value:
                    raise CorruptObject("Empty author")
                # Allow empty name/email if value is empty string after space, but strict check on newline
                if '\n' in value:
                     raise CorruptObject("Author contains newline")
                fields.append(('author', value))
            elif field_name == 'time':
                if not value:
                    raise CorruptObject("Empty timestamp")
                try:
                    timestamp = int(value)
                except ValueError:
                    raise CorruptObject("Invalid timestamp")
                if timestamp < 0:
                    raise CorruptObject("Negative timestamp")
                fields.append(('timestamp', str(timestamp)))
            else:
                raise CorruptObject(f"Unknown field in commit: {field_name}")

            idx = line_start + 1

        if 'timestamp' not in [f[0] for f in fields]:
            raise CorruptObject("Missing timestamp")
        timestamp = int(fields[fields.index(('timestamp', ''))[1]])

        tree_oid = fields[0][1] if 'tree' in [f[0] for f in fields] else None
        if tree_oid is None:
            raise CorruptObject("Missing tree field")

        parent_oids = tuple(f[1] for f in fields if f[0] == 'parent')

        author = fields[2][1] if 'author' in [f[0] for f in fields] else ""
        message = fields[-1][1] if len(fields) > 3 else ""

        return Commit(
            tree=tree_oid,
            parents=tuple(parent_oids),
            author=author,
            timestamp=timestamp,
            message=message
        )

    raise CorruptObject(f"Unsupported object type: {obj_type}")
