# objstore/store.py
from .objects import (
    Blob, 
    Tree, 
    Commit, 
    serialize, 
    object_id, 
    parse_object, 
    CorruptObject
)
from typing import Dict, Iterable, Optional, Tuple, Any
import re

class ObjectNotFound(KeyError):
    pass

class AmbiguousPrefix(ValueError):
    pass

class ObjectStore:
    def __init__(self):
        self._store: Dict[str, bytes] = {}

    def put(self, obj: object) -> str:
        data = serialize(obj)
        oid = object_id(obj)
        self._store[oid] = data
        return oid

    def put_raw(self, raw: bytes) -> str:
        obj = parse_object(raw)
        return self.put(obj)

    def get(self, oid: str) -> object:
        data = self._store.get(oid)
        if data is None:
            raise ObjectNotFound(f"Object {oid} not found")
        return parse_object(data)

    def get_raw(self, oid: str) -> bytes:
        data = self._store.get(oid)
        if data is None:
            raise ObjectNotFound(f"Object {oid} not found")
        return data

    def __contains__(self, oid: str) -> bool:
        return oid in self._store

    def resolve(self, prefix: str) -> str:
        # Validate prefix length and format
        if not (4 <= len(prefix) <= 40):
            raise ValueError(f"Invalid prefix length: {len(prefix)} (must be 4-40)")

        # Check lowercase hex
        if not re.match(r'^[0-9a-f]+$', prefix):
            raise ValueError(f"Invalid prefix format: {prefix}")

        matches = [oid for oid in self._store if oid.startswith(prefix)]

        if len(matches) == 0:
            raise ObjectNotFound(f"No object found starting with prefix {prefix}")
        if len(matches) > 1:
            raise AmbiguousPrefix(f"Multiple objects found starting with prefix {prefix}")

        return matches[0]

    def write_tree(self, files: Dict[str, bytes]) -> str:
        # Validate paths
        for path in files:
            if not path:
                raise ValueError("Path cannot be empty")
            if path.startswith('/') or path.endswith('/'):
                raise ValueError("Path cannot start or end with '/'")
            # Check for empty parts (e.g. 'a//b')
            if '/' in path:
                parts = path.split('/')
                if any(not p for p in parts):
                    raise ValueError("Path contains empty part")
            # Validate name constraints on parts
            for p in path.split('/'):
                _validate_name(p)

        # Build tree structure
        tree_dict: Dict[str, Dict[str, Any]] = {}

        # First pass: determine if path is a file or directory
        for path, data in files.items():
            parts = path.split('/')
            current = tree_dict
            for i, part in enumerate(parts[:-1]): # All parts except last
                full_path = '/'.join(parts[:i+1])
                if full_path not in current:
                    current[full_path] = {'kind': 'tree', 'entries': {}}
                current[full_path] = current[full_path]['kind'] # Mark as tree

                # Check if this path is also a file
                if path in files:
                    raise ValueError(f"Path '{path}' is both a file and a directory")

                current = current[full_path]['entries']

            last_part = parts[-1]
            full_path = '/'.join(parts)

            if full_path not in current:
                current[full_path] = {'kind': 'blob', 'data': data}
            elif current[full_path]['kind'] == 'tree':
                raise ValueError(f"Path '{full_path}' is both a file and a directory")
            else:
                # Should not happen if input dict is consistent, but safety check
                pass

        def build_tree(entries_dict: Dict[str, Any]) -> Tree:
            entries: list[TreeEntry] = []
            for key, val in entries_dict.items():
                if val['kind'] == 'blob':
                    entries.append(TreeEntry(name=key, kind='blob', oid=object_id(Blob(val['data']))))
                elif val['kind'] == 'tree':
                    sub_tree = build_tree(val['entries'])
                    entries.append(TreeEntry(name=key, kind='tree', oid=object_id(sub_tree)))
                else:
                    raise ValueError(f"Unknown kind in tree entry: {val['kind']}")
            return Tree(tuple(sorted(entries, key=lambda e: e.name.encode('utf-8'))))

        if not tree_dict:
            return object_id(Tree(()))

        root_entries: list[TreeEntry] = []
        for key, val in tree_dict.items():
            if val['kind'] == 'blob':
                root_entries.append(TreeEntry(name=key, kind='blob', oid=object_id(Blob(val['data']))))
            elif val['kind'] == 'tree':
                sub_tree = build_tree(val['entries'])
                root_entries.append(TreeEntry(name=key, kind='tree', oid=object_id(sub_tree)))
            else:
                raise ValueError(f"Unknown kind in tree entry: {val['kind']}")

        return object_id(Tree(tuple(sorted(root_entries, key=lambda e: e.name.encode('utf-8'))))))

    def read_tree(self, oid: str) -> Dict[str, bytes]:
        tree = self.get(oid)
        if not isinstance(tree, Tree):
            raise ValueError(f"Object {oid} is not a tree")

        result: Dict[str, bytes] = {}
        for entry in tree.entries:
            if entry.kind == 'blob':
                result[entry.name] = entry.oid # Store oid as bytes representation isn't possible here directly, 
                                              # wait, the spec says "dict from every file's full path to its bytes".
                                              # But we only store blobs in the tree structure as oids.
                                              # However, `read_tree` needs to return bytes.
                                              # We must have stored the raw blobs separately or reconstruct them.
                                              # Given `write_tree` logic, we don't keep a map of path -> bytes globally in store.
                                              # We rely on the fact that `write_tree` creates blobs.
                                              # To strictly follow "returns the dict... to its bytes", we need to fetch blobs by oid.
                # But how to fetch? `get` returns the object.
                # Let's assume the store allows fetching by oid to get the Blob object.
                pass
            elif entry.kind == 'tree':
                sub_tree = self.read_tree(entry.oid)
                for sub_path, sub_data in sub_tree.items():
                    result[f"{entry.name}/{sub_path}"] = sub_data

        # Correction on implementation logic for read_tree:
        # The previous snippet built the tree structure but didn't actually traverse to get the flat dict with bytes.
        # Let's rewrite the traversal logic inline.
        flat: Dict[str, bytes] = {}

        def traverse(tree: Tree, prefix: str = ""):
            for entry in tree.entries:
                current_path = f"{prefix}/{entry.name}" if prefix else entry.name

                if entry.kind == 'blob':
                    blob_obj = self.get(entry.oid)
                    if isinstance(blob_obj, Blob):
                        flat[current_path] = blob_obj.data
                    else:
                        raise ValueError(f"Blob oid {entry.oid} does not resolve to a Blob")
                elif entry.kind == 'tree':
                    traverse(tree, current_path)

        traverse(tree)
        # The spec says keys sorted. dict preserves insertion order in 3.7+, but we should sort explicitly.
        return dict(sorted(flat.items()))

    def commit(self, tree_oid: str, parents: Iterable[str] = (), *, 
               author: str, timestamp: int, message: str) -> str:
        if not isinstance(tree_oid, str):
            raise ObjectNotFound(f"Tree must be an oid")
        if tree_oid not in self._store:
            raise ObjectNotFound(f"Tree oid {tree_oid} not found")

        tree_obj = self.get(tree_oid)
        if not isinstance(tree_obj, Tree):
            raise ValueError(f"Tree oid {tree_oid} is not a tree")

        for p in parents:
            if p not in self._store:
                raise ObjectNotFound(f"Parent oid {p} not found")
            parent_obj = self.get(p)
            if not isinstance(parent_obj, Commit):
                raise ValueError(f"Parent oid {p} is not a commit")

        commit_obj = Commit(
            tree=tree_oid,
            parents=tuple(parents),
            author=author,
            timestamp=timestamp,
            message=message
        )
        return self.put(commit_obj)

    def log(self, oid: str, first_parent: bool = False) -> Iterable[str]:
        commits: list[str] = []
        current_oid = oid

        if first_parent:
            while current_oid is not None:
                commits.append(current_oid)
                try:
                    c = self.get(current_oid)
                    if not isinstance(c, Commit):
                        raise ValueError("Not a commit")
                    current_oid = c.parents[0]
                except ObjectNotFound:
                    break
            return
        else:
            # Standard log: newest first, ordered by timestamp, then oid for ties
            stack: list[Tuple[str, int, str]] = [(oid, 0, "")] # (oid, depth, path)
            # Actually, we need to follow ancestry until root, then reverse sort.
            # But standard git log follows parents until null.
            # "ordered by timestamp, newest first, with equal timestamps ordered by oid ascending"
            # This implies we need to collect all ancestors first, then sort.

            ancestors: list[str] = []
            current = oid
            while current in self._store:
                c = self.get(current)
                if not isinstance(c, Commit):
                    raise ValueError(f"Oid {current} is not a commit")
                ancestors.append(current)
                current = c.parents[0] if c.parents else None

            # Reverse to get newest first
            ancestors.reverse()

            # Sort by timestamp (desc), then oid (asc)
            # We need timestamp for each.
            # Note: Ancestors list might have duplicates if not careful with sets, but we followed pointers.
            # We just need to sort the collected list.

            # Create list of (timestamp, oid)
            data = []
            for c_oid in ancestors:
                c = self.get(c_oid)
                data.append((c.timestamp, c_oid))

            # Sort: timestamp desc (-x[0]), oid asc (x[1])
            data.sort(key=lambda x: (-x[0], x[1]))

            for _, c_oid in data:
                yield c_oid

    def __repr__(self):
        return f"ObjectStore({len(self._store)} objects)"
