from typing import NamedTuple, Optional, Tuple, Iterable
from .store import ObjectStore
from .objects import Tree

class Change(NamedTuple):
    status: str
    path: str
    old: Optional[str]
    new: Optional[str]

def diff_trees(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> Iterable[Change]:
    old_tree = None
    if old_oid is not None:
        try:
            old_tree = store.get(old_oid)
        except ObjectNotFound:
            pass

    new_tree = None
    if new_oid is not None:
        try:
            new_tree = store.get(new_oid)
        except ObjectNotFound:
            pass

    # Flatten both trees into dicts of {path: oid}
    # For directories, we need to recurse.
    # Note: If a path exists in one but not the other, it's a change.

    def tree_to_dict(tree: Optional[Tree]) -> dict[str, Optional[str]]:
        if tree is None:
            return {}
        result: dict[str, Optional[str]] = {}

        def recurse(t: Tree, prefix: str = ""):
            for entry in t.entries:
                full_path = f"{prefix}/{entry.name}" if prefix else entry.name

                if entry.kind == 'blob':
                    result[full_path] = entry.oid
                elif entry.kind == 'tree':
                    recurse(t, full_path)

        recurse(tree)
        return result

    old_entries = tree_to_dict(old_tree)
    new_entries = tree_to_dict(new_tree)

    all_paths = sorted(set(old_entries.keys()) | set(new_entries.keys()))

    for path in all_paths:
        old_blob = old_entries.get(path)
        new_blob = new_entries.get(path)

        # Determine status
        if path not in old_entries and path in new_entries:
            # Added
            if new_blob is not None: # Should always be true if in dict
                yield Change(status='A', path=path, old=None, new=new_blob)
        elif path not in new_entries and path in old_entries:
            # Deleted
            yield Change(status='D', path=path, old=old_blob, new=None)
        else:
            # Present in both
            if old_blob != new_blob:
                yield Change(status='M', path=path, old=old_blob, new=new_blob)

def diff_commits(store: ObjectStore, old_oid: Optional[str], new_oid: Optional[str]) -> Iterable[Change]:
    # Diffs the trees of two commits
    try:
        old_tree = store.get(old_oid)
    except ObjectNotFound:
        old_tree = None

    try:
        new_tree = store.get(new_oid)
    except ObjectNotFound:
        new_tree = None

    yield from diff_trees(store, old_tree, new_tree)

def format_changes(changes: Iterable[Change]) -> str:
    return '\n'.join(f"{c.status}\t{c.path}\n" for c in changes)
